import { lazy } from "react"
import { createBrowserRouter, RouterProvider } from "react-router-dom"
import { MotionConfig, LazyMotion, domAnimation } from "framer-motion"
import LazyWrapper from "./components/Utils/LazyWrapper"
import { SidebarProvider } from "./context/SidebarContext"
import RootLayout from "./components/Layout/RootLayout"

// Static Pages
import Home from "./pages/Home"

// Lazy Pages
const Login = lazy(() => import("./pages/Login"))
const Register = lazy(() => import("./pages/Register"))
const RegisterSuccess = lazy(() => import("./pages/RegisterSuccess"))
const ForgotPassword = lazy(() => import("./pages/ForgotPassword"))
const ResetPassword = lazy(() => import("./pages/ResetPassword"))
const Verify = lazy(() => import("./pages/Verify"))
const Maintenance = lazy(() => import("./pages/Maintenance"))
const NotFound = lazy(() => import("./pages/NotFound"))

const PublicProfile = lazy(() => import("./pages/PublicProfile"))
const Account = lazy(() => import("./pages/Account"))
const Gacha = lazy(() => import("./pages/Gacha"))
const AdminPanel = lazy(() => import("./pages/AdminPanel"))
const MapPage = lazy(() => import("./pages/Map"))
const Status = lazy(() => import("./pages/Status"))

// Forum Lazy
const Forum = lazy(() => import("./pages/Forum"))
const ForumCategory = lazy(() => import("./pages/ForumCategory"))
const ForumThread = lazy(() => import("./pages/ForumThread"))
const CreateThread = lazy(() => import("./pages/CreateThread"))

// Support Lazy
const Support = lazy(() => import("./pages/Support"))
const TicketDetail = lazy(() => import("./pages/TicketDetail"))
const PolicyPage = lazy(() => import("./pages/PolicyPage"))
const Wiki = lazy(() => import("./pages/Wiki"))
const AboutRedesign = lazy(() => import("./pages/AboutRedesign"))
const LauncherPage = lazy(() => import("./pages/LauncherPage"))


const router = createBrowserRouter([
    {
        path: "/",
        element: <RootLayout />,
        errorElement: <LazyWrapper><NotFound /></LazyWrapper>,
        children: [
            { index: true, element: <Home /> },

            { path: "u/:username", element: <LazyWrapper><PublicProfile /></LazyWrapper> },
            { path: "account", element: <LazyWrapper minHeight="80vh"><Account /></LazyWrapper> },
            { path: "login", element: <LazyWrapper><Login /></LazyWrapper> },
            { path: "forgot-password", element: <LazyWrapper><ForgotPassword /></LazyWrapper> },
            { path: "reset-password", element: <LazyWrapper><ResetPassword /></LazyWrapper> },
            { path: "register", element: <LazyWrapper><Register /></LazyWrapper> },
            { path: "register/success", element: <LazyWrapper><RegisterSuccess /></LazyWrapper> },
            { path: "gacha", element: <LazyWrapper><Gacha /></LazyWrapper> },
            { path: "admin", element: <LazyWrapper minHeight="80vh"><AdminPanel /></LazyWrapper> },

            { path: "forum", element: <LazyWrapper><Forum /></LazyWrapper> },
            { path: "forum/create", element: <LazyWrapper><CreateThread /></LazyWrapper> },
            { path: "forum/:id", element: <LazyWrapper><ForumCategory /></LazyWrapper> },
            { path: "forum/thread/:id", element: <LazyWrapper><ForumThread /></LazyWrapper> },
            { path: "forum/thread/:type/:id", element: <LazyWrapper><ForumThread /></LazyWrapper> },
            { path: "map", element: <LazyWrapper><MapPage /></LazyWrapper> },
            { path: "status", element: <LazyWrapper><Status /></LazyWrapper> },

            { path: "support", element: <LazyWrapper><Support /></LazyWrapper> },
            { path: "support/:id", element: <LazyWrapper><TicketDetail /></LazyWrapper> },
            { path: "policies/:slug", element: <LazyWrapper><PolicyPage /></LazyWrapper> },
            { path: "wiki", element: <LazyWrapper><Wiki /></LazyWrapper> },
            { path: "wiki/:slug", element: <LazyWrapper><Wiki /></LazyWrapper> },
            { path: "about-redesign", element: <LazyWrapper><AboutRedesign /></LazyWrapper> },
            { path: "launcher", element: <LazyWrapper><LauncherPage /></LazyWrapper> },

            { path: "verify", element: <LazyWrapper><Verify /></LazyWrapper> },
            { path: "maintenance", element: <LazyWrapper><Maintenance /></LazyWrapper> },

            { path: "rules", element: <Home /> },
            { path: "donors", element: <Home /> },
            { path: "news", element: <Home /> },
            { path: "suggestions", element: <Home /> },
            { path: "contests", element: <Home /> },
            { path: "stories", element: <Home /> },


            { path: "*", element: <LazyWrapper><NotFound /></LazyWrapper> }
        ]
    }
])

export default function App() {
  return (
    <LazyMotion features={domAnimation}>
      <MotionConfig reducedMotion="never">
        <SidebarProvider>
            <RouterProvider router={router} />
        </SidebarProvider>
      </MotionConfig>
    </LazyMotion>
  )
}

import { describe, it, expect } from "vitest";
import { renderWithProviders } from "@/utils/test-utils";
import { AmbientBubbles } from "@/components/Launcher/AmbientBubbles";

describe("AmbientBubbles Component", () => {
  it("renders container with 22 animated ambient bubble elements", () => {
    const { container } = renderWithProviders(<AmbientBubbles />);

    const bubbleContainer = container.querySelector(".ambient-bubbles-container");
    expect(bubbleContainer).toBeInTheDocument();

    const bubbles = container.querySelectorAll(".ambient-bubble");
    expect(bubbles.length).toBe(22);
  });

  it("applies dynamic styles (width, height, left, duration, delay) to bubbles", () => {
    const { container } = renderWithProviders(<AmbientBubbles />);

    const bubbles = container.querySelectorAll(".ambient-bubble");
    const firstBubble = bubbles[0] as HTMLElement;

    expect(firstBubble.style.width).toMatch(/\d+(\.\d+)?px/);
    expect(firstBubble.style.height).toMatch(/\d+(\.\d+)?px/);
    expect(firstBubble.style.left).toMatch(/\d+(\.\d+)?vw/);
    expect(firstBubble.style.animationDuration).toMatch(/\d+(\.\d+)?s/);
    expect(firstBubble.style.animationDelay).toMatch(/\d+(\.\d+)?s/);
  });
});

﻿import type React from 'react';
import { describe, it, expect, vi, beforeEach, afterEach, type Mock } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import PremiumAlert from '@/components/UI/PremiumAlert';

vi.mock('framer-motion', () => ({
    motion: {
        div: ({ children, ...p }: { children?: React.ReactNode } & Record<string, unknown>) => <div {...(p as React.HTMLAttributes<HTMLDivElement>)}>{children}</div>,
        button: ({ children, ...p }: { children?: React.ReactNode } & Record<string, unknown>) => <button {...(p as React.ButtonHTMLAttributes<HTMLButtonElement>)}>{children}</button>
    },
    m: {
        div: ({ children, ...p }: { children?: React.ReactNode } & Record<string, unknown>) => <div {...(p as React.HTMLAttributes<HTMLDivElement>)}>{children}</div>,
        button: ({ children, ...p }: { children?: React.ReactNode } & Record<string, unknown>) => <button {...(p as React.ButtonHTMLAttributes<HTMLButtonElement>)}>{children}</button>
    },
    AnimatePresence: ({ children }: { children?: React.ReactNode }) => <>{children}</>
}));

vi.mock('react-i18next', () => ({
    useTranslation: () => ({
        t: (_key: string, defaultValue: string) => defaultValue
    })
}));

describe('PremiumAlert', () => {
    let onCloseMock: Mock;

    beforeEach(() => {
        onCloseMock = vi.fn();
    });

    afterEach(() => {
        vi.clearAllMocks();
    });

    it('should not render when isOpen is false', () => {
        render(<PremiumAlert isOpen={false} message="Test message" onClose={onCloseMock} />);
        expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
    });

    it('should render when isOpen is true', () => {
        render(<PremiumAlert isOpen={true} message="Test message" onClose={onCloseMock} />);
        expect(screen.getByRole('dialog')).toBeInTheDocument();
    });

    it('should render with the correct variant and icon', () => {
        render(<PremiumAlert isOpen={true} message="Test message" onClose={onCloseMock} variant="error" />);
        expect(screen.getByRole('img', { name: /alert circle/i })).toBeInTheDocument();
        expect(screen.getByRole('heading', { level: 3 }).textContent).toBe('Error');
    });

    it('should render with the default title when title prop is not provided', () => {
        render(<PremiumAlert isOpen={true} message="Test message" onClose={onCloseMock} variant="info" />);
        expect(screen.getByRole('heading', { level: 3 }).textContent).toBe('Información');
    });

    it('should render with the provided title when title prop is provided', () => {
        render(<PremiumAlert isOpen={true} title="Custom Title" message="Test message" onClose={onCloseMock} variant="success" />);
        expect(screen.getByRole('heading', { level: 3 }).textContent).toBe('Custom Title');
    });

    it('should call onClose when the close button is clicked', async () => {
        render(<PremiumAlert isOpen={true} message="Test message" onClose={onCloseMock} />);
        const closeButton = screen.getByRole('button', { name: /action/i });
        await userEvent.click(closeButton);
        expect(onCloseMock).toHaveBeenCalled();
    });

    it('should call onClose when the accept button is clicked', async () => {
        render(<PremiumAlert isOpen={true} message="Test message" onClose={onCloseMock} />);
        const acceptButton = screen.getByRole('button', { name: /aceptar/i });
        await userEvent.click(acceptButton);
        expect(onCloseMock).toHaveBeenCalled();
    });

    it('should render with the correct styles for the accept button based on variant', () => {
        render(<PremiumAlert isOpen={true} message="Test message" onClose={onCloseMock} variant="warning" />);
        const acceptButton = screen.getByRole('button', { name: /aceptar/i });
        expect(acceptButton).toHaveStyle('color: #000');
    });

    it('should render with the correct styles for the accept button based on variant', () => {
        render(<PremiumAlert isOpen={true} message="Test message" onClose={onCloseMock} variant="info" />);
        const acceptButton = screen.getByRole('button', { name: /aceptar/i });
        expect(acceptButton).toHaveStyle('color: #fff');
    });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useForumThread } from '../../hooks/useForumThread';
import * as AuthContext from '../../context/AuthContext';
import * as ReactRouter from 'react-router-dom';
import * as ReactQuery from '@tanstack/react-query';

vi.mock('../../context/AuthContext', () => ({
  useAuth: vi.fn(),
}));

vi.mock('react-router-dom', () => ({
  useParams: vi.fn(),
  useNavigate: vi.fn(),
}));

vi.mock('@tanstack/react-query', () => ({
  useQuery: vi.fn(),
}));

vi.mock('react-i18next', () => ({
  useTranslation: () => ({
    t: (k: string, defaultVal?: string) => defaultVal || k,
    i18n: { language: 'es' },
  }),
}));

describe('useForumThread Hook', () => {
  const mockNavigate = vi.fn();

  beforeEach(() => {
    vi.clearAllMocks();
    vi.mocked(ReactRouter.useNavigate).mockReturnValue(mockNavigate);
    vi.mocked(ReactRouter.useParams).mockReturnValue({ type: 'topic', id: 'sample-thread' });
    vi.mocked(ReactQuery.useQuery).mockReturnValue({
      data: {
        thread: {
          id: 'sample-thread',
          title: 'Sample Thread Title',
          content: 'Sample thread content body',
          author: 'TestUser',
          author_id: 'user-123',
          author_avatar: null,
          author_role: 'user',
          date: '01/10/2026',
          longDate: '01/10/2026 12:00',
          image: null,
          tag: 'General',
          category_id: 2,
          views: 42,
          poll: null,
          pinned: false,
          locked: false,
        },
        comments: [
          {
            id: 'c1',
            user: 'Commenter',
            user_id: 'user-456',
            avatar: null,
            role: 'user',
            date: '01/10/2026',
            content: 'First comment',
          },
        ],
      },
      isLoading: false,
      error: null,
    } as any);
  });

  it('determines admin privileges correctly', () => {
    vi.mocked(AuthContext.useAuth).mockReturnValue({
      user: {
        id: 'admin-1',
        user_metadata: { role: 'admin', username: 'SuperAdmin' },
      },
    } as any);

    const { result } = renderHook(() => useForumThread());
    expect(result.current.isAdmin).toBe(true);
    expect(result.current.isOwnerOrAdmin('any-user-id')).toBe(true);
  });

  it('identifies non-admin owner privileges correctly', () => {
    vi.mocked(AuthContext.useAuth).mockReturnValue({
      user: {
        id: 'user-123',
        user_metadata: { role: 'user', username: 'NormalUser' },
      },
    } as any);

    const { result } = renderHook(() => useForumThread());
    expect(result.current.isAdmin).toBe(false);
    expect(result.current.isOwnerOrAdmin('user-123')).toBe(true);
    expect(result.current.isOwnerOrAdmin('other-id')).toBe(false);
  });

  it('opens delete confirmation modal for thread and comment', () => {
    vi.mocked(AuthContext.useAuth).mockReturnValue({
      user: { id: 'admin-1', user_metadata: { role: 'admin' } },
    } as any);

    const { result } = renderHook(() => useForumThread());

    act(() => {
      result.current.handleDeleteThread();
    });
    expect(result.current.deleteModal).toEqual({ type: 'thread', id: 'sample-thread' });

    act(() => {
      result.current.handleDeletePost('c1');
    });
    expect(result.current.deleteModal).toEqual({ type: 'post', id: 'c1' });

    act(() => {
      result.current.closeDeleteModal();
    });
    expect(result.current.deleteModal).toBeNull();
  });

  it('handles inline edit mode state transitions', () => {
    vi.mocked(AuthContext.useAuth).mockReturnValue({
      user: { id: 'user-123', user_metadata: { role: 'user' } },
    } as any);

    const { result } = renderHook(() => useForumThread());

    act(() => {
      result.current.startEditThread();
    });
    expect(result.current.isEditingThread).toBe(true);
    expect(result.current.editThreadData.title).toBe('Sample Thread Title');

    act(() => {
      result.current.cancelEditThread();
    });
    expect(result.current.isEditingThread).toBe(false);
  });
});

