import React, { useEffect, useRef, useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useTranslation } from "react-i18next";
import {
  Medal,
  X,
  LogOut,
  Trophy,
  LayoutDashboard,
  Camera,
  PenTool,
  MessageSquare,
  Shield,
  Link as LinkIcon,
  Settings,
} from "lucide-react";
import { useAuth } from "../../context/AuthContext";
import { uploadImage } from "../../services/uploadService";
import { compressImage } from "../../utils/imageOptimizer";
import Loader from "../UI/Loader";
import { User } from "@supabase/supabase-js";
import { isAdmin as checkAdmin } from "../../utils/roleUtils";
import { useGachaBalance } from "../../hooks/useAccountData";

interface NavButtonProps {
  active: boolean;
  onClick: () => void;
  icon: React.ReactNode;
  label: string;
}

const NavButton = ({ active, onClick, icon, label }: NavButtonProps) => (
  <button
    type="button"
    onClick={onClick}
    className={`group flex w-full items-center gap-4 rounded-2xl px-6 py-4 transition-colors ${active ? "bg-(--accent)/10 text-(--accent) shadow-(--accent)/5 shadow-lg" : "text-gray-400 hover:bg-white/5 hover:text-white"}`}
  >
    <span
      className={`text-lg transition-transform group-hover:scale-110 ${active ? "text-(--accent)" : "text-gray-500"}`}
      aria-hidden="true"
    >
      {icon}
    </span>
    <span className="text-xs font-black uppercase tracking-widest">
      {label}
    </span>
  </button>
);

interface AccountSidebarProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  user: User;
  statsData?: { username?: string };
  mcUsername: string;
  isLinked: boolean;
  isOpen?: boolean;
  onClose?: () => void;
}

const AccountSidebar: React.FC<AccountSidebarProps> = ({
  activeTab,
  setActiveTab,
  user,
  statsData,
  mcUsername,
  isLinked,
  isOpen,
  onClose,
}) => {
  const { t } = useTranslation();
  const { logout, updateUser } = useAuth();
  const navigate = useNavigate();

  const [uploading, setUploading] = useState(false);
  const [isEditingName, setIsEditingName] = useState(false);
  const [newName, setNewName] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);
  const nameInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isEditingName) {
      nameInputRef.current?.focus();
    }
  }, [isEditingName]);

  const isAdmin = checkAdmin(user);
  const { data: authoritativeBalance } = useGachaBalance(user?.id);

  const handleLogout = async () => {
    await logout();
    navigate("/");
  };

  const handleAvatarClick = () => {
    if (fileInputRef.current) fileInputRef.current.click();
  };

  const handleAvatarUpload = async (
    event: React.ChangeEvent<HTMLInputElement>,
  ) => {
    try {
      setUploading(true);
      if (!event.target.files || event.target.files.length === 0) return;

      const file = event.target.files[0];
      const compressedBlob = await compressImage(file);

      // Server-validated upload (backend namespaces the file under user.id)
      const publicUrl = await uploadImage(compressedBlob, "avatars");
      await updateUser({ avatar_url: publicUrl });
    } catch (error) {
      console.error("Avatar upload error:", error);
    } finally {
      setUploading(false);
    }
  };

  const handleNameUpdate = async () => {
    if (!newName.trim()) return setIsEditingName(false);
    try {
      await updateUser({
        full_name: newName.trim(),
        username: newName.trim(),
      });
      setIsEditingName(false);
    } catch {
      alert(t("account.name.error_update"));
    }
  };

  const handleNav = (tab: string) => {
    setActiveTab(tab);
    if (onClose) onClose();
  };

  return (
    <aside
      className={`w-75 z-200 lg:rounded-4xl fixed inset-y-0 left-0 border border-white/10 bg-[#0a0a0a]/90 backdrop-blur-2xl transition-transform duration-500 lg:sticky lg:top-24 lg:z-50 lg:h-[calc(100vh-120px)] lg:translate-x-0 ${isOpen ? "translate-x-0 shadow-2xl shadow-black" : "-translate-x-full"}`}
    >
      <button
        aria-label={t("common.close", "Cerrar menú")}
        type="button"
        className="absolute right-6 top-6 flex h-10 w-10 items-center justify-center rounded-xl bg-white/5 text-gray-400 transition-colors hover:bg-white/10 lg:hidden"
        onClick={onClose}
      >
        <X size={18} />
      </button>

      <div className="flex h-full flex-col p-8">
        {/* User Header */}
        <div className="mb-8 flex flex-col items-center text-center">
          <div
            className="group/avatar relative mb-5 cursor-pointer"
            onClick={handleAvatarClick}
            role="button"
            tabIndex={0}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                handleAvatarClick();
              }
            }}
          >
            <div className="bg-linear-to-tr from-(--accent)/40 ring-(--accent)/30 group-hover/avatar:ring-(--accent)/70 relative h-24 w-24 overflow-hidden rounded-full via-white/10 to-white/5 p-1 shadow-2xl ring-2 transition-colors duration-300">
              {uploading ? (
                <div className="absolute inset-0 flex items-center justify-center bg-black/70 backdrop-blur-md">
                  <Loader minimal />
                </div>
              ) : (
                <img
                  src={
                    user?.user_metadata?.avatar_preference === "social" &&
                    user?.user_metadata?.avatar_url
                      ? user.user_metadata.avatar_url
                      : isLinked
                        ? `https://mc-heads.net/avatar/${statsData?.username || mcUsername}/128`
                        : "https://ui-avatars.com/api/?name=" +
                          (user?.user_metadata?.full_name || "User")
                  }
                  alt="Avatar"
                  className="h-full w-full rounded-full object-cover transition-transform duration-500 group-hover/avatar:scale-105"
                />
              )}
              <div className="absolute inset-0 flex items-center justify-center rounded-full bg-black/50 opacity-0 transition-opacity duration-300 group-hover/avatar:opacity-100">
                <Camera className="text-xl text-white" />
              </div>
            </div>
            <div className="group-hover/avatar:border-(--accent)/40 animate-spin-slow pointer-events-none absolute -inset-2 rounded-full border border-dashed border-white/10 transition-colors"></div>
          </div>

          <input
            aria-label={t("account.upload_avatar", "Subir avatar")}
            type="file"
            ref={fileInputRef}
            onChange={handleAvatarUpload}
            className="hidden"
            accept="image/*"
          />

          <div className="space-y-1">
            {isEditingName ? (
              <div className="flex items-center gap-2">
                <input
                  ref={nameInputRef}
                  aria-label={t("account.edit_name", "Editar nombre")}
                  value={newName}
                  onChange={(e) => setNewName(e.target.value)}
                  className="focus:border-(--accent)/40 w-32 rounded-lg border border-white/10 bg-white/5 px-3 py-1.5 text-sm font-bold text-white focus:outline-none"
                />
                <button
                  aria-label={t("common.save", "Guardar")}
                  type="button"
                  onClick={handleNameUpdate}
                  className="bg-(--accent) shadow-(--accent)/20 rounded-lg p-2 text-[10px] font-black uppercase text-black shadow-lg"
                >
                  {t("common.save", "Guardar")}
                </button>
              </div>
            ) : (
              <h3 className="group/name flex items-center justify-center gap-2 text-lg font-black uppercase tracking-tighter text-white">
                {user?.user_metadata?.full_name || mcUsername}
                <PenTool
                  className="cursor-pointer text-[10px] text-gray-600 transition-colors group-hover/name:text-white"
                  onClick={() => {
                    setNewName(user?.user_metadata?.full_name || "");
                    setIsEditingName(true);
                  }}
                />
              </h3>
            )}
            <p className="max-w-45 truncate text-[10px] font-bold uppercase tracking-widest text-gray-500">
              {user?.email}
            </p>

            {user?.user_metadata?.status_message && (
              <div className="mt-3 flex max-w-full items-center justify-center gap-2 rounded-xl border border-white/5 bg-white/5 px-3.5 py-1.5 backdrop-blur-md">
                <div className="h-1.5 w-1.5 shrink-0 animate-pulse rounded-full bg-green-400 shadow-[0_0_8px_rgba(74,222,128,0.6)]" />
                <p className="max-w-45 truncate text-[10px] font-bold italic text-gray-300">
                  "{user.user_metadata.status_message}"
                </p>
              </div>
            )}

            {/* 🪙 Compact KilluCoins (KC) Balance Pill */}
            <div className="mt-3 flex w-full items-center justify-between gap-3 rounded-xl border border-amber-500/20 bg-amber-500/10 px-4 py-2 backdrop-blur-md">
              <span className="flex items-center gap-1.5 text-[10px] font-black uppercase tracking-wider text-amber-400">
                <img
                  src="/images/killucoin.png"
                  alt="KC"
                  className="h-4 w-4 object-contain [image-rendering:pixelated]"
                  onError={(e) => {
                    (e.target as HTMLImageElement).style.display = "none";
                  }}
                />
                <span>KilluCoins</span>
              </span>
              <span className="font-mono text-xs font-black text-amber-300">
                {(
                  (authoritativeBalance !== undefined &&
                  authoritativeBalance !== null
                    ? authoritativeBalance
                    : user?.user_metadata?.gacha_balance) ?? 0
                ).toLocaleString()}{" "}
                KC
              </span>
            </div>
          </div>

          {isAdmin && (
            <Link
              to="/admin"
              className="mt-5 flex items-center gap-2 rounded-xl border border-red-500/20 bg-red-500/10 px-5 py-2 text-[10px] font-black uppercase tracking-widest text-red-400 shadow-lg shadow-red-500/5 transition-colors hover:bg-red-500/20 active:scale-95"
            >
              <Shield size={14} /> {t("account.admin_panel")}
            </Link>
          )}
        </div>

        {/* Nav Links */}
        <nav className="flex-1 space-y-1.5 overflow-y-auto pb-24 pr-1 [-ms-overflow-style:none] [scrollbar-width:none] lg:pb-0 [&::-webkit-scrollbar]:hidden">
          <NavButton
            active={activeTab === "overview"}
            onClick={() => handleNav("overview")}
            icon={<LayoutDashboard size={18} />}
            label={t("account.nav.overview")}
          />
          <NavButton
            active={activeTab === "posts"}
            onClick={() => handleNav("posts")}
            icon={<MessageSquare size={18} />}
            label={t("account.nav.posts")}
          />
          <NavButton
            active={activeTab === "medals"}
            onClick={() => handleNav("medals")}
            icon={<Medal size={18} />}
            label={t("account.nav.medals", "Medallas")}
          />
          <NavButton
            active={activeTab === "achievements"}
            onClick={() => handleNav("achievements")}
            icon={<Trophy size={18} />}
            label={t("account.nav.achievements")}
          />
          <NavButton
            active={activeTab === "connections"}
            onClick={() => handleNav("connections")}
            icon={<LinkIcon size={18} />}
            label={t("account.nav.connections")}
          />
          <NavButton
            active={activeTab === "settings"}
            onClick={() => handleNav("settings")}
            icon={<Settings size={18} />}
            label={t("account.nav.settings", "Configuración")}
          />
        </nav>

        <div className="mt-4 border-t border-white/5 pt-5">
          <button
            type="button"
            onClick={handleLogout}
            className="flex w-full items-center gap-4 rounded-2xl px-6 py-3.5 text-[10px] font-black uppercase tracking-widest text-red-400/70 transition-colors hover:bg-red-500/10 hover:text-red-400 active:scale-95"
          >
            <LogOut size={16} /> {t("account.nav.logout")}
          </button>
        </div>
      </div>
    </aside>
  );
};

export default AccountSidebar;

import React from 'react';
import { Medal, Lock, Share2 } from 'lucide-react';

export interface AchievementCardProps {
    title: string;
    description: string;
    icon: React.ReactNode;
    unlocked: boolean;
    criteria?: string;
    onShare?: () => void;
    color?: string;
}

const AchievementCard = ({ title, description, icon, unlocked, criteria, onShare, color = '#4CAF50' }: AchievementCardProps) => (
    <div 
        className={`group relative flex flex-col items-center text-center p-8 rounded-4xl transition-colors duration-500 overflow-hidden ${unlocked ? 'bg-white/5 border border-white/5 hover:bg-white/10 hover:-translate-y-1' : 'bg-transparent border border-dashed border-white/10 opacity-60'}`}
        style={{ '--accent-color': color } as React.CSSProperties}
    >
        {/* Background Glow */}
        {unlocked && (
            <div 
                className="absolute inset-0 opacity-0 group-hover:opacity-10 transition-opacity pointer-events-none"
                style={{ background: `radial-gradient(circle at center, ${color} 0%, transparent 70%)` }}
            />
        )}

        {/* Status Badges */}
        <div className="absolute top-6 right-6 flex flex-col gap-2">
            {unlocked ? (
                <>
                    <div 
                        className="w-9 h-9 flex items-center justify-center bg-white/5 rounded-full"
                        style={{ color }}
                    >
                        <Medal size={14} className="drop-shadow-[0_0_8px_currentColor]" />
                    </div>
                    {onShare && (
                        <button type="button" 
                            onClick={(e) => { e.stopPropagation(); onShare(); }}
                            className="w-9 h-9 flex items-center justify-center bg-white/5 border border-white/10 rounded-full text-white transition-colors hover:bg-(--accent-color) hover:text-black hover:scale-110 active:scale-90"
                            title="Compartir Logro"
                        >
                            <Share2 size={12} />
                        </button>
                    )}
                </>
            ) : (
                <div className="w-9 h-9 flex items-center justify-center bg-white/2 rounded-full text-gray-700">
                    <Lock size={12} />
                </div>
            )}
        </div>

        {/* Icon Container */}
        <div className={`relative w-20 h-20 flex items-center justify-center rounded-3xl mb-6 transition-colors duration-500 ${unlocked ? 'bg-white/5 border border-white/10 shadow-2xl group-hover:scale-110' : 'bg-white/2 border border-white/5 grayscale opacity-30 shadow-none'}`}>
             <div className="text-4xl">
                {icon}
             </div>
             {unlocked && (
                <div 
                    className="absolute inset-0 rounded-3xl opacity-20 blur-xl pointer-events-none"
                    style={{ backgroundColor: color }}
                />
             )}
        </div>

        {/* Text Content */}
        <div className="space-y-3">
            <h3 className={`text-lg font-black uppercase tracking-tighter transition-colors ${unlocked ? 'text-white' : 'text-gray-600'}`}>
                {title}
            </h3>
            <p className={`text-xs font-medium leading-relaxed max-w-[180px] mx-auto transition-colors ${unlocked ? 'text-gray-400' : 'text-gray-700'}`}>
                {description}
            </p>

            {!unlocked && criteria && (
                <div className="mt-4 inline-block px-3 py-1 bg-black/40 rounded-lg border border-white/5">
                    <p className="text-[10px] font-black uppercase tracking-widest text-gray-700 italic">
                        🔒 {criteria}
                    </p>
                </div>
            )}
        </div>

        {/* Progress Line (Decorative) */}
        {unlocked && (
            <div 
                className="absolute bottom-0 left-0 h-[2px] w-0 group-hover:w-full transition-colors duration-700 ease-out"
                style={{ backgroundColor: color }}
            />
        )}
    </div>
)

export default AchievementCard;

import React, { useState, useEffect, useRef } from 'react';
import { Gamepad2, ChevronDown, ChevronUp, Copy, ExternalLink, Check } from 'lucide-react';
import { UserIdentity } from '@supabase/supabase-js';
import Loader from '../UI/Loader';
import { useTranslation } from 'react-i18next';
import {
    openMicrosoftOAuthPopup,
    exchangeMicrosoftAuthCode,
    formatUuidWithHyphens,
    MicrosoftDeviceCode
} from '../../services/microsoftAuthWeb';

export interface ConnectionCardsProps {
    isLinked: boolean;
    mcUsername: string | undefined;
    statsDataUsername: string | undefined;
    linkCode: string | null;
    linkLoading: boolean;
    onGenerateCode: () => void;
    discordIdentity?: UserIdentity;
    isDiscordLinked?: boolean;
    discordMetadataName?: string;
    discordMetadataAvatar?: string;
    twitchIdentity?: UserIdentity;
    onLinkProvider: (provider: string) => void;
    onUnlinkProvider: (identity: UserIdentity) => void;
    onUnlinkMinecraft: () => void;
    onUnlinkDiscord: () => void;
    manualCode?: string;
    onManualCodeChange?: (val: string) => void;
    onVerifyCode?: () => void;
    isVerifying?: boolean;
    discordManualCode?: string;
    onDiscordManualCodeChange?: (val: string) => void;
    onVerifyDiscordCode?: () => void;
    isVerifyingDiscord?: boolean;
    onLinkMicrosoft?: (data: { uuid: string; nick: string }) => void;
}

const ConnectionCards: React.FC<ConnectionCardsProps> = ({
    isLinked,
    mcUsername,
    statsDataUsername,
    linkCode,
    linkLoading,
    onGenerateCode,
    discordIdentity,
    isDiscordLinked,
    discordMetadataName,
    discordMetadataAvatar,
    twitchIdentity,
    onLinkProvider,
    onUnlinkProvider,
    onUnlinkMinecraft,
    onUnlinkDiscord,
    manualCode,
    onManualCodeChange,
    onVerifyCode,
    isVerifying,
    discordManualCode,
    onDiscordManualCodeChange,
    onVerifyDiscordCode,
    isVerifyingDiscord,
    onLinkMicrosoft
}) => {
    const { t } = useTranslation();

    // Microsoft Auth States
    const [msAuthLoading, setMsAuthLoading] = useState(false);
    const [msDeviceCode] = useState<MicrosoftDeviceCode | null>(null);
    const [msStatusMsg, setMsStatusMsg] = useState("");
    const [msErrorMsg, setMsErrorMsg] = useState<string | null>(null);
    const [copiedCode, setCopiedCode] = useState(false);

    // No-Premium Section Toggle State
    const [showNoPremiumSection, setShowNoPremiumSection] = useState(false);

    const [popupWindow, setPopupWindow] = useState<Window | null>(null);

    const onLinkMicrosoftRef = useRef(onLinkMicrosoft);
    useEffect(() => {
        onLinkMicrosoftRef.current = onLinkMicrosoft;
    }, [onLinkMicrosoft]);

    useEffect(() => {
        if (!popupWindow) return;

        const messageHandler = async (event: MessageEvent) => {
            if (event.origin !== window.location.origin) return;
            if (event.data?.type === "MS_AUTH_CODE" && event.data?.code) {
                setMsStatusMsg("Autenticando con Microsoft y Xbox Live...");
                try {
                    const profile = await exchangeMicrosoftAuthCode(event.data.code);
                    const formattedUuid = formatUuidWithHyphens(profile.id);
                    if (onLinkMicrosoftRef.current) {
                        onLinkMicrosoftRef.current({ uuid: formattedUuid, nick: profile.name });
                    }
                } catch (err: unknown) {
                    console.error("Microsoft popup auth error:", err);
                    const msg = err instanceof Error ? err.message : String(err);
                    setMsErrorMsg(msg || "Error al autenticar con Microsoft");
                } finally {
                    setMsAuthLoading(false);
                    setPopupWindow(null);
                }
            }
        };

        window.addEventListener("message", messageHandler);

        const timer = setInterval(() => {
            if (popupWindow.closed) {
                setMsAuthLoading(false);
                setPopupWindow(null);
            }
        }, 1000);

        return () => {
            clearInterval(timer);
            window.removeEventListener("message", messageHandler);
        };
    }, [popupWindow]);

    const handleStartMicrosoftLink = () => {
        setMsAuthLoading(true);
        setMsErrorMsg(null);
        setMsStatusMsg("Abriendo ventana de inicio de sesión de Microsoft...");

        const popup = openMicrosoftOAuthPopup();
        setPopupWindow(popup);
    };

    const handleCopyMsCode = () => {
        if (!msDeviceCode) return;
        navigator.clipboard.writeText(msDeviceCode.user_code);
        setCopiedCode(true);
        setTimeout(() => setCopiedCode(false), 2000);
        window.open(msDeviceCode.verification_uri || "https://microsoft.com/link", "_blank", "noopener,noreferrer");
    };

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">

            {/* Minecraft Card */}
            <div className="group relative flex flex-col bg-white/5 border border-green-500/20 rounded-4xl p-8 backdrop-blur-3xl overflow-hidden transition-colors hover:bg-white/10 hover:border-green-500/50 hover:shadow-[0_0_30px_rgba(34,197,94,0.1)] hover:-translate-y-1">
                <div className="flex items-center gap-5 mb-8">
                    <div className="relative">
                        {isLinked ? (
                            <img 
                                src={`https://mc-heads.net/avatar/${statsDataUsername || mcUsername}`} 
                                alt={mcUsername}
                                className="w-16 h-16 rounded-2xl object-contain bg-black/40 border-2 border-green-500/30 shadow-2xl"
                            />
                        ) : (
                            <div className="w-16 h-16 bg-green-500/20 rounded-2xl flex items-center justify-center text-green-400 text-3xl">
                                <Gamepad2 size={32} />
                            </div>
                        )}
                        <div className="absolute -bottom-2 -right-2 bg-[#1a1a1a] p-1.5 rounded-xl border border-white/10 shadow-xl">
                            <img 
                                src="/images/ui/minecraft_logo_icon_168974.png" 
                                alt="MC" 
                                className="w-5 h-5 object-contain" 
                            />
                        </div>
                    </div>

                    <div>
                        <h3 className="text-xl font-black uppercase tracking-tighter text-white">Minecraft</h3>
                        <p className="text-sm font-bold text-gray-500 uppercase tracking-widest">
                            {isLinked ? mcUsername : t('account.connections.not_linked')}
                        </p>
                    </div>
                </div>

                <div className="mt-auto space-y-4">
                    {isLinked ? (
                        <button 
                            type="button"
                            onClick={onUnlinkMinecraft}
                            className="w-full py-4 bg-red-500/10 border border-red-500/20 text-red-400 font-black uppercase tracking-widest rounded-2xl hover:bg-red-500/20 active:scale-95 transition-colors text-xs"
                        >
                            {t('account.connections.unlink')}
                        </button>
                    ) : (
                        <div className="space-y-4">
                            {/* Premium Microsoft Link Button */}
                            {!msDeviceCode ? (
                                <button 
                                    type="button"
                                    onClick={handleStartMicrosoftLink} 
                                    disabled={msAuthLoading}
                                    className="w-full py-4 bg-emerald-500 hover:bg-emerald-400 text-black font-black uppercase tracking-widest rounded-2xl hover:scale-[1.02] active:scale-95 transition-colors shadow-xl shadow-emerald-500/20 disabled:opacity-50 text-xs flex items-center justify-center gap-2"
                                >
                                    {msAuthLoading ? (
                                        <Loader minimal />
                                    ) : (
                                        <>
                                            <svg width="16" height="16" viewBox="0 0 23 23" fill="currentColor">
                                                <path fill="#f35325" d="M1 1h10v10H1z"/>
                                                <path fill="#81bc06" d="M12 1h10v10H12z"/>
                                                <path fill="#05a6f0" d="M1 12h10v10H1z"/>
                                                <path fill="#ffba08" d="M12 12h10v10H12z"/>
                                            </svg>
                                            <span>Vincular Premium (Microsoft)</span>
                                        </>
                                    )}
                                </button>
                            ) : (
                                /* Microsoft Device Code Dialog */
                                <div className="bg-black/60 border border-emerald-500/40 rounded-3xl p-5 text-center animate-fade-in space-y-3">
                                    <p className="text-[11px] font-bold text-gray-300 uppercase tracking-widest">
                                        Introduce este código en Microsoft:
                                    </p>
                                    <code className="block bg-emerald-950/60 text-emerald-300 py-2.5 rounded-xl text-xl font-black tracking-widest border border-emerald-500/30">
                                        {msDeviceCode.user_code}
                                    </code>

                                    <button aria-label="Action"
                                        type="button"
                                        onClick={handleCopyMsCode}
                                        className="w-full py-2.5 bg-emerald-500/20 hover:bg-emerald-500/30 border border-emerald-500/40 text-emerald-300 text-xs font-extrabold rounded-xl transition-colors flex items-center justify-center gap-2"
                                    >
                                        {copiedCode ? <Check size={14} /> : <Copy size={14} />}
                                        <span>{copiedCode ? "¡Código copiado!" : "Copiar e ir a Microsoft"}</span>
                                        <ExternalLink size={14} />
                                    </button>

                                    <div className="flex items-center justify-center gap-2 pt-1 text-gray-400 text-[10.5px]">
                                        <Loader minimal />
                                        <span>{msStatusMsg || "Esperando autorización..."}</span>
                                    </div>
                                </div>
                            )}

                            {msErrorMsg && (
                                <div className="p-3 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 text-xs text-center font-semibold">
                                    ⚠️ {msErrorMsg}
                                </div>
                            )}

                            {/* Section for No-Premium accounts */}
                            <div className="border-t border-white/10 pt-3">
                                <button
                                    type="button"
                                    onClick={() => setShowNoPremiumSection(!showNoPremiumSection)}
                                    aria-expanded={showNoPremiumSection}
                                    aria-label="Alternar sección de cuenta No-Premium"
                                    className="w-full flex items-center justify-between text-[11px] font-bold text-gray-400 hover:text-white transition-colors py-1 px-1"
                                >
                                    <span>¿Usas cuenta No-Premium / Offline?</span>
                                    {showNoPremiumSection ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
                                </button>

                                {showNoPremiumSection && (
                                    <div className="mt-3 space-y-4 animate-fade-in">
                                        {!linkCode ? (
                                            <>
                                                <button aria-label="Action" 
                                                    type="button"
                                                    onClick={onGenerateCode} 
                                                    disabled={linkLoading}
                                                    className="w-full py-3 bg-white/10 hover:bg-white/20 text-white font-bold uppercase tracking-widest rounded-2xl transition-colors disabled:opacity-50 text-[11px]"
                                                >
                                                    {linkLoading ? <Loader minimal /> : "Generar código en servidor (/link)"}
                                                </button>

                                                <div className="flex gap-2">
                                                    <input aria-label="Input field" 
                                                        type="text" 
                                                        placeholder="CÓDIGO 6 DÍGITOS"
                                                        value={manualCode}
                                                        onChange={(e) => onManualCodeChange?.(e.target.value)}
                                                        className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-4 py-2.5 text-xs font-bold text-white placeholder:text-gray-600 focus:outline-none focus:border-white/20 transition-colors"
                                                    />
                                                    <button aria-label="Action" 
                                                        type="button"
                                                        onClick={onVerifyCode}
                                                        disabled={isVerifying || !manualCode}
                                                        className="px-5 bg-white/10 hover:bg-white/20 text-white font-black uppercase tracking-widest rounded-2xl transition-colors disabled:opacity-30 text-[10px]"
                                                    >
                                                        {isVerifying ? <Loader minimal /> : '✓'}
                                                    </button>
                                                </div>
                                            </>
                                        ) : (
                                            <div className="bg-white/5 border border-dashed border-green-500/40 rounded-3xl p-5 text-center animate-fade-in">
                                                <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Escribe esto en el chat del servidor:</p>
                                                <code className="block bg-black/60 text-green-400 py-2.5 rounded-xl text-base font-black tracking-widest border border-green-500/20 mb-3 shadow-2xl">
                                                    /link {linkCode}
                                                </code>
                                                <div className="flex items-center justify-center gap-2">
                                                    <Loader minimal />
                                                    <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest">{t('account.connections.waiting')}</span>
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                )}
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {/* Discord Card */}
            <div className="group relative flex flex-col bg-white/5 border border-[#5865F2]/20 rounded-4xl p-8 backdrop-blur-3xl overflow-hidden transition-colors hover:bg-white/10 hover:border-[#5865F2]/50 hover:shadow-[0_0_30px_rgba(88,101,242,0.1)] hover:-translate-y-1">
                <div className="flex items-center gap-5 mb-8">
                    <div className="relative">
                        {isDiscordLinked && (discordIdentity?.identity_data?.avatar_url || discordIdentity?.identity_data?.image_url || discordIdentity?.identity_data?.picture || discordMetadataAvatar) ? (
                            <img 
                                src={discordIdentity?.identity_data?.avatar_url || discordIdentity?.identity_data?.image_url || discordIdentity?.identity_data?.picture || discordMetadataAvatar} 
                                alt="Discord"
                                className="w-16 h-16 rounded-full object-cover border-2 border-[#5865F2]/30 shadow-2xl"
                            />
                        ) : (
                            <div className="w-16 h-16 bg-[#5865F2]/20 rounded-full flex items-center justify-center text-[#5865F2] text-3xl">
                                <svg viewBox="0 0 24 24" fill="currentColor" className="w-8 h-8">
                                    <path d="M20.317 4.37a19.791 19.791 0 0 0-4.885-1.515.074.074 0 0 0-.079.037c-.21.375-.444.864-.608 1.25a18.27 18.27 0 0 0-5.487 0 12.64 12.64 0 0 0-.617-1.25.077.077 0 0 0-.079-.037A19.736 19.736 0 0 0 3.677 4.37a.07.07 0 0 0-.032.027C.533 9.046-.32 13.58.099 18.057a.082.082 0 0 0 .031.057 19.9 19.9 0 0 0 5.993 3.03.078.078 0 0 0 .084-.028 14.09 14.09 0 0 0 1.226-1.994.076.076 0 0 0-.041-.106 13.107 13.107 0 0 1-1.872-.892.077.077 0 0 1-.008-.128c.125-.094.249-.192.37-.291a.074.074 0 0 1 .077-.01c3.928 1.793 8.18 1.793 12.062 0a.074.074 0 0 1 .078.01c.12.098.246.198.37.292a.077.077 0 0 1-.006.127 12.299 12.299 0 0 1-1.873.892.077.077 0 0 0-.041.107c.36.698.772 1.362 1.225 1.993a.076.076 0 0 0 .084.028 19.839 19.839 0 0 0 6.002-3.03.077.077 0 0 0 .032-.054c.5-5.177-.838-9.674-3.549-13.66a.061.061 0 0 0-.031-.03zM8.02 15.33c-1.183 0-2.157-1.085-2.157-2.419 0-1.333.955-2.419 2.157-2.419 1.21 0 2.176 1.096 2.157 2.42 0 1.333-.956 2.418-2.157 2.418zm7.975 0c-1.183 0-2.157-1.085-2.157-2.419 0-1.333.955-2.419 2.157-2.419 1.21 0 2.176 1.096 2.157 2.42 0 1.333-.946 2.418-2.157 2.418z"/>
                                </svg>
                            </div>
                        )}
                        <div className="absolute -bottom-1 -right-1 bg-[#5865F2] p-1.5 rounded-full border-2 border-[#1a1a1a] text-[10px] text-white flex items-center justify-center shadow-lg">
                            <svg viewBox="0 0 24 24" fill="currentColor" className="w-3.5 h-3.5">
                                <path d="M20.317 4.37a19.791 19.791 0 0 0-4.885-1.515.074.074 0 0 0-.079.037c-.21.375-.444.864-.608 1.25a18.27 18.27 0 0 0-5.487 0 12.64 12.64 0 0 0-.617-1.25.077.077 0 0 0-.079-.037A19.736 19.736 0 0 0 3.677 4.37a.07.07 0 0 0-.032.027C.533 9.046-.32 13.58.099 18.057a.082.082 0 0 0 .031.057 19.9 19.9 0 0 0 5.993 3.03.078.078 0 0 0 .084-.028 14.09 14.09 0 0 0 1.226-1.994.076.076 0 0 0-.041-.106 13.107 13.107 0 0 1-1.872-.892.077.077 0 0 1-.008-.128c.125-.094.249-.192.37-.291a.074.074 0 0 1 .077-.01c3.928 1.793 8.18 1.793 12.062 0a.074.074 0 0 1 .078.01c.12.098.246.198.37.292a.077.077 0 0 1-.006.127 12.299 12.299 0 0 1-1.873.892.077.077 0 0 0-.041.107c.36.698.772 1.362 1.225 1.993a.076.076 0 0 0 .084.028 19.839 19.839 0 0 0 6.002-3.03.077.077 0 0 0 .032-.054c.5-5.177-.838-9.674-3.549-13.66a.061.061 0 0 0-.031-.03zM8.02 15.33c-1.183 0-2.157-1.085-2.157-2.419 0-1.333.955-2.419 2.157-2.419 1.21 0 2.176 1.096 2.157 2.42 0 1.333-.956 2.418-2.157 2.418zm7.975 0c-1.183 0-2.157-1.085-2.157-2.419 0-1.333.955-2.419 2.157-2.419 1.21 0 2.176 1.096 2.157 2.42 0 1.333-.946 2.418-2.157 2.418z"/>
                            </svg>
                        </div>
                    </div>

                    <div>
                        <h3 className="text-xl font-black uppercase tracking-tighter text-white">Discord</h3>
                        <p className="text-sm font-bold text-gray-500 uppercase tracking-widest truncate max-w-37.5">
                            {isDiscordLinked
                                ? (discordIdentity?.identity_data?.full_name || discordIdentity?.identity_data?.name || discordIdentity?.identity_data?.user_name || discordMetadataName || t('account.connections.connected')) 
                                : t('account.connections.disconnected')}
                        </p>
                    </div>
                </div>

                <div className="mt-auto space-y-4">
                    {isDiscordLinked ? (
                        <button 
                            type="button"
                            onClick={() => discordIdentity ? onUnlinkProvider(discordIdentity) : onUnlinkDiscord()}
                            className="w-full py-4 bg-red-500/10 border border-red-500/20 text-red-400 font-black uppercase tracking-widest rounded-2xl hover:bg-red-500/20 active:scale-95 transition-colors text-xs"
                        >
                            {t('account.connections.unlink')}
                        </button>
                    ) : (
                        <div className="space-y-4">
                            <button 
                                type="button"
                                onClick={() => onLinkProvider('discord')}
                                className="w-full py-4 bg-[#5865F2] text-white font-black uppercase tracking-widest rounded-2xl hover:bg-[#4752c4] hover:scale-[1.02] active:scale-95 transition-colors shadow-xl shadow-[#5865f2]/10 text-xs"
                            >
                                {t('account.connections.connect_discord')}
                            </button>

                            <div className="relative py-4 flex items-center justify-center">
                                <span className="relative z-10 bg-[#0a0a0a]/50 px-4 text-[10px] font-black text-gray-500 uppercase tracking-widest backdrop-blur-sm rounded-full">
                                    {t('account.connections.or_bot_code', 'O CÓDIGO DE BOT')}
                                </span>
                                <div className="absolute inset-0 flex items-center">
                                    <div className="w-full border-t border-white/5"></div>
                                </div>
