export default ProfileSettings;

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Shield, Unlock, X } from 'lucide-react';
import { useVerifyAdmin2FA } from '../../hooks/useAdminData';
import { setAdminToken } from '../../services/adminAuth';
import Loader from '../UI/Loader';
import "../../styles/admin/admin2fa_modal.css";

interface Admin2FAModalProps {
    isOpen: boolean;
    onVerified: () => void;
    onClose: () => void;
}

export default function Admin2FAModal({ isOpen, onVerified, onClose }: Admin2FAModalProps) {
    const { t } = useTranslation();
    const [code, setCode] = useState('');
    const [error, setError] = useState<string | null>(null);

    const { mutate: verifyAdmin, isPending: loading } = useVerifyAdmin2FA();

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (code.length < 6) return;

        setError(null);

        verifyAdmin(code, {
            onSuccess: (data) => {
                setAdminToken(data.adminToken);
                onVerified();
            },
            onError: (err: Error) => {
                setCode('');
                setError(t('admin.2fa.error_retry', 'Código incorrecto. Inténtalo de nuevo.'));
                console.error(err);
            }
        });
    };

    return (
        <div
            role="dialog"
            aria-modal="true"
            aria-labelledby="admin-2fa-title"
            style={{
                position: 'fixed', inset: 0, zIndex: 3000,
                background: 'rgba(0,0,0,0.9)', backdropFilter: 'blur(10px)',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                animation: 'fadeIn 0.2s'
            }}
        >
            <div style={{
                background: '#0a0a0a', 
                border: '1px solid rgba(255,50,50,0.2)',
                boxShadow: '0 0 40px rgba(220, 20, 60, 0.1)',
                padding: '2.5rem', 
                borderRadius: '24px', 
                maxWidth: '420px', 
                width: '90%',
                position: 'relative', 
                textAlign: 'center',
                display: 'flex',
                flexDirection: 'column',
                gap: '1.5rem'
            }}>
                <button
                    aria-label={t('admin.2fa.close', 'Cerrar modal de autenticación')}
                    type="button" 
                    onClick={onClose}
                    style={{ position: 'absolute', top: '1.5rem', right: '1.5rem', background: 'none', border: 'none', color: 'rgba(255,255,255,0.4)', cursor: 'pointer', transition: 'color 0.2s' }}
                    className="hover:text-white"
                >
                    <X size={20} aria-hidden="true" />
                </button>

                <div style={{ 
                    background: 'rgba(239, 68, 68, 0.1)', color: '#ef4444', 
                    width: '80px', height: '80px', borderRadius: '50%', 
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    margin: '0 auto',
                    border: '1px solid rgba(239, 68, 68, 0.2)'
                }}>
                    <Shield size={36} aria-hidden="true" />
                </div>

                <div>
                    <h2 id="admin-2fa-title" style={{ color: '#fff', marginBottom: '0.5rem', fontSize: '1.5rem', fontWeight: '800' }}>{t('admin.2fa.title', 'Acceso Restringido')}</h2>
                    <p style={{ color: 'rgba(255,255,255,0.5)', fontSize: '0.95rem', lineHeight: '1.5' }}>
                        {t('admin.2fa.desc', 'Esta área requiere autenticación de dos factores. Ingresa tu código para continuar.')}
                    </p>
                </div>

                <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                    <div style={{ position: 'relative' }}>
                        <input aria-label={t('admin.2fa.code_label', 'Código de autenticación 2FA')}
                            type="text"
                            inputMode="numeric"
                            pattern="[0-9]*"
                            autoComplete="one-time-code"
                            maxLength={6}
                            value={code}
                            onChange={(e) => {
                                const val = e.target.value.replace(/[^0-9]/g, '');
                                setCode(val);
                                if(error) setError(null); // Clear error on typing
                            }}
                            placeholder="000 000"
                            style={{
                                width: '100%', padding: '1rem', background: 'rgba(255,255,255,0.03)',
                                border: error ? '1px solid #ef4444' : '1px solid rgba(255,255,255,0.1)',
                                borderRadius: '12px', color: '#fff', fontSize: '1.8rem', textAlign: 'center',
                                letterSpacing: '8px', 
                                outline: 'none',
                                fontWeight: '700',
                                fontVariantNumeric: 'tabular-nums',
                                transition: "color 0.2s, background-color 0.2s, border-color 0.2s, opacity 0.2s"
                            }}
                        />
                         {error && (
                            <div
                                role="alert"
                                aria-live="assertive"
                                style={{ 
                                    color: '#ef4444', 
                                    fontSize: '0.9rem', 
                                    marginTop: '0.8rem',
                                    fontWeight: '600',
                                    animation: 'shake 0.4s cubic-bezier(.36,.07,.19,.97) both'
                                }}
                            >
                                {error}
                            </div>
                        )}
                    </div>

                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.8rem' }}>
                        <button 
                            type="submit"
                            aria-busy={loading}
                            disabled={loading || code.length !== 6}
                            className="btn-primary"
                            style={{ 
                                width: '100%', padding: '1rem', justifyContent: 'center', display: 'flex', alignItems: 'center', gap: '10px',
                                borderRadius: '12px', fontSize: '1rem', fontWeight: '700',
                                background: '#ef4444', color: 'white', border: 'none', 
                                cursor: (loading || code.length !== 6) ? 'not-allowed' : 'pointer',
                                opacity: (loading || code.length !== 6) ? 0.5 : 1,
                                transition: "color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease, opacity 0.2s ease"
                            }}
                        >
                            {loading ? <Loader minimal /> : <><Unlock /> {t('admin.2fa.verify', 'Verificar Acceso')}</>}
                        </button>

                        <button 
                            type="button"
                            onClick={onClose}
                            style={{ 
                                background: 'transparent', 
                                border: 'none', 
                                color: 'rgba(255,255,255,0.4)', 
                                padding: '0.5rem', 
                                cursor: 'pointer',
                                fontSize: '0.9rem',
                                textDecoration: 'underline'
                            }}
                        >
                            {t('admin.back_home', 'Cancelar y volver al inicio')}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

