interface AdminDoc {
    id: string;
    title: string;
    content: string;
}

interface AdminDocsProps {
    mockDocs?: AdminDoc[];
}

export default function AdminDocs({ mockDocs }: AdminDocsProps = {}) {
    const { t } = useTranslation();
    const defaults = useDocsDefaults();
    const [docs, setDocs] = useState<AdminDoc[]>(mockDocs || []);
    const [activeTab, setActiveTab] = useState('intro');
    const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
    const [isEditing, setIsEditing] = useState(false);
    const [editContent, setEditContent] = useState('');
    const [loading, setLoading] = useState(!mockDocs);
    const [saving, setSaving] = useState(false);
    const [isResetConfirmOpen, setIsResetConfirmOpen] = useState(false);
    const [alertConfig, setAlertConfig] = useState<{ isOpen: boolean, message: string, variant: 'error' | 'success' }>({
        isOpen: false,
        message: '',
        variant: 'success'
    });
    const [uploading, setUploading] = useState(false);

    // Fetch docs from DB
    useEffect(() => {
        let ignore = false;
        const fetchDocs = async () => {
             if (mockDocs) return; // Use mocked docs
            try {
                const { data: { session } } = await supabase.auth.getSession();
                const res = await fetch(`${API_URL}/settings/admin_docs`, {
                    headers: getAuthHeaders(session?.access_token || null)
                });
                if (res.ok) {
                    const data = await res.json();
                    if (!ignore) {
                        if (data && data.value) {
                            const parsed = typeof data.value === 'string' ? JSON.parse(data.value) : data.value;
                            setDocs(parsed);
                        } else {
                            setDocs(defaults);
                        }
                    }
                } else if (!ignore) {
                    setDocs(defaults);
                }
            } catch (err) {
                console.error("Error fetching docs:", err);
                if (!ignore) setDocs(defaults);
            } finally {
                if (!ignore) setLoading(false);
            }
        };
        fetchDocs();
        return () => { ignore = true; };
    }, [defaults, mockDocs]);

    const activeDoc = docs.find(d => d.id === activeTab) || docs[0] || defaults[0];

    useEffect(() => {
        if (activeDoc) setEditContent(activeDoc.content);
    }, [activeDoc]);

    const handleSave = async () => {
        setSaving(true);
        try {
            const updatedDocs = docs.map(d => 
                d.id === activeTab ? { ...d, content: editContent } : d
            );

            const { data: { session } } = await supabase.auth.getSession();
            const res = await fetch(`${API_URL}/settings/admin_docs`, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    ...getAuthHeaders(session?.access_token || null)
                },
                body: JSON.stringify({ 
                    value: JSON.stringify(updatedDocs),
                    userId: session?.user?.id,
                    username: session?.user?.user_metadata?.username || 'Admin'
                })
            });

            if (!res.ok) throw new Error('Failed to save');

            setDocs(updatedDocs);
            setIsEditing(false);
        } catch (err) {
            console.error("Error saving docs:", err);
            setAlertConfig({
                isOpen: true,
                message: t('admin.docs.save_error'),
                variant: 'error'
            });
        } finally {
            setSaving(false);
        }
    };

    const handleReset = () => {
        setIsResetConfirmOpen(true);
    };

    const executeReset = () => {
        const defaultDoc = defaults.find(d => d.id === activeTab);
        if (defaultDoc) setEditContent(defaultDoc.content);
        setIsResetConfirmOpen(false);
    };

    const handleImageUpload = async (file: File) => {
        setUploading(true);
        try {
            // Server-validated upload (magic bytes checked in backend)
            const publicUrl = await uploadImageSecure(file, 'admin-assets', 'docs');

            // Insert markdown at cursor or end
            const imageMarkdown = `\n![Image](${publicUrl})\n`;
            setEditContent(prev => prev + imageMarkdown);

            setAlertConfig({
                isOpen: true,
                message: t('admin.docs.image_uploaded', 'Imagen subida correctamente'),
                variant: 'success'
            });
        } catch (err) {
            console.error("Error uploading image:", err);
            setAlertConfig({
                isOpen: true,
                message: t('admin.docs.upload_error', 'Error al subir la imagen'),
                variant: 'error'
            });
        } finally {
            setUploading(false);
        }
    };

    if (loading) return <div style={{ color: '#aaa', padding: '2rem' }}>{t('admin.docs.loading')}</div>;

    const ActiveIcon = ICON_MAP[activeDoc?.id] || Book;

    return (
        <div className="admin-docs-container">

            {/* Desktop Sidebar */}
            <div className="docs-sidebar">
                <h3 style={{ padding: '0 1rem 1rem', borderBottom: '1px solid rgba(255,255,255,0.05)', color: 'var(--muted)' }}>{t('admin.docs.index')}</h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', padding: '1rem 0' }}>
                    {docs.map(doc => {
                        const Icon = ICON_MAP[doc.id] || Book;
                        return (
                            <button 
                                aria-label={t('admin.docs.view_doc', `Ver documento: ${doc.title}`)} 
                                aria-current={activeTab === doc.id ? 'page' : undefined}
                                type="button"
                                key={doc.id}
                                onClick={() => { setActiveTab(doc.id); setIsEditing(false); }}
                                className={`sidebar-btn ${activeTab === doc.id ? 'active' : ''}`}
                            >
                                <Icon aria-hidden="true" />
                                {doc.title}
                            </button>
                        );
                    })}
                </div>
            </div>

            {/* Mobile Dropdown */}
            <div className="mobile-dropdown-container">
                <button 
                    aria-label={t('admin.docs.toggle_doc_menu', 'Alternar menú de documentación')} 
                    aria-expanded={mobileMenuOpen}
                    type="button" 
                    className="mobile-dropdown-btn"
                    onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
                >
                    <span style={{ display: 'flex', alignItems: 'center', gap: '0.8rem' }}>
                        <ActiveIcon color="var(--accent)" aria-hidden="true" /> {activeDoc.title}
                    </span>
                    <ChevronDown style={{ transform: mobileMenuOpen ? 'rotate(180deg)' : 'rotate(0)', transition: 'transform 0.2s' }} aria-hidden="true" />
                </button>

                {mobileMenuOpen && (
                    <div className="mobile-dropdown-list">
                        {docs.map(doc => {
                            const Icon = ICON_MAP[doc.id] || Book;
                            return (
                                <button
                                    type="button"
                                    key={doc.id}
                                    className={`mobile-dropdown-item ${activeTab === doc.id ? 'active' : ''}`}
                                    onClick={() => {
                                        setActiveTab(doc.id);
                                        setMobileMenuOpen(false);
                                        setIsEditing(false);
                                    }}
                                >
                                    <Icon /> {doc.title}
                                </button>
                            );
                        })}
                    </div>
                )}
            </div>

            {/* Área de Contenido */}
            <div className="docs-content">
                <div className="docs-card">
                    <div className="docs-header">
                        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                            <ActiveIcon size={30} color="var(--accent)" />
                            <h2 style={{ margin: 0, fontSize: '1.8rem' }}>{activeDoc.title}</h2>
                        </div>

                        <div style={{ display: 'flex', gap: '0.5rem' }}>
                            {isEditing ? (
                                <>
                                    <button 
                                        aria-label={t('admin.docs.reset', 'Restablecer documento')}
                                        type="button" 
                                        onClick={handleReset} 
                                        className="btn-secondary" 
                                        style={{ padding: '0.5rem 1rem', background: 'rgba(255,255,255,0.05)' }} 
                                        title={t('admin.docs.reset')}
                                    >
                                        <Undo2 aria-hidden="true" />
                                    </button>
                                    <button 
                                        type="button" 
                                        onClick={() => setIsEditing(false)} 
                                        className="btn-secondary" 
                                        style={{ color: '#ef4444' }}
                                    >
                                        <X aria-hidden="true" /> {t('admin.actions.cancel')}
                                    </button>
                                    <button 
                                        aria-busy={saving}
                                        type="button" 
                                        onClick={handleSave} 
                                        className="btn-primary" 
                                        disabled={saving}
                                    >
                                        <Save aria-hidden="true" /> {saving ? t('admin.docs.saving') : t('admin.actions.save')}
                                    </button>
                                </>
                            ) : (
                                <button type="button" onClick={() => setIsEditing(true)} className="btn-primary" style={{ background: 'rgba(22, 140, 128, 0.2)', border: '1px solid var(--accent)', color: 'var(--accent)' }}>
                                    <Edit /> {t('admin.docs.edit_section')}
                                </button>
                            )}
                        </div>
                    </div>

                    {isEditing ? (
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem', flex: 1 }}>
                            <div className="editor-toolbar" style={{ 
                                display: 'flex', 
                                gap: '0.5rem', 
                                padding: '0.5rem', 
                                background: 'rgba(255,255,255,0.02)', 
                                border: '1px solid rgba(255,255,255,0.05)', 
                                borderRadius: '8px' 
                            }}>
                                <label className="btn-icon-premium" style={{ cursor: 'pointer', padding: '0.5rem 1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.85rem' }}>
                                    {uploading ? <Loader2 className="spin" /> : <Image />}
                                    {uploading ? t('common.uploading', 'Subiendo...') : t('admin.docs.upload_image', 'Subir Imagen')}
                                    <input aria-label={t('admin.docs.upload_image', 'Subir Imagen')} 
                                        type="file" 
                                        accept="image/*" 
                                        style={{ display: 'none' }} 
                                        disabled={uploading}
                                        onChange={(e) => {
                                            if (e.target.files?.[0]) handleImageUpload(e.target.files[0]);
                                        }}
                                    />
                                </label>
                            </div>
                            <textarea aria-label={t('admin.docs.edit_content', 'Editar contenido de la documentación')} 
                                className="docs-editor"
                                value={editContent}
                                onChange={(e) => setEditContent(e.target.value)}
                                placeholder={t('admin.docs.placeholder')}
                                style={{ flex: 1 }}
                            />
                        </div>
                    ) : (
                        <div className="markdown-body" style={{ color: '#ddd', lineHeight: 1.6 }}>
                            <MarkdownRenderer content={activeDoc.content} />
                        </div>
                    )}
                </div>
            </div>
            <PremiumConfirm 
                isOpen={isResetConfirmOpen}
                title={t('admin.docs.reset_confirm_title', 'Restablecer Sección')}
                message={t('admin.docs.reset_confirm', '¿Estás seguro de que quieres restablecer esta sección a los valores predeterminados?')}
                confirmLabel={t('admin.docs.reset', 'Restablecer')}
                onConfirm={executeReset}
                onCancel={() => setIsResetConfirmOpen(false)}
                variant="warning"
            />
            <PremiumAlert 
                isOpen={alertConfig.isOpen}
                message={alertConfig.message}
                variant={alertConfig.variant}
                onClose={() => setAlertConfig(prev => ({ ...prev, isOpen: false }))}
            />
        </div>
    );
}

import { useState } from "react"
import { Plus, Edit, Trash2, Search, TriangleAlert } from "lucide-react"
import { useTranslation } from "react-i18next"
import Loader from "../UI/Loader"
import NewsForm from "./NewsForm"
import { NewsFormValues } from "../../schemas/news"
import { User } from "@supabase/supabase-js";
import { 
    useAdminNews, 
    useCreateNews, 
    useUpdateNews, 
    useDeleteNews 
} from "../../hooks/useAdminData"

interface NewsPost extends NewsFormValues {
    id?: number;
    created_at?: string;
    username?: string;
}

interface AdminNewsProps {
    user: User | null;
}

export default function AdminNews({ user }: AdminNewsProps) {
    const { t } = useTranslation()
    const [searchTerm, setSearchTerm] = useState('')
    const [isEditing, setIsEditing] = useState(false)
    const [currentPost, setCurrentPost] = useState<NewsPost | null>(null)
    const [deleteConfirm, setDeleteConfirm] = useState<number | null>(null)

    // TanStack Query Hooks
    const { data: news = [], isLoading: loading } = useAdminNews();
    const createMutation = useCreateNews();
    const updateMutation = useUpdateNews();
    const deleteMutation = useDeleteNews();

    const handleEdit = (post: NewsPost) => {
        setCurrentPost(post)
        setIsEditing(true)
    }

    const handleNew = () => {
        setCurrentPost({ 
            title: "", 
            title_en: "", 
            category: "General", 
            content: "", 
            content_en: "", 
            status: "Draft",
            image: "" 
        })
        setIsEditing(true)
    }

    const executeDelete = async () => {
        if (!deleteConfirm || !user) return;

        deleteMutation.mutate(deleteConfirm, {
            onSuccess: () => setDeleteConfirm(null)
        });
    }

    const handleSave = async (data: NewsFormValues) => {
        const username = user?.user_metadata?.full_name || user?.email || 'Admin';

        if (data.id) {
            updateMutation.mutate({ 
                id: data.id, 
                payload: { ...data, username, user_id: user?.id } 
            }, {
                onSuccess: () => {
                    setIsEditing(false);
                    setCurrentPost(null);
                }
            });
        } else {
            createMutation.mutate({
                ...data,
                author_id: user?.id,
                username
            }, {
                onSuccess: () => {
                    setIsEditing(false);
                    setCurrentPost(null);
                }
            });
        }
    }

    const filteredNews = news.filter((post: NewsPost) => 
        post.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
        post.category.toLowerCase().includes(searchTerm.toLowerCase())
    )

    if (isEditing && currentPost) {
        return (
            <NewsForm 
                initialData={currentPost}
                onSave={handleSave}
                onCancel={() => {
                    setIsEditing(false)
                    setCurrentPost(null)
                }}
                user={user}
            />
        )
    }

    return (
        <div className="news-manager-container">
            <div className="news-header">
                <div className="news-search-wrapper">
                    <Search className="news-search-icon" aria-hidden="true" />
                    <input 
                        aria-label={t('admin.news.search_ph', 'Buscar noticias')} 
                        type="search" 
                        placeholder={t('admin.news.search_ph')} 
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                        className="news-search-input"
                    />
                </div>
                <button type="button" className="btn-primary poll-new-btn" onClick={handleNew}>
                    <Plus size={14} aria-hidden="true" /> {t('admin.news.write_btn')}
                </button>
            </div>

            {loading ? (
                <div style={{ padding: '8rem', display: 'flex', justifyContent: 'center' }}>
                    <Loader />
                </div>
            ) : filteredNews.length === 0 ? (
                <div className="poll-empty-state">
                    <div className="poll-empty-icon-wrapper">
                        <Search size={48} />
                    </div>
                    <div>
                        <h3 style={{ fontSize: '1.75rem', fontWeight: '900', color: '#fff', marginBottom: '0.75rem' }}>{t('admin.news.no_news')}</h3>
                        <p style={{ color: 'rgba(255,255,255,0.4)', maxWidth: '400px', margin: '0 auto 2.5rem', lineHeight: '1.6' }}>
                           No se han encontrado noticias que coincidan con tu búsqueda o aún no hay entradas.
                        </p>
                        <button type="button" className="btn-primary" onClick={handleNew} style={{ padding: '1rem 2.5rem' }}>
                            <Plus style={{ marginRight: '10px' }} /> {t('admin.news.write_btn')}
                        </button>
                    </div>
                </div>
            ) : (
                <div className="news-cards-grid">
                    {filteredNews.map((post: NewsPost) => (
                        <div key={post.id} className="news-card-premium">
                            <div className="news-card-image-wrapper">
                                <img 
                                    src={post.image || "/images/ui/logo.webp"} 
                                    className="news-card-image" 
                                    alt={post.title} 
                                    onError={(e) => {
                                        (e.target as HTMLImageElement).src = "/images/ui/logo.webp";
                                    }}
                                />
                                <div className="news-card-overlay"></div>
                                <span className="news-card-badge">
                                    {post.category}
                                </span>
                                <span className="news-card-status" style={{
                                    color: post.status === "Published" ? "#4ade80" : "#fbbf24",
                                    background: post.status === "Published" ? "rgba(74, 222, 128, 0.2)" : "rgba(251, 191, 36, 0.2)",
                                    backdropFilter: 'blur(10px)',
                                    border: `1px solid ${post.status === "Published" ? "rgba(74, 222, 128, 0.4)" : "rgba(251, 191, 36, 0.4)"}`
                                }}>
                                    {post.status === "Published" ? t('admin.news.form.published') : t('admin.news.form.draft')}
                                </span>
                            </div>

                            <div className="news-card-content">
                                <h4 className="news-card-title">{post.title}</h4>
                                <div className="news-card-meta">
                                    <span>{post.created_at ? new Date(post.created_at).toLocaleDateString() : '-'}</span>
                                    <span>•</span>
                                    <span>{post.username || 'Admin'}</span>
                                </div>

                                <div className="news-card-footer">
                                    <button type="button"
                                        onClick={() => handleEdit(post)}
                                        className="event-btn-action"
                                        title={t('admin.news.edit_title')}
                                    >
                                        <Edit />
                                    </button>
                                    <button type="button"
                                        onClick={() => post.id && setDeleteConfirm(post.id)}
                                        className="event-btn-action delete"
                                        title={t('admin.news.delete_tooltip')}
                                    >
                                        <Trash2 />
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Delete Confirmation Modal */}
            {deleteConfirm && (
                <div className="sync-modal-overlay">
                    <div className="sync-modal-content" style={{ maxWidth: '450px', textAlign: 'center', padding: '3.5rem' }}>
                        <div className="modal-accent-line" style={{ background: 'linear-gradient(90deg, transparent, #ef4444, transparent)' }}></div>
                        <div style={{ 
                            width: '80px', 
                            height: '80px', 
                            borderRadius: '50%', 
                            background: 'rgba(239, 68, 68, 0.1)', 
                            color: '#ef4444',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            margin: '0 auto 2rem',
                            fontSize: '2.5rem'
                        }}>
                            <TriangleAlert />
                        </div>
                        <h3 style={{ margin: '0 0 1rem 0', fontSize: '1.75rem', fontWeight: '900', color: '#fff' }}>{t('admin.news.delete_modal.title')}</h3>
                        <p style={{ color: 'rgba(255,255,255,0.4)', marginBottom: '2.5rem', lineHeight: '1.6', fontSize: '1rem' }}>
                            {t('admin.news.delete_modal.desc')}
                        </p>
                        <div style={{ display: 'flex', gap: '1.25rem', justifyContent: 'center' }}>
                            <button type="button" 
                                className="modal-btn-secondary" 
                                onClick={() => setDeleteConfirm(null)}
                                style={{ flex: 1, height: '54px' }}
                            >
                                {t('admin.news.delete_modal.cancel')}
                            </button>
                            <button type="button" 
                                className="modal-btn-primary" 
                                onClick={executeDelete}
                                disabled={deleteMutation.isPending}
                                style={{ 
                                    flex: 1, 
                                    background: '#ef4444', 
                                    color: '#fff',
                                    height: '54px',
                                    boxShadow: '0 10px 30px rgba(239, 68, 68, 0.3)'
                                }}
                            >
                                {deleteMutation.isPending ? t('common.deleting') : t('admin.news.delete_modal.confirm')}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    )
}

import { useState, useEffect } from "react"
import { Globe, Gamepad2, Shield, User, Search, Filter, Calendar, ChevronLeft, ChevronRight } from 'lucide-react'
import { useTranslation } from "react-i18next"
import Loader from "../UI/Loader"
import { useAuditLogs } from "../../hooks/useAdminData"

const getSourceIcon = (source: string) => {
    if (source === 'game') return <Gamepad2 size={16} />
    if (source === 'security-auditor' || source === 'security') return <Shield size={16} />
    return <Globe size={16} />
}

const formatDate = (date: number | string) => {
    const d = new Date(date)
    return d.toLocaleString()
}

interface LogEntry {
    id: string;
    created_at: number | string;
    username: string;
    action: string;
    details: string;
    source: string;
}

interface AuditLogProps {
    mockLogs?: LogEntry[];
    mockTotal?: number;
}

interface HistoryProps extends React.SVGProps<SVGSVGElement> {
    size?: number | string;
}

function History({ size = 24, ...props }: HistoryProps) {
    return (
        <svg
            {...props}
            xmlns="http://www.w3.org/2000/svg"
            width={size}
            height={size}
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
        >
            <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8" />
            <path d="M3 3v5h5" />
            <path d="m12 7 0 5 3 3" />
        </svg>
    )
}

export default function AuditLog({ mockLogs, mockTotal }: AuditLogProps = {}) {
    const { t } = useTranslation()
    const [filterSource, setFilterSource] = useState('all')
    const [page, setPage] = useState(1)
    const [limit] = useState(50)
    const [search, setSearch] = useState('')
    const [searchTerm, setSearchTerm] = useState('')

    // TanStack Query Hook
    const { data: fetchLogsData, isLoading: loading } = useAuditLogs(
        page, 
        limit, 
        searchTerm, 
        filterSource
    );

    useEffect(() => {
        const timer = setTimeout(() => {
            setSearchTerm(search);
            setPage(1); // Reset to first page on search
        }, 500);
        return () => clearTimeout(timer);
    }, [search]);

    const logs = mockLogs || fetchLogsData?.data || [];
    const totalCount = mockTotal !== undefined ? mockTotal : (fetchLogsData?.total || 0);
    const totalPages = Math.ceil(totalCount / limit) || 1;



    return (
        <div className="audit-log-container">
            <div className="audit-log-header">
                <div>
                    <h3>{t('admin.audit.title')}</h3>
                    <p>{t('admin.audit.subtitle')}</p>
                </div>

                <div className="audit-log-controls">
                    <div className="audit-search-box">
                        <Search size={18} aria-hidden="true" />
                        <input
                            aria-label={t('admin.audit.search_placeholder', 'Buscar por usuario o acción')}
                            type="text" 
                            placeholder={t('admin.audit.search_placeholder')} 
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                        />
                    </div>
                </div>
            </div>

            <div className="audit-filters-bar">
                <div className="filter-group" role="group" aria-label={t('admin.audit.filter_by_source', 'Filtrar por origen')}>
                    <Filter size={16} aria-hidden="true" />
                    <button 
                        type="button"
                        aria-pressed={filterSource === 'all'}
                        className={`filter-btn ${filterSource === 'all' ? 'active' : ''}`}
                        onClick={() => { setFilterSource('all'); setPage(1); }}
                    >
                        {t('admin.audit.source_all')}
                    </button>
                    <button 
                        type="button"
                        aria-pressed={filterSource === 'web'}
                        className={`filter-btn ${filterSource === 'web' ? 'active' : ''}`}
                        onClick={() => { setFilterSource('web'); setPage(1); }}
                    >
                        <Globe size={14} aria-hidden="true" /> {t('admin.audit.source_web')}
                    </button>
                    <button 
                        type="button"
                        aria-pressed={filterSource === 'game'}
                        className={`filter-btn ${filterSource === 'game' ? 'active' : ''}`}
                        onClick={() => { setFilterSource('game'); setPage(1); }}
                    >
                        <Gamepad2 size={14} aria-hidden="true" /> {t('admin.audit.source_game')}
                    </button>
                    <button 
                        type="button"
                        aria-pressed={filterSource === 'security-auditor'}
                        className={`filter-btn ${filterSource === 'security-auditor' ? 'active' : ''}`}
                        onClick={() => { setFilterSource('security-auditor'); setPage(1); }}
                    >
                        <Shield size={14} aria-hidden="true" /> {t('admin.audit.source_security-auditor')}
                    </button>
                </div>

                <div className="pagination-summary">
                    {t('admin.audit.showing', { count: logs.length, total: totalCount })}
                </div>
            </div>

            {loading ? (
                <div className="audit-loading-state">
                    <Loader />
                </div>
            ) : logs.length === 0 ? (
                <div className="audit-empty-state">
                    <div className="empty-icon-circle">
                        <History size={48} />
                    </div>
                    <h4>{t('admin.audit.no_logs_found')}</h4>
                    <p>{t('admin.audit.try_adjust_filters')}</p>
                </div>
            ) : (
                <div className="audit-table-wrapper">
                    <table className="audit-table">
                        <thead>
                            <tr>
                                <th>{t('admin.audit.table_date')}</th>
                                <th>{t('admin.audit.table_user')}</th>
                                <th>{t('admin.audit.table_source')}</th>
                                <th>{t('admin.audit.table_action')}</th>
                                <th>{t('admin.audit.table_details')}</th>
                            </tr>
                        </thead>
                        <tbody>
                            {logs.map((log: LogEntry) => (
                                <tr key={log.id} className="audit-row">
                                    <td className="cell-date">
                                        <div className="date-main">
                                            <Calendar size={14} />
                                            {formatDate(log.created_at)}
                                        </div>
                                    </td>
                                    <td className="cell-user">
                                        <div className="user-info">
                                            <User size={14} />
                                            <span>{log.username}</span>
                                        </div>
                                    </td>
                                    <td className="cell-source">
                                        <span className={`source-badge ${log.source}`}>
                                            {getSourceIcon(log.source)}
                                            {t(`admin.audit.source_${log.source}`)}
                                        </span>
                                    </td>
                                    <td className="cell-action">
                                        <span className="action-tag">{log.action}</span>
                                    </td>
                                    <td className="cell-details">
                                        <div className="details-text" title={log.details}>
                                            {log.details}
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            {totalPages > 1 && (
                <div className="audit-pagination" role="navigation" aria-label={t('common.pagination', 'Paginación de registros')}>
                    <button type="button" 
                        disabled={page === 1} 
                        onClick={() => setPage(page - 1)}
                        className="pagination-btn"
                        aria-label={t('common.previous', 'Página anterior')}
                        title={t('common.previous')}
                    >
                        <ChevronLeft size={18} aria-hidden="true" />
                    </button>
                    <div className="pagination-pages">
                        {(() => {
                            const maxButtons = 5;
                            let startPage = Math.max(1, page - 2);
                            const endPage = Math.min(totalPages, Math.max(1, startPage + maxButtons - 1));

                            // Adjust start if we hit the end
                            if (endPage - startPage + 1 < maxButtons) {
                                startPage = Math.max(1, endPage - maxButtons + 1);
                            }

                            return Array.from({ length: endPage - startPage + 1 }, (_, i) => startPage + i).map(p => (
                                <button
                                    type="button" 
                                    key={p}
                                    aria-label={t('common.page_number', `Página ${p}`, { page: p })}
                                    aria-current={page === p ? "page" : undefined}
                                    className={`page-num ${page === p ? 'active' : ''}`}
                                    onClick={() => setPage(p)}
                                    style={{ fontVariantNumeric: 'tabular-nums' }}
                                >
                                    {p}
                                </button>
                            ));
                        })()}
                    </div>
                    <button type="button" 
                        disabled={page === totalPages} 
                        onClick={() => setPage(page + 1)}
                        className="pagination-btn"
                        aria-label={t('common.next', 'Página siguiente')}
                        title={t('common.next')}
                    >
                        <ChevronRight size={18} aria-hidden="true" />
                    </button>
                </div>
            )}
        </div>
    )
}

import { useState, useEffect } from 'react';
import { Plus, Trash2, Save, Edit2, X, MapPin, Ghost, Users } from 'lucide-react';
import "../../../styles/admin/locations_manager.css";
import ConfirmationModal from '../../UI/ConfirmationModal';
import { getLocations, createLocation, updateLocation, deleteLocation, WorldLocation, LocationAuthor } from '../../../services/locationService';
import { supabase } from '../../../services/supabaseClient';
import { useTranslation } from 'react-i18next';
import Loader from '../../UI/Loader';

const AUTHOR_ROLES = [
    'architect',
    'co_founder',
    'staff',
    'team',
    'builder',
    'developer'
];

export default function LocationsManager() {
    const { t } = useTranslation();
    const [locations, setLocations] = useState<WorldLocation[]>([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [deleteConfirmId, setDeleteConfirmId] = useState<number | null>(null);
    const [editingId, setEditingId] = useState<number | null>(null);
    const [isCreating, setIsCreating] = useState(false);

    // Form state
    const [formData, setFormData] = useState<Partial<WorldLocation>>({
        title: '',
        description: '',
        long_description: '',
        coords: '0, 0, 0',
        image_url: '',
        is_coming_soon: false,
        authors: [],
        sort_order: 0
    });

    const [newAuthor, setNewAuthor] = useState<LocationAuthor>({ name: '', role: 'architect' });

    async function fetchLocations() {
        setLoading(true);
        try {
            const data = await getLocations();
            setLocations(data);
        } catch (error) {
            console.error('Error fetching locations:', error);
        } finally {
            setLoading(false);
        }
    }

    useEffect(() => {
        let isMounted = true;
        Promise.resolve().then(() => {
            if (isMounted) fetchLocations();
        });
        return () => {
            isMounted = false;
        };
    }, []);

    const handleSave = async () => {
        if (!formData.title || !formData.description) {
            alert(t('locations_manager.form.error_fields', 'Por favor completa los campos básicos'));
            return;
        }

        setSaving(true);
        try {
            const { data: { session } } = await supabase.auth.getSession();
            const token = session?.access_token;
            if (!token) return;

            if (editingId) {
                await updateLocation(editingId, formData, token);
            } else {
                await createLocation(formData as Omit<WorldLocation, 'id'>, token);
            }

            resetForm();
            await fetchLocations();
        } catch (error) {
            console.error('Error saving location:', error);
            alert(t('locations_manager.form.error_save', 'Error al guardar'));
        } finally {
            setSaving(false);
        }
    };

    const handleEdit = (loc: WorldLocation) => {
        setFormData(loc);
        setEditingId(loc.id);
        setIsCreating(true);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const resetForm = () => {
        setFormData({
            title: '',
            description: '',
            long_description: '',
            coords: '0, 0, 0',
            image_url: '',
            is_coming_soon: false,
            authors: [],
            sort_order: 0
        });
        setEditingId(null);
        setIsCreating(false);
    };

    const addAuthor = () => {
        if (!newAuthor.name) return;
        const currentAuthors = formData.authors || [];
        setFormData({ ...formData, authors: [...currentAuthors, newAuthor] });
        setNewAuthor({ name: '', role: 'architect' });
    };

    const removeAuthor = (idx: number) => {
        const currentAuthors = [...(formData.authors || [])];
        currentAuthors.splice(idx, 1);
        setFormData({ ...formData, authors: currentAuthors });
    };

    const confirmDelete = async () => {
        if (!deleteConfirmId) return;
        try {
            const { data: { session } } = await supabase.auth.getSession();
            const token = session?.access_token;
            if (!token) return;

            await deleteLocation(deleteConfirmId, token);
            setDeleteConfirmId(null);
            await fetchLocations();
        } catch (error) {
            console.error('Error deleting:', error);
        }
    };

    if (loading) return (
        <div style={{ padding: '5rem 0' }}>
            <Loader text={t('locations_manager.loading', "Sincronizando Lore...")} />
        </div>
    );

    return (
        <div className="locations-manager-container animate-fade-in">

            {/* Header Section */}
            <div className="manager-header">
                <div>
                    <h3 style={{ margin: 0, fontSize: '1.5rem', fontWeight: '900', color: '#fff', display: 'flex', alignItems: 'center', gap: '1rem' }}>
                        <MapPin style={{ color: 'var(--accent)' }} /> {t('locations_manager.title', 'Gestor de Lugares y Lore')}
                    </h3>
                    <p style={{ margin: '4px 0 0 0', fontSize: '0.9rem', color: 'rgba(255,255,255,0.4)' }}>{t('locations_manager.subtitle', 'Administra los puntos de interés y la historia del mundo.')}</p>
                </div>
                {!isCreating && (
                    <button type="button" 
                        onClick={() => setIsCreating(true)} 
                        className="modal-btn-primary hover-lift"
                        style={{ padding: '0.8rem 1.5rem', borderRadius: '16px', fontWeight: '800', display: 'flex', alignItems: 'center', gap: '10px' }}
                    >
                        <Plus /> {t('locations_manager.create_btn', 'Nuevo Lugar')}
                    </button>
                )}
            </div>

            {/* Creation Form */}
            {isCreating && (
                <div className="admin-card editor-card">
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2.5rem' }}>
