                                <div>
                                    <label htmlFor="location-coords" style={{ display: 'block', marginBottom: '0.8rem', color: 'rgba(255,255,255,0.7)', fontSize: '0.9rem', fontWeight: '700' }}>
                                        {t('locations_manager.form.coords', 'Coordenadas')}
                                    </label>
                                    <input id="location-coords"
