    const setContentEn = (val: string) => dispatchForm({ type: 'UPDATE_FIELD', field: 'contentEn', value: val })

    const currentPolicy = useMemo(() => 
        policies.find((p: Policy) => p.slug === selectedSlug) || null
    , [policies, selectedSlug])

