import React, { useState, useEffect } from "react";
import { CircleDollarSign, X, User, Mail, Clock, CheckCircle, Loader2 } from "lucide-react";
import { useTranslation } from "react-i18next";
import { Donation } from "./types";

interface DonationFormModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSave: (donation: Donation) => Promise<void>;
    initialData: Donation | null;
    saving?: boolean;
}

export default function DonationFormModal({ isOpen, onClose, onSave, initialData, saving }: DonationFormModalProps) {
    const { t } = useTranslation();
    const [formData, setFormData] = useState<Donation>({
        id: 0,
        amount: 0,
        currency: 'USD',
        from_name: '',
        message: '',
        is_public: true,
        buyer_email: '',
        created_at: new Date().toISOString()
    });
    const [isSubmitting, setIsSubmitting] = useState(false);

    useEffect(() => {
        if (initialData) {
            setFormData(initialData);
        } else {
            // Reset for new entry
            setFormData({
                id: 0,
                amount: 0,
                currency: 'USD',
                from_name: '',
                message: '',
                is_public: true,
                buyer_email: '',
                created_at: new Date().toISOString()
            });
        }
    }, [initialData, isOpen]);

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSubmitting(true);
        try {
            await onSave(formData);
            onClose();
        } catch (error) {
            console.error("Error saving donation:", error);
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="sync-modal-overlay" role="presentation">
            <div className="sync-modal-content" role="dialog" aria-modal="true" aria-labelledby="donation-modal-title" style={{ maxWidth: '700px' }}>
                <div className="modal-accent-line"></div>

                <div className="poll-form-header">
                    <h3 id="donation-modal-title" style={{ margin: 0, display: 'flex', alignItems: 'center', gap: '12px', color: '#fff', fontSize: '1.5rem', fontWeight: '900' }}>
                        <CircleDollarSign style={{ color: 'var(--accent)' }} aria-hidden="true" />
                        {formData.id ? t('admin.donations.edit_title') : t('admin.donations.new_btn')}
                    </h3>
                    <button 
                        aria-label={t('common.close', 'Cerrar ventana')} 
                        type="button" 
                        onClick={onClose} 
                        className="btn-close-mini"
                    >
                        <X aria-hidden="true" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="poll-form-body">
                    <div className="donation-form-grid">
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                            <div className="form-group">
                                <label htmlFor="donation-donor-name" className="admin-label-premium">
                                    <User size={12} /> {t('admin.donations.form.donor_name')}
                                </label>
                                <input id="donation-donor-name"
                                    className="admin-input-premium" 
                                    value={formData.from_name} 
                                    onChange={e => setFormData({...formData, from_name: e.target.value})}
                                    placeholder={t('admin.donations.form.name_ph')}
                                />
                            </div>

                            <div className="form-group">
                                <label htmlFor="donation-email" className="admin-label-premium">
                                    <Mail size={12} /> {t('admin.donations.form.email_label')}
                                </label>
                                <input id="donation-email"
                                    className="admin-input-premium" 
                                    value={formData.buyer_email || ''} 
                                    onChange={e => setFormData({...formData, buyer_email: e.target.value})}
                                    placeholder="email@ejemplo.com"
                                />
                            </div>

                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                                <div className="form-group">
                                    <label htmlFor="donation-amount" className="admin-label-premium">{t('admin.donations.form.amount')}</label>
                                    <input id="donation-amount"
                                        type="number" 
                                        step="0.01"
                                        className="admin-input-premium" 
                                        value={formData.amount} 
                                        onChange={e => setFormData({...formData, amount: parseFloat(e.target.value) || 0})}
                                        required
                                    />
                                </div>
                                <div className="form-group">
                                    <label htmlFor="donation-currency" className="admin-label-premium">{t('admin.donations.form.currency')}</label>
                                    <select id="donation-currency"
                                        className="admin-select-premium" 
                                        value={formData.currency} 
                                        onChange={e => setFormData({...formData, currency: e.target.value})}
                                    >
                                        <option value="USD">USD</option>
                                        <option value="EUR">EUR</option>
                                        <option value="MXN">MXN</option>
                                    </select>
                                </div>
                            </div>
                        </div>

                        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                            <div className="form-group">
                                <label htmlFor="donation-message" className="admin-label-premium">{t('admin.donations.form.message')}</label>
                                <textarea id="donation-message"
                                    className="admin-textarea-premium" 
                                    rows={4}
                                    value={formData.message} 
                                    onChange={e => setFormData({...formData, message: e.target.value})}
                                    placeholder="Escribe un mensaje..."
                                />
                            </div>

                            <div className="form-group">
                                <div
                                    className={`custom-checkbox-premium ${formData.is_public ? 'checked' : ''}`}
                                    onClick={() => setFormData({...formData, is_public: !formData.is_public})}
                                    role="checkbox"
                                    aria-checked={formData.is_public}
                                    tabIndex={0}
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter' || e.key === ' ') {
                                            e.preventDefault();
                                            setFormData({...formData, is_public: !formData.is_public});
                                        }
                                    }}
                                >
                                    <div className="checkbox-visual">
                                        {formData.is_public && <CheckCircle />}
                                    </div>
                                    <div className="checkbox-label-text">
                                        {t('admin.donations.form.is_public')}
                                    </div>
                                </div>
                            </div>

                            <div className="form-group">
                                <label htmlFor="donation-date" className="admin-label-premium">
                                    <Clock size={12} /> {t('admin.tickets.table.date')}
                                </label>
                                <input id="donation-date"
                                    type="datetime-local"
                                    className="admin-input-premium" 
                                    value={formData.created_at ? new Date(formData.created_at).toISOString().slice(0, 16) : ''} 
                                    onChange={e => setFormData({...formData, created_at: new Date(e.target.value).toISOString()})}
                                />
                            </div>
                        </div>
                    </div>

                    <div className="poll-form-footer">
                        <button type="button" className="modal-btn-secondary" onClick={onClose}>{t('admin.donations.form.cancel')}</button>
                        <button type="submit" className="modal-btn-primary" disabled={saving || isSubmitting}>
                            {(saving || isSubmitting) ? <Loader2 className="spin" /> : <><CheckCircle /> {t('admin.donations.form.save')}</>}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

import {
  Edit2,
  Trash2,
  Globe,
  X,
  CircleDollarSign,
  Calendar,
  ChevronLeft,
  ChevronRight,
} from "lucide-react";
import { useTranslation } from "react-i18next";
import Loader from "../../UI/Loader";
import { Donation } from "./types";

interface DonationsTableProps {
  donations: Donation[];
  loading: boolean;
  onEdit: (donation: Donation) => void;
  onDelete: (id: number) => void;
  page: number;
  totalPages: number;
  setPage: (page: number | ((prev: number) => number)) => void;
}

export default function DonationsTable({
  donations,
  loading,
  onEdit,
  onDelete,
  page,
  totalPages,
  setPage,
}: DonationsTableProps) {
  const { t } = useTranslation();

  if (loading && donations.length === 0) {
    return (
      <div className="empty-donations">
        <Loader />
      </div>
    );
  }

  if (donations.length === 0) {
    return (
      <div className="empty-donations">
        <div className="empty-icon-pulse">
          <CircleDollarSign />
        </div>
        <h4 style={{ color: "#fff", margin: 0 }}>
          {t("admin.donations.empty")}
        </h4>
        <p
          style={{
            color: "rgba(255,255,255,0.3)",
            maxWidth: "300px",
            margin: 0,
          }}
        >
          No hay registros de donaciones que coincidan con tu búsqueda.
        </p>
      </div>
    );
  }

  return (
    <div className="donations-table-wrapper">
      <div style={{ flex: 1, overflowX: "auto" }}>
        <table className="premium-table">
          <thead>
            <tr>
              <th>{t("admin.tickets.table.user")}</th>
              <th>{t("admin.donations.form.message")}</th>
              <th>{t("admin.donations.form.amount")}</th>
              <th>{t("admin.tickets.table.date")}</th>
              <th>{t("admin.tickets.table.status")}</th>
              <th style={{ textAlign: "right" }}>Acciones</th>
            </tr>
          </thead>
          <tbody>
            {donations.map((donation) => (
              <tr key={donation.id}>
                <td
                  aria-label={
                    donation.from_name || t("admin.donations.anonymous")
                  }
                >
                  <div className="donor-cell">
                    <div className="donor-mini-avatar">
                      {donation.from_name
                        ? donation.from_name.charAt(0).toUpperCase()
                        : "?"}
                    </div>
                    <div className="donor-name-link">
                      <span className="donor-name-text">
                        {donation.from_name || t("admin.donations.anonymous")}
                      </span>
                      <span className="donor-email-text">
                        {donation.buyer_email || "---"}
                      </span>
                    </div>
                  </div>
                </td>
                <td>
                  <div
                    className={`message-cell ${!donation.message ? "empty" : ""}`}
                  >
                    {donation.message || t("admin.donations.no_msg")}
                  </div>
                </td>
                <td>
                  <div
                    className={`donation-amount-badge ${Number(donation.amount) >= 50 ? "high" : ""}`}
                  >
                    {donation.currency}{" "}
                    {Number(donation.amount || 0).toFixed(2)}
                  </div>
                </td>
                <td>
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "0.6rem",
                      color: "rgba(255,255,255,0.4)",
                      fontSize: "0.85rem",
                      fontWeight: 600,
                    }}
                  >
                    <Calendar size={12} />
                    {donation.created_at
                      ? new Date(donation.created_at).toLocaleDateString()
                      : "---"}
                  </div>
                </td>
                <td>
                  <span
                    className={`visibility-badge ${donation.is_public ? "public" : "private"}`}
                  >
                    {donation.is_public ? <Globe size={10} /> : <X size={10} />}
                    {donation.is_public
                      ? t("admin.donations.public")
                      : t("admin.donations.private")}
                  </span>
                </td>
                <td style={{ textAlign: "right" }}>
                  <div
                    style={{
                      display: "flex",
                      justifyContent: "flex-end",
                      gap: "0.6rem",
                    }}
                  >
                    <button
                      aria-label={t(
                        "admin.donations.edit_donation",
                        `Editar donación de ${donation.from_name || t("admin.donations.anonymous")}`,
                      )}
                      type="button"
                      onClick={() => onEdit(donation)}
                      className="donor-btn-action edit"
                      title={t("admin.polls.edit_btn")}
                    >
                      <Edit2 size={14} aria-hidden="true" />
                    </button>
                    <button
                      aria-label={t(
                        "admin.donations.delete_donation",
                        `Eliminar donación de ${donation.from_name || t("admin.donations.anonymous")}`,
                      )}
                      type="button"
                      onClick={() => onDelete(donation.id)}
                      className="donor-btn-action delete"
                      title={t("admin.donors.delete_btn")}
                    >
                      <Trash2 size={14} aria-hidden="true" />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {totalPages > 1 && (
        <div className="premium-pagination">
          <button
            aria-label={t("common.prev_page", "Página anterior")}
            type="button"
            className="page-btn"
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={page === 1}
          >
            <ChevronLeft size={12} aria-hidden="true" />
          </button>
          <div className="page-info">
            PAGINA <span className="tabular-nums">{page}</span> DE{" "}
            <span className="tabular-nums">{totalPages}</span>
          </div>
          <button
            aria-label={t("common.next_page", "Página siguiente")}
            type="button"
            className="page-btn"
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            disabled={page === totalPages}
          >
            <ChevronRight size={12} aria-hidden="true" />
          </button>
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
