                {
                    id: '5',
                    name: "Zeta",
                    skinUrl: "/skins/zeta.png",
                    description: t('donors.profiles.zeta'),
                    ranks: ['fundador']
                },
                {
                    id: '6',
                    name: "SendPles",
                    skinUrl: "https://minotar.net/skin/5bec40ab-e459-474b-b96c-21ee1eae7d29",
                    description: t('donors.profiles.sendples'),
                    ranks: ['fundador']
                },
                {
                    id: '7',
                    name: "ZenXeone",
                    skinUrl: "https://minotar.net/skin/eacfb70c-c83a-4e0b-8465-ee4b0b86e041",
                    description: t('donors.profiles.zen'),
                    ranks: ['donador']
                },
                {
                    id: '8',
                    name: "Churly",
                    skinUrl: "/skins/churly.png",
                    description: t('donors.profiles.churly'),
                    ranks: ['donador', 'developer']
                },
                {
                    id: '9',
                    name: "Nana Fubuki",
                    skinUrl: "/skins/nana-fubuki.png",
                    description: t('donors.profiles.nana'),
                    ranks: ['donador']
                }
            ];
            handleUpdateDonors(defaults);
        }
        setConfirmModal({ isOpen: false, type: null });
    };

    const onDragEnd = (result: DropResult) => {
        if (!result.destination) return;

        const items = Array.from(donors);
        const [reorderedItem] = items.splice(result.source.index, 1);
        items.splice(result.destination.index, 0, reorderedItem);

        handleUpdateDonors(items);
    };

    const handleEditSave = (donorData: Donor) => {
        if (!donorData.name) {
            setAlert({ message: t('admin.donors.validation.name_req'), type: "error" });
            return;
        }
        if (!donorData.isPremium && !donorData.skinUrl) {
            setAlert({ message: t('admin.donors.validation.skin_req'), type: "error" });
            return;
        }
        if (!donorData.description) {
            setAlert({ message: t('admin.donors.validation.desc_req'), type: "error" });
            return;
        }

        let newList = [...donors];
        const finalDonor = {
            ...donorData,
            skinUrl: donorData.isPremium 
                ? `https://minotar.net/skin/${donorData.name}` 
                : donorData.skinUrl
        };

        if (isNew) {
            finalDonor.id = Date.now().toString();
            newList.push(finalDonor);
        } else {
            newList = newList.map(d => d.id === donorData.id ? finalDonor : d);
        }

        handleUpdateDonors(newList);
        setEditingDonor(null);
    };

    const openNew = () => {
        setEditingDonor({
            id: '',
            name: '',
            skinUrl: '',
            description: '',
            description_en: '',
            ranks: ['donador'],
            isPremium: false
        });
        setIsNew(true);
    };

    if (loading) return <div style={{ padding: '8rem', display: 'flex', justifyContent: 'center' }}><Loader /></div>;

    return (
        <div className="donor-manager-container">
            <div className="news-header">
                <div>
                   <h3 style={{ margin: 0, display:'flex', alignItems:'center', gap:'1rem', fontSize: '1.5rem', fontWeight: 900, color: '#fff' }}>
                        <div style={{ padding: '8px', background: 'rgba(var(--accent-rgb), 0.1)', borderRadius: '12px', display: 'flex', color: 'var(--accent)' }}>
                            <Crown />
                        </div>
                        {t('admin.donors.manager_title')}
                    </h3>
                    <p style={{ margin: '0.5rem 0 0', color: 'rgba(255,255,255,0.4)', fontSize: '0.9rem' }}>
                        {t('admin.donors.manager_desc', 'Administra la lista de honor y personaliza el perfil de cada donador.')}
                    </p>
                </div>
                <button type="button" className="btn-primary poll-new-btn" onClick={openNew}>
                    <Plus /> {t('admin.donors.add_btn')}
                </button>
            </div>

            <DonorsList 
                donors={donors}
                onDragEnd={onDragEnd}
                onEdit={(d) => { setEditingDonor(d); setIsNew(false); }}
                onDelete={(id) => setConfirmModal({ isOpen: true, type: 'delete', payload: id })}
                onImport={handleImportDefaults}
            />

            <DonorFormModal 
                donor={editingDonor}
                isNew={isNew}
                onClose={() => setEditingDonor(null)}
                onSave={handleEditSave}
                saving={updateSettingMutation.isPending}
            />

            <DonorsConfirmModal 
                isOpen={confirmModal.isOpen}
                type={confirmModal.type}
                onClose={() => setConfirmModal({ ...confirmModal, isOpen: false })}
                onConfirm={confirmAction}
            />

            {/* ALERT TOAST */}
            {alert && (
                <div 
                    role="status" 
                    aria-live="polite" 
                    style={{ position: 'fixed', bottom: '2rem', right: '2rem', zIndex: 1000000, animation: 'slideUp 0.3s ease-out' }}
                >
                   <div style={{ 
                       background: 'rgba(0,0,0,0.8)', 
                       backdropFilter: 'blur(20px)', 
                       border: `1px solid ${alert.type === 'error' ? '#ef4444' : (alert.type === 'success' ? '#10b981' : '#facc15')}`,
                       padding: '1rem 1.5rem',
                       borderRadius: '16px',
                       display: 'flex',
                       alignItems: 'center',
                       gap: '12px',
                       boxShadow: '0 20px 40px rgba(0,0,0,0.4)'
                   }}>
                       {alert.type === 'error' ? <AlertCircle color="#ef4444" aria-hidden="true" /> : <CheckCircle color="#10b981" aria-hidden="true" />}
                       <span style={{ color: '#fff', fontWeight: 700, fontSize: '0.9rem' }}>{alert.message}</span>
                       <button 
                           aria-label={t('common.dismiss', 'Descartar notificación')} 
                           type="button" 
                           onClick={() => setAlert(null)} 
                           style={{ background: 'none', border: 'none', color: 'rgba(255,255,255,0.3)', cursor: 'pointer', padding: '4px' }}
                       >
                           <X aria-hidden="true" />
                       </button>
                   </div>
                </div>
            )}
        </div>
    );
}

import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { Crown, X, Loader2, Globe, CheckCircle } from 'lucide-react';
import { supabase } from '../../../services/supabaseClient';
import { getAuthHeaders } from '../../../services/adminAuth';

const API_URL = import.meta.env.VITE_API_URL || '/api';

export interface Donor {
    id: string; 
    name: string;
    skinUrl: string;
    description: string;
    description_en?: string;
    ranks: string[];
    isPremium?: boolean;
}

interface DonorFormModalProps {
    donor: Donor | null;
    isNew: boolean;
    onClose: () => void;
    onSave: (donor: Donor) => void;
    saving: boolean;
}

const AVAILABLE_RANKS = [
    { id: 'donador', label: 'Donador', img: '/ranks/rank-donador.png' },
    { id: 'fundador', label: 'Fundador', img: '/ranks/rank-fundador.png' },
    { id: 'killu', label: 'Killu', img: '/ranks/rank-killu.png' },
    { id: 'neroferno', label: 'Neroferno', img: '/ranks/rank-neroferno.png' },
    { id: 'developer', label: 'Developer', img: '/ranks/developer.png' },
    { id: 'admin', label: 'Admin', img: '/ranks/admin.png' },
    { id: 'mod', label: 'Moderator', img: '/ranks/moderator.png' },
    { id: 'helper', label: 'Helper', img: '/ranks/helper.png' },
    { id: 'staff', label: 'Staff', img: '/ranks/staff.png' },
];

export default function DonorFormModal({ donor, isNew, onClose, onSave, saving }: DonorFormModalProps) {
    const { t } = useTranslation();
    const [formData, setFormData] = useState<Donor>({
        id: '',
        name: '',
        skinUrl: '',
        description: '',
        description_en: '',
        ranks: ['donador'],
        isPremium: false
    });
    const [translating, setTranslating] = useState(false);

    useEffect(() => {
        if (donor) {
            setFormData(donor);
        }
    }, [donor]);

    const handleTranslate = async (text: string, toLang: 'es' | 'en', field: 'description' | 'description_en') => {
        if (!text) return;
        setTranslating(true);
        try {
            const { data: { session } } = await supabase.auth.getSession();
            const res = await fetch(`${API_URL}/translation`, {
                method: 'POST',
                headers: { 
                    'Content-Type': 'application/json',
                    ...getAuthHeaders(session?.access_token || null)
                },
                body: JSON.stringify({ text, targetLang: toLang })
            });
            if (!res.ok) throw new Error('Translation failed');
            const data = await res.json();
            if (data.success) {
                setFormData(prev => ({ ...prev, [field]: data.translatedText }));
            }
        } catch (e) {
            console.error("Translation fail", e instanceof Error ? e.message : 'Unknown error');
            // Error handling could be passed up via callback if needed, 
            // but for now logging is sufficient as UI feedback is limited in this scope
        } finally {
            setTranslating(false);
        }
    };

    const handleSubmit = () => {
        // Validation could be added here
        onSave(formData);
    };

    if (!donor) return null;

    return (
        <div className="sync-modal-overlay" role="presentation">
            <div className="sync-modal-content" role="dialog" aria-modal="true" aria-labelledby="donor-modal-title" style={{ maxWidth: '850px' }}>
                <div className="modal-accent-line"></div>

                <div className="poll-form-header">
                    <h3 id="donor-modal-title" style={{ margin: 0, display: 'flex', alignItems: 'center', gap: '12px', color: '#fff', fontSize: '1.5rem', fontWeight: '900' }}>
                        <Crown style={{ color: 'var(--accent)' }} aria-hidden="true" />
                        {isNew ? t('admin.donors.new_title') : t('admin.donors.edit_title')}
                    </h3>
                    <button 
                        aria-label={t('common.close', 'Cerrar ventana')} 
                        type="button" 
                        onClick={onClose} 
                        className="btn-close-mini"
                    >
                        <X aria-hidden="true" />
                    </button>
                </div>

                <div className="poll-form-body" style={{ overflowY: 'auto', maxHeight: '70vh', padding: '0.5rem' }}>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '2rem' }}>
                        {/* Left Side: Basic Info */}
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                            <div className="form-group">
                                <label htmlFor="donor-nick" className="admin-label-premium">{t('admin.donors.form.nick')}</label>
                                <input id="donor-nick"
                                    className="admin-input-premium" 
                                    value={formData.name} 
                                    onChange={e => setFormData({...formData, name: e.target.value})}
                                    placeholder={t('admin.donors.form.nick_ph')}
                                />
                            </div>

                            <div className="form-group">
                                <div style={{ display: 'flex', alignItems: 'center', gap: '12px', background: 'rgba(255,255,255,0.03)', padding: '1rem', borderRadius: '16px', border: '1px solid rgba(255,255,255,0.05)' }}>
                                    <input 
                                        aria-label={t('admin.donors.form.is_premium', 'Es donador premium')} 
                                        type="checkbox" 
                                        id="isPremiumDonor"
                                        checked={formData.isPremium || false}
                                        onChange={e => setFormData({...formData, isPremium: e.target.checked})}
                                        style={{ width: '20px', height: '20px', cursor: 'pointer' }}
                                    />
                                    <label htmlFor="isPremiumDonor" style={{ cursor: 'pointer', fontSize: '0.95rem', color: '#fff', fontWeight: 700 }}>
                                        {t('admin.donors.form.is_premium')}
                                    </label>
                                </div>
                            </div>

                            {!formData.isPremium && (
                                <div className="form-group">
                                    <label htmlFor="donor-skin-url" className="admin-label-premium">{t('admin.donors.form.skin_url')}</label>
                                    <input id="donor-skin-url"
                                        className="admin-input-premium" 
                                        value={formData.skinUrl} 
                                        onChange={e => setFormData({...formData, skinUrl: e.target.value})}
                                        placeholder={t('admin.donors.form.skin_ph')}
                                    />
                                    <p style={{ fontSize: '0.75rem', color: 'rgba(255,255,255,0.3)', marginTop: '0.5rem' }}>
                                        {t('admin.donors.form.skin_hint')}
                                    </p>
                                </div>
                            )}

                            <div className="form-group">
                                <div className="admin-label-premium">{t('admin.donors.form.ranks')}</div>
                                <div className="donor-ranks-selector">
                                    {AVAILABLE_RANKS.map(rank => {
                                        const isSelected = formData.ranks.includes(rank.id);
                                        return (
                                            <button
                                                type="button"
                                                key={rank.id}
                                                aria-pressed={isSelected}
                                                onClick={() => {
                                                    const newRanks = isSelected
                                                        ? formData.ranks.filter(r => r !== rank.id)
                                                        : [...formData.ranks, rank.id];
                                                    setFormData({...formData, ranks: newRanks});
                                                }}
                                                className={`rank-select-item ${isSelected ? 'active' : ''}`}
                                            >
                                                <img src={rank.img} alt={rank.label} />
                                                <span>{rank.label}</span>
                                            </button>
                                        )
                                    })}
                                </div>
                            </div>
                        </div>

                        {/* Right Side: Descriptions & Preview */}
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                            <div className="form-group">
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
                                    <label htmlFor="donor-desc" className="admin-label-premium">{t('admin.donors.form.desc')}</label>
                                    <button 
                                        type="button"
                                        className="btn-premium-mini" 
                                        onClick={() => handleTranslate(formData.description, 'en', 'description_en')}
                                        disabled={translating || !formData.description}
                                    >
                                        {translating ? <Loader2 className="spin" size={14} /> : <Globe size={14} />} 
                                        {t('admin.donors.form.translate_en')}
                                    </button>
                                </div>
                                <textarea id="donor-desc" 
                                    className="admin-textarea-premium" 
                                    value={formData.description} 
                                    onChange={e => setFormData({...formData, description: e.target.value})}
                                    placeholder={t('admin.donors.form.desc_ph')}
                                    rows={3}
                                />
                            </div>

                            <div className="form-group">
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
                                    <label htmlFor="donor-desc-en" className="admin-label-premium">{t('admin.donors.form.desc_en')}</label>
                                    <button 
                                        type="button"
                                        className="btn-premium-mini" 
                                        onClick={() => handleTranslate(formData.description_en || '', 'es', 'description')}
                                        disabled={translating || !formData.description_en}
                                    >
                                        {translating ? <Loader2 className="spin" size={14} /> : <Globe size={14} />} 
                                        {t('admin.donors.form.translate_es')}
                                    </button>
                                </div>
                                <textarea id="donor-desc-en" 
                                    className="admin-textarea-premium" 
                                    value={formData.description_en || ''} 
                                    onChange={e => setFormData({...formData, description_en: e.target.value})}
                                    placeholder={t('admin.donors.form.desc_en_ph')}
                                    rows={3}
                                />
                            </div>

                            <div className="donor-preview-pane">
                                <span style={{ fontSize: '0.7rem', fontWeight: 900, color: 'rgba(255,255,255,0.2)', textTransform: 'uppercase', letterSpacing: '0.1em' }}>Preview</span>
                                <div className="donor-card-premium" style={{ width: '100%', pointerEvents: 'none', background: 'rgba(255,255,255,0.02)' }}>
                                    <div className="donor-card-header">
                                        <div className="donor-avatar-wrapper">
                                            <img 
                                                className="donor-avatar"
                                                src={formData.isPremium ? `https://mc-heads.net/avatar/${formData.name}/64` : formData.skinUrl} 
                                                alt="preview"
                                                onError={(e) => e.currentTarget.src = `https://mc-heads.net/avatar/Steve/64`}
                                            />
                                        </div>
                                        <div className="donor-info">
                                            <h4 className="donor-name">{formData.name || 'New Donor'}</h4>
                                            <div className="donor-ranks">
                                                {formData.ranks.map(r => (
                                                    <span key={r} className="donor-rank-badge">{r}</span>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                    <p className="donor-description" style={{ fontSize: '0.8rem' }}>"{formData.description || 'Description goes here...'}"</p>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="poll-form-footer" style={{ marginTop: '2.5rem', padding: '1.5rem 2.5rem' }}>
                        <button type="button" className="modal-btn-secondary" onClick={onClose} style={{ height: '52px' }}>
                            {t('admin.donors.form.cancel')}
                        </button>
                        <button type="button" 
                            className="modal-btn-primary" 
                            onClick={handleSubmit} 
                            disabled={saving} 
                            style={{ height: '52px', padding: '0 3rem', flex: 'none' }}
                        >
                            {saving ? <Loader2 className="spin" /> : <><CheckCircle size={20} /> {t('admin.donors.form.save')}</>}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

import { useState, useEffect } from "react";
import { Users, X } from "lucide-react";
import { useTranslation } from "react-i18next";
import Loader from "../../UI/Loader";
import { supabase } from "../../../services/supabaseClient";
import { getAuthHeaders } from "../../../services/adminAuth";
import { Registration } from "./types";

interface RegistrationsModalProps {
  eventId: number;
  onClose: () => void;
  API_URL: string;
  mockRegistrations?: Registration[];
}

export default function RegistrationsModal({
  eventId,
  onClose,
  API_URL,
  mockRegistrations,
}: RegistrationsModalProps) {
  const { t } = useTranslation();
  const [registrations, setRegistrations] = useState<Registration[]>(
    mockRegistrations || [],
  );
  const [loading, setLoading] = useState(!mockRegistrations);

  useEffect(() => {
    let ignore = false;
    const fetchReg = async () => {
      if (mockRegistrations) return;
      try {
        const {
          data: { session },
        } = await supabase.auth.getSession();
        const res = await fetch(`${API_URL}/events/${eventId}/registrations`, {
          headers: getAuthHeaders(session?.access_token || null),
        });
        if (res.ok) {
          const data = await res.json();
          if (!ignore) setRegistrations(data);
        }
      } catch (e) {
        console.error(e);
      } finally {
        if (!ignore) setLoading(false);
      }
    };
    fetchReg();
    return () => {
      ignore = true;
    };
  }, [eventId, API_URL, mockRegistrations]);

  return (
    <div
      className="sync-modal-overlay"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
      role="presentation"
    >
      <div
        className="sync-modal-content poll-modal-content"
        role="dialog"
        aria-modal="true"
        aria-labelledby="registrations-modal-title"
        style={{
          maxWidth: "550px",
          maxHeight: "85vh",
          display: "flex",
          flexDirection: "column",
        }}
      >
        <div className="modal-accent-line"></div>

        <div
          className="poll-form-header"
          style={{
            padding: "2rem 2.5rem",
            borderBottom: "1px solid rgba(255,255,255,0.05)",
          }}
        >
          <h3
            id="registrations-modal-title"
            style={{
              margin: 0,
              display: "flex",
              alignItems: "center",
              gap: "12px",
              fontSize: "1.4rem",
              fontWeight: "900",
              color: "#fff",
            }}
          >
            <Users style={{ color: "var(--accent)" }} aria-hidden="true" />
            {t("admin.events.registrations.title")}{" "}
            <span className="tabular-nums">({registrations.length})</span>
          </h3>
          <button
            aria-label={t("common.close", "Cerrar ventana")}
            type="button"
            onClick={onClose}
            className="btn-close-mini"
          >
            <X aria-hidden="true" />
          </button>
        </div>

        <div style={{ flex: 1, overflowY: "auto", padding: "2rem 2.5rem" }}>
          {loading ? (
            <div
              style={{
                padding: "4rem 0",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: "1.5rem",
              }}
            >
              <Loader style={{ height: "auto", minHeight: "60px" }} />
              <span
                style={{
                  fontSize: "0.9rem",
                  color: "rgba(255,255,255,0.3)",
                  fontWeight: "800",
                  textTransform: "uppercase",
                  letterSpacing: "1px",
                }}
              >
                {t("admin.events.registrations.loading")}
              </span>
            </div>
          ) : registrations.length === 0 ? (
            <div
              className="poll-empty-state"
              style={{ padding: "3rem 1rem", marginTop: 0 }}
            >
              <Users size={40} style={{ color: "rgba(255,255,255,0.05)" }} />
              <p style={{ color: "rgba(255,255,255,0.2)", fontWeight: "800" }}>
                {t("admin.events.registrations.empty")}
              </p>
            </div>
          ) : (
            <div
              style={{ display: "flex", flexDirection: "column", gap: "1rem" }}
            >
              {registrations.map((reg) => (
                <div key={reg.id} className="registration-item">
                  <div className="reg-avatar-ring">
                    <div className="reg-avatar-content">
                      {reg.profiles?.avatar_url ? (
                        <img
                          src={reg.profiles.avatar_url}
                          style={{
                            width: "100%",
                            height: "100%",
                            objectFit: "cover",
                          }}
                          alt="avatar"
                        />
                      ) : (
                        <div
                          style={{
                            color: "rgba(255,255,255,0.2)",
                            fontSize: "1rem",
                            fontWeight: "900",
                          }}
                        >
                          CT
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="reg-info">
                    <div className="reg-name">
                      {reg.profiles?.username ||
                        t("admin.events.registrations.unknown_user")}
                    </div>
                    <div className="reg-date">
                      {new Date(reg.created_at).toLocaleDateString()}
                    </div>
                  </div>
                  <div
                    style={{
                      width: 10,
                      height: 10,
                      borderRadius: "50%",
                      background: "var(--accent)",
                      boxShadow: "0 0 10px var(--accent)",
                    }}
                  ></div>
                </div>
              ))}
            </div>
          )}
        </div>

        <div
          style={{
            padding: "1.5rem 2.5rem",
            borderTop: "1px solid rgba(255,255,255,0.05)",
            display: "flex",
            justifyContent: "flex-end",
          }}
        >
          <button
            type="button"
            onClick={onClose}
            className="modal-btn-primary"
            style={{ height: "44px", padding: "0 2rem" }}
          >
            {t("admin.events.close_btn", "Cerrar")}
          </button>
        </div>
      </div>
    </div>
  );
}

