const convertFileToWebP = (file: File): Promise<Blob> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader()
        reader.onload = (e) => {
            const img = new Image()
            img.onload = () => {
                const canvas = document.createElement('canvas')
                canvas.width = img.width
                canvas.height = img.height
                const ctx = canvas.getContext('2d')
                if (!ctx) {
                    reject(new Error('No canvas context'))
                    return
                }
                ctx.drawImage(img, 0, 0)
                canvas.toBlob((blob) => {
                    if (blob) resolve(blob)
                    else reject(new Error('Conversion failed'))
                }, 'image/webp', 0.8)
            }
            img.onerror = reject
            img.src = e.target?.result as string
        }
        reader.onerror = reject
        reader.readAsDataURL(file)
    })
}

export default function NewsForm({ initialData, onSave, onCancel }: NewsFormProps) {
    const { t } = useTranslation()
    const contentFileInputRef = useRef<HTMLInputElement>(null)
    const [uploading, setUploading] = useState(false)
    const [uploadError, setUploadError] = useState<string | null>(null)
    const [translating, setTranslating] = useState(false)

    const API_URL = import.meta.env.VITE_API_URL || '/api'; 

    const { register, handleSubmit, setValue, watch, formState: { errors, isSubmitting } } = useForm<NewsFormValues>({
        resolver: zodResolver(newsSchema),
        defaultValues: initialData || {
            title: "", 
            title_en: "", 
            category: "General", 
            content: "", 
            content_en: "", 
            status: "Draft",
            image: ""
        }
    })

    // Watch fields for translation buttons
    const title = watch("title");
    const title_en = watch("title_en");
    const content = watch("content");
    const content_en = watch("content_en");


    const uploadImage = async (file: File): Promise<string | null> => {
        try {
            setUploading(true)
            setUploadError(null)

            const webpBlob = await convertFileToWebP(file)
            // Server-validated upload (magic bytes checked in backend)
            return await uploadImageSecure(webpBlob, 'forum-uploads', 'news')
        } catch (error: unknown) {
            console.error('Error uploading image:', error)
            setUploadError((error as Error).message || t('admin.news.upload_error_unknown'))
            return null
        } finally {
            setUploading(false)
        }
    }

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (!e.target.files || e.target.files.length === 0) return
        const file = e.target.files[0]
        const url = await uploadImage(file)
        if (url) {
            setValue("image", url, { shouldValidate: true })
        }
    }

    const handleContentImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (!e.target.files || e.target.files.length === 0) return
        const file = e.target.files[0]
        const url = await uploadImage(file)
        if (url) {
            const currentContent = watch("content") || ""
            const imageMarkdown = `\n![Imagen](${url})\n`
            setValue("content", currentContent + imageMarkdown, { shouldValidate: true })
        }
        if (contentFileInputRef.current) contentFileInputRef.current.value = ''
    }

    const handleTranslate = async (text: string, toLang: 'es' | 'en', field: 'title' | 'content' | 'title_en' | 'content_en') => {
        if (!text) return
        setTranslating(true)
        try {
            const { data: { session } } = await supabase.auth.getSession()
            const token = session?.access_token

            const res = await fetch(`${API_URL}/translation`, {
                method: 'POST',
                headers: { 
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify({ text, targetLang: toLang })
            })
            if (!res.ok) throw new Error('Translation failed')
            const data = await res.json()
            if (data.success) {
                setValue(field, data.translatedText, { shouldValidate: true })
            }
        } catch (error) {
            console.error("Translation fail", error)
        } finally {
            setTranslating(false)
        }
    }

    return (
        <div className="news-form-container">
            <div className="news-header" style={{ marginBottom: '2rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem' }}>
                <h3 style={{ margin: 0, fontSize: 'clamp(1.25rem, 4vw, 1.5rem)', fontWeight: 900, color: '#fff' }}>
                    {initialData?.id ? t('admin.news.edit_title') : t('admin.news.create_title')}
                </h3>
                <button type="button" className="btn-secondary" onClick={onCancel} style={{ borderRadius: '12px', height: '42px', flex: '1 1 auto', minWidth: '120px' }}>
                    {t('admin.news.cancel')}
                </button>
            </div>

            <div className="poll-active-card" style={{ padding: '3rem', maxWidth: '100%', borderRadius: '32px' }}>
                <div className="modal-accent-line"></div>
                <form onSubmit={handleSubmit(onSave)} className="news-form-grid">

                    {/* LEFT COLUMN: Spanish & Settings */}
                    <div className="news-form-section">
                        <h4><img alt="" src="/images/ui/logo.webp" width="20" style={{ verticalAlign: 'middle', marginRight: '8px' }} /> {t('admin.news.form_extras.config_es', 'Contenido en Español')}</h4>

                        <div className="form-group">
                            <label htmlFor="news-form-title" className="admin-label-premium">{t('admin.news.form.title')}</label>
                            <input
                                id="news-form-title"
                                aria-label={t('admin.news.form.title')}
                                type="text"
                                className="admin-input-premium"
                                {...register("title")}
                                placeholder="Escribe un título impactante..."
                            />
                            {errors.title && <span style={{color: '#ef4444', fontSize: '0.75rem', fontWeight: 700, marginTop: '5px', display: 'block'}}>{errors.title.message}</span>}

                            <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.75rem' }}>
                                <button 
                                    type="button"
                                    className="btn-translate-premium"
                                    onClick={() => handleTranslate(title, 'en', 'title_en')}
                                    disabled={translating || !title}
                                >
                                    {translating ? <Loader2 className="spin" /> : <Languages />} {t('admin.news.translate_to_en_title')}
                                </button>
                            </div>
                        </div>

                        <div className="form-group">
                            <label htmlFor="news-form-content" className="admin-label-premium">{t('admin.news.form.content')}</label>
                            <div style={{ position: 'relative' }}>
                                <textarea
                                    id="news-form-content"
                                    aria-label={t('admin.news.form.content')}
                                    className="admin-textarea-premium"
                                    rows={12}
                                    {...register("content")}
                                    placeholder="Desarrolla la noticia aquí..."
                                ></textarea>
                                <button 
                                    type="button" 
                                    onClick={() => contentFileInputRef.current?.click()} 
                                    className="btn-translate-premium" 
                                    style={{ position: 'absolute', bottom: '1rem', right: '1rem', background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(10px)' }}
                                    disabled={uploading}
                                >
                                    <ImageIcon /> {t('admin.news.insert_image')}
                                </button>
                                <input 
                                    aria-label={t('admin.news.upload_content_image', 'Subir imagen para el contenido de la noticia')} 
                                    type="file" 
                                    ref={contentFileInputRef} 
                                    style={{display: 'none'}} 
                                    accept="image/*" 
                                    onChange={handleContentImageUpload}
                                />
                            </div>
                            {errors.content && <span style={{color: '#ef4444', fontSize: '0.75rem', fontWeight: 700, marginTop: '5px', display: 'block'}}>{errors.content.message}</span>}

                            <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.75rem' }}>
                                <button 
                                    type="button"
                                    className="btn-translate-premium"
                                    onClick={() => handleTranslate(content, 'en', 'content_en')}
                                    disabled={translating || !content}
                                >
                                    {translating ? <Loader2 className="spin" /> : <Languages />} {t('admin.news.translate_to_en_content')}
                                </button>
                            </div>
                        </div>

                        <div className="news-selectors-grid" style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: "1.5rem" }}>
                            <div className="form-group">
                                <label htmlFor="news-form-category" className="admin-label-premium">{t('admin.news.form.category')}</label>
                                <select id="news-form-category" aria-label={t('admin.news.form.category')} className="admin-select-premium" {...register("category")}>
                                    <option value="General">General</option>
                                    <option value="Evento">Evento</option>
                                    <option value="Update">Update</option>
                                    <option value="Sistema">Sistema</option>
                                    <option value="Comunidad">Comunidad</option>
                                </select>
                            </div>
                            <div className="form-group">
                                <label htmlFor="news-form-status" className="admin-label-premium">{t('admin.news.form.status')}</label>
                                <select id="news-form-status" aria-label={t('admin.news.form.status')} className="admin-select-premium" {...register("status")}>
                                    <option value="Draft">{t('admin.news.form.draft')}</option>
                                    <option value="Published">{t('admin.news.form.published')}</option>
                                </select>
                            </div>
                        </div>
                    </div>

                    {/* RIGHT COLUMN: English & Image */}
                    <div className="news-form-section">
                        <h4><Languages /> {t('admin.news.form_extras.config_en', 'English Version')}</h4>

                        <div className="form-group">
                            <label htmlFor="news-form-title-en" className="admin-label-premium">{t('admin.news.form.title')} {t('admin.news.english_suffix')}</label>
                            <input
                                id="news-form-title-en"
                                aria-label={t('admin.news.form.title')}
                                type="text"
                                className="admin-input-premium"
                                {...register("title_en")}
                                placeholder="Catchy title in English..."
                            />
                            {errors.title_en && <span style={{color: '#ef4444', fontSize: '0.75rem', fontWeight: 700, marginTop: '5px', display: 'block'}}>{errors.title_en.message}</span>}

                            <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.75rem' }}>
                                <button 
                                    type="button"
                                    className="btn-translate-premium"
                                    onClick={() => handleTranslate(title_en || '', 'es', 'title')}
                                    disabled={translating || !title_en}
                                >
                                    {translating ? <Loader2 className="spin" /> : <Languages />} {t('admin.news.translate_to_es_title')}
                                </button>
                            </div>
                        </div>

                        <div className="form-group">
                            <label htmlFor="news-form-content-en" className="admin-label-premium">{t('admin.news.form.content')} {t('admin.news.english_suffix')}</label>
                            <textarea
                                id="news-form-content-en"
                                aria-label={t('admin.news.form.content')}
                                className="admin-textarea-premium"
                                rows={12}
                                {...register("content_en")}
                                placeholder="Develop the news content in English..."
                            ></textarea>
                            {errors.content_en && <span style={{color: '#ef4444', fontSize: '0.75rem', fontWeight: 700, marginTop: '5px', display: 'block'}}>{errors.content_en.message}</span>}

                            <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.75rem' }}>
                                <button 
                                    type="button"
                                    className="btn-translate-premium"
                                    onClick={() => handleTranslate(content_en || '', 'es', 'content')}
                                    disabled={translating || !content_en}
                                >
                                    {translating ? <Loader2 className="spin" /> : <Languages />} {t('admin.news.translate_to_es_content')}
                                </button>
                            </div>
                        </div>

                        <div className="form-group">
                            <label htmlFor="news-form-image" className="admin-label-premium">{t('admin.news.form.image')}</label>
                            <div className="news-img-preview-wrapper" style={{ marginBottom: '1rem' }}>
                                {watch("image") ? (
                                    <img src={watch("image")} className="news-img-preview" alt="Preview" />
                                ) : (
                                    <div style={{ textAlign: 'center', opacity: 0.3 }}>
                                        <ImageIcon size={40} style={{ marginBottom: '10px' }} />
                                        <p style={{ fontSize: '0.8rem', fontWeight: 800 }}>SIN IMAGEN PORTADA</p>
                                    </div>
                                )}
                                {uploading && (
                                    <div className="news-upload-loading">
                                        <Loader2 className="spin" size={24} />
                                        <span>SUBIENDO...</span>
                                    </div>
                                )}
                            </div>

                            <div style={{ display: 'flex', gap: '1rem' }}>
                                <input id="news-form-image"
                                    type="text"
                                    className="admin-input-premium"
                                    placeholder="https://su-imagen.webp"
                                    {...register("image")}
                                    style={{ flex: 1 }}
                                />
                                <button 
                                    type="button"
                                    aria-label="Subir imagen"
                                    className="modal-btn-primary"
                                    style={{ width: '54px', height: '54px', borderRadius: '14px', flexShrink: 0 }}
                                    onClick={() => {
                                        const input = document.createElement('input');
                                        input.type = 'file';
                                        input.accept = 'image/*';
                                        input.onchange = (e: Event) => handleImageUpload(e as unknown as React.ChangeEvent<HTMLInputElement>);
                                        input.click();
                                    }}
                                    disabled={uploading}
                                >
                                    <ImageIcon size={20} />
                                </button>
                            </div>
                            {uploadError && (
                                <div style={{ background: 'rgba(239, 68, 68, 0.1)', color: '#ef4444', padding: '1rem', borderRadius: '12px', fontSize: '0.8rem', fontWeight: 700, marginTop: '1rem', display: 'flex', alignItems: 'center', gap: '10px' }}>
                                    <AlertTriangle /> {uploadError}
                                </div>
                            )}
                        </div>
                    </div>

                    <div className="news-form-footer" style={{ gridColumn: '1 / -1', marginTop: '2rem', display: 'flex', justifyContent: 'flex-end', gap: '1.5rem', borderTop: '1px solid rgba(255,255,255,0.05)', paddingTop: '2.5rem', flexWrap: 'wrap' }}>
                        <button type="button" onClick={onCancel} className="modal-btn-secondary" style={{ flex: '1 1 auto', minWidth: '140px', height: '54px', padding: '0 2rem' }}>
                            {t('admin.news.cancel')}
                        </button>
                        <button type="submit" className="modal-btn-primary" style={{ flex: '1 1 auto', minWidth: '140px', height: '54px', padding: '0 2rem' }} disabled={isSubmitting}>
                            {isSubmitting ? <Loader2 className="spin" /> : (initialData?.id ? t('admin.news.form.save') : t('admin.news.form.publish'))}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    )
}

import { useState } from 'react'
import { BarChart3, Plus, History } from 'lucide-react'
import { useTranslation } from 'react-i18next'
import Loader from "../UI/Loader"

import { 
    useAdminActivePoll, 
    useAdminPolls, 
    useCreatePoll, 
    useUpdatePoll, 
    useClosePoll, 
    useDeletePoll,
    useTranslateText
} from "../../hooks/useAdminData"

import { Poll } from './Polls/types'
import PollActiveCard from './Polls/PollActiveCard'
import PollHistoryTable from './Polls/PollHistoryTable'
import PollFormModal from './Polls/PollFormModal'
import PollDeleteModal from './Polls/PollDeleteModal'

interface PollsManagerProps {
    mockActivePoll?: Poll | null;
    mockHistoryPolls?: Poll[];
}

export default function PollsManager({ mockActivePoll, mockHistoryPolls }: PollsManagerProps = {}) {
    const { t } = useTranslation()
    const [tab, setTab] = useState<'active' | 'history'>('active')
    const [page, setPage] = useState(1)

    // TanStack Query Hooks
    const { data: fetchActiveData, isLoading: loadingPoll } = useAdminActivePoll();
    const { data: historyData, isLoading: historyLoading } = useAdminPolls(page);

    const createMutation = useCreatePoll();
    const updateMutation = useUpdatePoll();
    const closeMutation = useClosePoll();
    const deleteMutation = useDeletePoll();
    const translateMutation = useTranslateText();

    // UI Flow States
    const [showModal, setShowModal] = useState(false)
    const [editingPoll, setEditingPoll] = useState<Poll | null>(null)
    const [showDeleteModal, setShowDeleteModal] = useState<number | null>(null)
    const [buttonSuccess, setButtonSuccess] = useState(false)
    const [translatingField, setTranslatingField] = useState<string | null>(null)
    const [translatedValues, setTranslatedValues] = useState<{ title?: string, question?: string, option?: {idx: number, val: string} }>({})

    const activePoll = mockActivePoll !== undefined ? mockActivePoll : (fetchActiveData || null);
    const historyPolls = mockHistoryPolls || historyData?.data || [];
    const totalPages = historyData?.totalPages || 1;

    // Handlers
    const handleEdit = (poll: Poll) => {
        setEditingPoll(poll);
        setShowModal(true);
    }

    const onCreateOpen = () => {
        setEditingPoll(null);
        setShowModal(true);
    }

    interface PollFormData {
        title: string;
        titleEn: string;
        question: string;
        questionEn: string;
        options: { label: string; labelEn?: string }[];
        daysDuration: number;
    }

    const handleFormSubmit = async (_e: React.FormEvent, data: PollFormData) => {
        const validOptions = data.options.filter((o: { label: string }) => o.label.trim() !== '')
        if (validOptions.length < 2) {
            alert(t('admin.polls.form.error_options'))
            return
        }

        const closesAt = new Date(Date.now() + data.daysDuration * 24 * 60 * 60 * 1000).toISOString()
        const payloadOptions = validOptions.map((o: { label: string; labelEn?: string }) => ({
            label: o.label,
            label_en: o.labelEn
        }))

        const payload = { 
            title: data.title, 
            title_en: data.titleEn, 
            question: data.question, 
            question_en: data.questionEn,
            options: payloadOptions,
            closes_at: closesAt
        }

        const mutationOptions = {
            onSuccess: () => {
                setButtonSuccess(true)
                setTimeout(() => {
                    setButtonSuccess(false)
                    setShowModal(false)
                    setEditingPoll(null)
                }, 1500)
            },
            onError: () => {
                alert(t('admin.polls.form.error_create'))
            }
        };

        if (editingPoll) {
            updateMutation.mutate({ id: editingPoll.id, payload }, mutationOptions);
        } else {
            createMutation.mutate(payload, mutationOptions);
        }
    }

    const handleClosePoll = (id: number) => {
        if(!window.confirm(t('admin.polls.confirm_close'))) return
        closeMutation.mutate(id);
    }

    const handleDelete = (id: number) => {
        deleteMutation.mutate(id, {
            onSuccess: () => setShowDeleteModal(null)
        });
    }

    // Translation
    const handleTranslate = async (text: string, targetField: string, index?: number) => {
        if (!text) return
        const fieldKey = targetField === 'options' ? `option-${index}` : targetField;
        setTranslatingField(fieldKey)

        translateMutation.mutate({ text }, {
            onSuccess: (translated) => {
                if (targetField === 'title') setTranslatedValues(prev => ({ ...prev, title: translated }))
                else if (targetField === 'question') setTranslatedValues(prev => ({ ...prev, question: translated }))
                else if (targetField === 'options' && index !== undefined) {
                    setTranslatedValues(prev => ({ ...prev, option: {idx: index, val: translated} }))
                }
            },
            onSettled: () => setTranslatingField(null)
        });
    }

    return (
        <div className="poll-manager-container">
            <div className="poll-header">
                <div className="poll-tabs-wrapper">
                    <button type="button" 
                        onClick={() => setTab('active')}
                        className={`poll-tab-btn ${tab === 'active' ? 'active' : ''}`}
                    >
                        <BarChart3 size={18} /> {t('admin.polls.tabs.active')}
                    </button>
                    <button type="button" 
                        onClick={() => setTab('history')}
                        className={`poll-tab-btn ${tab === 'history' ? 'active' : ''}`}
                    >
                        <History size={18} /> {t('admin.polls.tabs.history')}
                    </button>
                </div>

                <button type="button" onClick={onCreateOpen} className="btn-primary poll-new-btn">
                    <Plus size={16} /> {t('admin.polls.new_btn')}
                </button>
            </div>

            {tab === 'active' ? (
                loadingPoll ? (
                    <div style={{ padding: '6rem', display: 'flex', justifyContent: 'center' }}>
                        <Loader style={{ height: 'auto', minHeight: '100px' }} />
                    </div>
                ) : (
                    <PollActiveCard 
                        poll={activePoll} 
                        onEdit={handleEdit} 
                        onDelete={(id) => setShowDeleteModal(id)}
                        onClose={handleClosePoll}
                        onCreate={onCreateOpen}
                    />
                )
            ) : (
                <PollHistoryTable 
                    polls={historyPolls}
                    loading={historyLoading}
                    page={page}
                    totalPages={totalPages}
                    onPageChange={setPage}
                    onDelete={(id) => setShowDeleteModal(id)}
                    onClose={handleClosePoll}
                />
            )}

            {showModal && (
                <PollFormModal 
                    onClose={() => { setShowModal(false); setEditingPoll(null); }}
                    onSubmit={handleFormSubmit}
                    poll={editingPoll}
                    creating={createMutation.isPending || updateMutation.isPending}
                    buttonSuccess={buttonSuccess}
                    hasActivePoll={!!activePoll}
                    onTranslate={handleTranslate}
                    translatingField={translatingField}
                    translatedValues={translatedValues}
                />
            )}

            {showDeleteModal && (
                <PollDeleteModal 
                    onConfirm={() => handleDelete(showDeleteModal)}
                    onCancel={() => setShowDeleteModal(null)}
                />
            )}
        </div>
    )
}

import { useState, useEffect, useCallback } from 'react';
import { BarChart3, X, Plus, Loader2, Languages, Check } from 'lucide-react';

import { useTranslation } from 'react-i18next';
import { Poll } from './types';

interface PollFormModalProps {
    onClose: () => void;
    onSubmit: (e: React.FormEvent, data: { title: string, titleEn: string, question: string, questionEn: string, options: {label: string, labelEn: string}[], daysDuration: number }) => Promise<void>;
    poll?: Poll | null;
    creating: boolean;
    buttonSuccess: boolean;
    hasActivePoll: boolean;
    onTranslate: (text: string, targetField: string, index?: number) => void;
    translatingField: string | null;
    translatedValues: { title?: string, question?: string, option?: {idx: number, val: string} };
}

export default function PollFormModal({ onClose, onSubmit, poll, creating, buttonSuccess, hasActivePoll, onTranslate, translatingField, translatedValues }: PollFormModalProps) {
    const { t } = useTranslation();
    const isEdit = !!poll;

    const [title, setTitle] = useState('');
    const [titleEn, setTitleEn] = useState('');
    const [question, setQuestion] = useState('');
    const [questionEn, setQuestionEn] = useState('');
    const [options, setOptions] = useState<{label: string, labelEn: string}[]>([{label: '', labelEn: ''}, {label: '', labelEn: ''}]);
    const [daysDuration, setDaysDuration] = useState(7);

    const updateOption = useCallback((idx: number, field: 'label' | 'labelEn', val: string) => {
        setOptions(prev => {
            const newOpts = [...prev];
            newOpts[idx] = { ...newOpts[idx], [field]: val };
            return newOpts;
        });
    }, []);

    const removeOption = useCallback((idx: number) => {
        setOptions(prev => prev.filter((_, i) => i !== idx));
    }, []);

    // Initial load
    useEffect(() => {
        if (poll) {
             if (poll.title !== title) setTitle(poll.title);
             if ((poll.title_en || '') !== titleEn) setTitleEn(poll.title_en || '');
             if (poll.question !== question) setQuestion(poll.question);
             if ((poll.question_en || '') !== questionEn) setQuestionEn(poll.question_en || '');

             // Always reset options for simplicity when poll changes
             const mappedOptions = poll.options.map(o => ({
                 label: o.label,
                 labelEn: o.label_en || ''
             }));
             while (mappedOptions.length < 2) mappedOptions.push({ label: '', labelEn: '' });

             setOptions(mappedOptions);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [poll]); 

    // Translation updates
    useEffect(() => {
        if (translatedValues.title && translatedValues.title !== titleEn) setTitleEn(translatedValues.title);
        if (translatedValues.question && translatedValues.question !== questionEn) setQuestionEn(translatedValues.question);
        if (translatedValues.option) {
             const { idx, val } = translatedValues.option;
             updateOption(idx, 'labelEn', val);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [translatedValues, updateOption]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSubmit(e, {
            title, 
            titleEn, 
            question, 
            questionEn, 
            options, 
            daysDuration
        });
    };

    return (
        <div className="sync-modal-overlay">
            <div
                role="dialog"
                aria-modal="true"
                aria-labelledby="poll-form-modal-title"
                className="sync-modal-content poll-modal-content"
                style={{ maxWidth: '750px' }}
            >
                <div className="modal-accent-line"></div>

                <div className="poll-form-header">
                    <h3 id="poll-form-modal-title" style={{ margin: 0, display: 'flex', alignItems: 'center', gap: '12px', color: '#fff', fontSize: '1.5rem', fontWeight: '900' }}>
                        <BarChart3 style={{ color: 'var(--accent)' }} aria-hidden="true" />
                        {isEdit ? t('admin.polls.edit_title', 'Editar Encuesta') : t('admin.polls.create_title')}
                    </h3>
                    <button
                        aria-label={t('common.close', 'Cerrar modal')}
                        type="button"
                        onClick={onClose}
                        className="btn-close-mini"
                    >
                        <X aria-hidden="true" />
                    </button>
                </div>

                <div className="poll-form-body" style={{ overflowY: 'auto', maxHeight: '75vh' }}>
                    <form onSubmit={handleSubmit} className="poll-form-container">

                        <div className="poll-form-row">
                            <div className="form-group">
                                <label htmlFor="poll-title-es" className="admin-label-premium">{t('admin.polls.form_extras.title_es')}</label>
                                <input id="poll-title-es" className="admin-input-premium" value={title} onChange={e => setTitle(e.target.value)} placeholder={t('admin.polls.form.title_ph')} required />
                            </div>
                            <div className="form-group">
                                <div style={{display:'flex', justifyContent:'space-between', alignItems:'center'}}>
                                     <label htmlFor="poll-title-en" className="admin-label-premium">{t('admin.polls.form_extras.title_en')}</label>
                                     <button type="button" onClick={() => onTranslate(title, 'title')} className="btn-secondary" style={{fontSize:'0.7rem', padding:'0.2rem 0.6rem', marginBottom:'0.5rem'}} disabled={translatingField === 'title'}>
                                         {translatingField === 'title' ? <Loader2 className="spin"/> : <><Languages /> {t('admin.polls.form_extras.translate')}</>}
                                     </button>
                                </div>
                                <input id="poll-title-en" className="admin-input-premium" value={titleEn} onChange={e => setTitleEn(e.target.value)} placeholder="Poll Title" />
