                        </div>

                        <div className="poll-form-row">
                            <div className="form-group">
                                <label htmlFor="poll-question-es" className="admin-label-premium">{t('admin.polls.form_extras.question_es')}</label>
                                <textarea id="poll-question-es" className="admin-textarea-premium" value={question} onChange={e => setQuestion(e.target.value)} placeholder={t('admin.polls.form.question_ph')} required rows={3}></textarea>
                            </div>
                            <div className="form-group">
                                <div style={{display:'flex', justifyContent:'space-between', alignItems:'center'}}>
                                     <label htmlFor="poll-question-en" className="admin-label-premium">{t('admin.polls.form_extras.question_en')}</label>
                                     <button type="button" onClick={() => onTranslate(question, 'question')} className="btn-secondary" style={{fontSize:'0.7rem', padding:'0.2rem 0.6rem', marginBottom:'0.5rem'}} disabled={translatingField === 'question'}>
                                         {translatingField === 'question' ? <Loader2 className="spin"/> : <><Languages /> {t('admin.polls.form_extras.translate')}</>}
                                     </button>
                                </div>
                                <textarea id="poll-question-en" className="admin-textarea-premium" value={questionEn} onChange={e => setQuestionEn(e.target.value)} placeholder="Poll Question" rows={3}></textarea>
                            </div>
                        </div>

                        <div className="form-group">
                            <div className="admin-label-premium">{t('admin.polls.form.options')}</div>
                            <div className="poll-options-grid">
                                {options.map((opt, idx) => (
                                    // react-doctor-disable-next-line no-array-index-as-key -- editable option list: labels change per keystroke and may be empty/duplicated, so positional key is intended
                                    <div key={`item-${idx}`} className="poll-option-edit-card">
                                        <div className="poll-option-index" style={{ fontVariantNumeric: 'tabular-nums' }}>{idx + 1}</div>

                                        <div className="poll-option-inputs">
                                            <input
                                                aria-label={`${t('admin.polls.form_extras.option_es', 'Opción en español')} ${idx + 1}`}
                                                className="admin-input-premium" 
                                                value={opt.label} 
                                                onChange={e => updateOption(idx, 'label', e.target.value)} 
                                                placeholder={t('admin.polls.form_extras.option_es')}
                                                required
                                            />
                                            <div style={{display:'flex', gap:'10px'}}>
                                                 <input
                                                     aria-label={`${t('admin.polls.form_extras.option_en', 'Opción en inglés')} ${idx + 1}`}
                                                     className="admin-input-premium" 
                                                     value={opt.labelEn} 
                                                     onChange={e => updateOption(idx, 'labelEn', e.target.value)} 
                                                     placeholder={t('admin.polls.form_extras.option_en')}
                                                 />
                                                 <button
                                                     aria-label={`Traducir opción ${idx + 1}`}
                                                     type="button"
                                                     onClick={() => onTranslate(opt.label, 'options', idx)}
                                                     className="btn-secondary"
                                                     style={{padding:'0 1rem', borderRadius: '12px'}}
                                                     disabled={translatingField === `option-${idx}`}
                                                 >
                                                     {translatingField === `option-${idx}` ? <Loader2 className="spin"/> : <Languages size={18} />}
                                                 </button>
                                            </div>
                                        </div>

                                        {options.length > 2 && (
                                            <button 
                                                type="button" 
                                                aria-label={`${t('admin.polls.form_extras.delete_option', 'Eliminar opción')} ${idx + 1}`}
                                                onClick={() => removeOption(idx)} 
                                                className="poll-btn-action delete"
                                                style={{ height: '42px' }}
                                                title={t('admin.polls.form_extras.delete_option')}
                                            >
                                                <X />
                                            </button>
                                        )}
                                    </div>
                                ))}
                            </div>
                            <button type="button" onClick={() => setOptions([...options, {label: '', labelEn: ''}])} className="btn-secondary" style={{marginTop:'1.5rem', width:'100%', height: '50px', borderRadius: '16px', fontWeight: '800'}}>
                                <Plus style={{ marginRight: '10px' }} /> {t('admin.polls.form.add_option')}
                            </button>
                        </div>

                        <div className="poll-form-row">
                            <div className="form-group">
                                <label htmlFor="poll-duration" className="admin-label-premium">{t('admin.polls.form.duration')} ({t('admin.polls.form.days', 'días')})</label>
                                <input id="poll-duration" className="admin-input-premium" type="number" min="1" max="30" value={daysDuration} onChange={e => {
                                    const raw = e.target.value;
                                    if (!raw) { setDaysDuration(1); return; }
                                    const val = Number.parseInt(raw, 10);
                                    setDaysDuration(Number.isNaN(val) ? 1 : Math.max(1, Math.min(30, val)));
                                }} />
                            </div>
                            <div style={{ display: 'flex', alignItems: 'flex-end' }}>
                                 {hasActivePoll && !isEdit && (
                                    <div style={{ background: 'rgba(250, 204, 21, 0.1)', color: '#facc15', padding: '1rem', borderRadius: '14px', border: '1px solid rgba(250, 204, 21, 0.2)', fontSize: '0.85rem', fontWeight: '700', lineHeight: '1.4' }}>
                                        {t('admin.polls.form.warning_active')}
                                    </div>
                                 )}
                            </div>
                        </div>

                        <div className="poll-form-footer">
                            <button type="button" onClick={onClose} className="btn-secondary" style={{ height: '50px', padding: '0 2rem' }}>
                                {t('admin.polls.form_extras.cancel')}
                            </button>
                            <button type="submit" className="modal-btn-primary" style={{ height: '50px', padding: '0 2.5rem', background: buttonSuccess ? '#22c55e' : ''}} disabled={creating || buttonSuccess}>
                                {creating ? <Loader2 className="spin" /> : buttonSuccess ? (
                                    <><Check /> {t('admin.polls.form.success')}</>
                                ) : (
                                    <><Check /> {isEdit ? t('admin.polls.form.update', 'Actualizar') : t('admin.polls.form.submit')}</>
                                )}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    );
}

import { Trash2, Square, History } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import Loader from "../../UI/Loader";
import { Poll } from './types';

interface PollHistoryTableProps {
    polls: Poll[];
    loading: boolean;
    page: number;
    totalPages: number;
    onPageChange: (newPage: number) => void;
    onDelete: (id: number) => void;
    onClose: (id: number) => void;
}

export default function PollHistoryTable({ polls, loading, page, totalPages, onPageChange, onDelete, onClose }: PollHistoryTableProps) {
    const { t } = useTranslation();

    return (
        <div className="poll-history-container">
            <div className="poll-table-header">
                <History size={24} style={{ color: 'var(--accent)' }} />
                <h3>{t('admin.polls.history_title')}</h3>
            </div>

            {loading ? (
                <div style={{ padding: '4rem 0' }}>
                    <Loader 
                        text={t('admin.polls.loading_history')}
                        style={{ height: 'auto', minHeight: '150px' }} 
                    />
                </div>
            ) : (
                <div className="admin-table-container">
                    <table className="admin-table">
                        <thead>
                            <tr>
                                <th>{t('admin.polls.table.title')}</th>
                                <th>{t('admin.polls.table.date')}</th>
                                <th>{t('admin.polls.table.votes')}</th>
                                <th>{t('admin.polls.table.status')}</th>
                                <th style={{ textAlign: 'right' }}>{t('admin.polls.table.actions', 'Acciones')}</th>
                            </tr>
                        </thead>
                        <tbody>
                            {Array.isArray(polls) && polls.map(poll => (
                                <tr key={poll.id}>
                                    <td style={{ fontWeight: '800', color: '#fff', fontSize: '1.05rem' }}>{poll.title}</td>
                                    <td style={{ color: 'rgba(255,255,255,0.4)', fontWeight: '600' }}>
                                        {poll.created_at ? new Date(poll.created_at).toLocaleDateString() : '-'}
                                    </td>
                                    <td>
                                        <span style={{ fontWeight: '900', color: 'var(--accent)' }}>{poll.totalVotes}</span>
                                        <span style={{ fontSize: '0.8rem', color: 'rgba(255,255,255,0.3)', marginLeft: '6px', textTransform: 'uppercase' }}>{t('admin.polls.votes')}</span>
                                    </td>
                                    <td>
                                        <span className={`status-chip ${poll.is_active ? 'active' : 'inactive'}`} style={{
                                            background: poll.is_active ? 'rgba(34, 197, 94, 0.1)' : 'rgba(255, 255, 255, 0.05)',
                                            color: poll.is_active ? '#4ade80' : 'rgba(255,255,255,0.3)',
                                            border: `1px solid ${poll.is_active ? 'rgba(34, 197, 94, 0.2)' : 'rgba(255, 255, 255, 0.1)'}`,
                                        }}>
                                            {poll.is_active ? t('admin.polls.status_chip.active') : t('admin.polls.status_chip.closed')}
                                        </span>
                                    </td>
                                    <td style={{ textAlign: 'right' }}>
                                        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px' }}>
                                            {poll.is_active && (
                                                <button type="button" 
                                                    onClick={() => onClose(poll.id)}
                                                    aria-label={`${t('admin.polls.close_btn', 'Finalizar encuesta')} ${poll.title}`}
                                                    title={t('admin.polls.close_btn')}
                                                    className="poll-btn-action"
                                                >
                                                    <Square size={16} fill="currentColor" aria-hidden="true" />
                                                </button>
                                            )}
                                            <button type="button" 
                                                onClick={() => onDelete(poll.id)}
                                                aria-label={`${t('admin.polls.delete_tooltip', 'Eliminar encuesta')} ${poll.title}`}
                                                title={t('admin.polls.delete_tooltip')}
                                                className="poll-btn-action delete"
                                            >
                                                <Trash2 aria-hidden="true" />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                            {polls.length === 0 && (
                                <tr><td colSpan={5} style={{textAlign:'center', padding:'6rem', color: 'rgba(255,255,255,0.2)', fontWeight: '700'}}>{t('admin.polls.no_history')}</td></tr>
                            )}
                        </tbody>
                    </table>

                    {/* Pagination */}
                    {totalPages > 1 && (
                        <div role="navigation" aria-label={t('common.pagination', 'Paginación de encuestas')} style={{ display: 'flex', justifyContent: 'center', gap: '1rem', marginTop: '3rem', padding: '1rem', background: 'rgba(0,0,0,0.2)', borderRadius: '16px' }}>
                            <button
                                aria-label={t('common.previous', 'Página anterior')}
                                type="button"
                                onClick={() => onPageChange(Math.max(1, page - 1))}
                                disabled={page === 1}
                                className="poll-tab-btn"
                                style={{ padding: '0.5rem 1rem' }}
                            >
                                &lt;
                            </button>
                            <span style={{ display: 'flex', alignItems: 'center', color: 'rgba(255,255,255,0.4)', fontWeight: '800', fontVariantNumeric: 'tabular-nums' }}>
                                {t('admin.polls.pagination', { page, total: totalPages })}
                            </span>
                            <button
                                aria-label={t('common.next', 'Página siguiente')}
                                type="button"
                                onClick={() => onPageChange(Math.min(totalPages, page + 1))}
                                disabled={page === totalPages}
                                className="poll-tab-btn"
                                style={{ padding: '0.5rem 1rem' }}
                            >
                                &gt;
                            </button>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
}

import { useState } from 'react'
import { Waves, Ghost, TreePine, Check, Users, Save, ChevronDown, Settings, Megaphone, Image, Gavel, Shield } from 'lucide-react'
import { useAuth } from '../../context/AuthContext'
import ConfirmationModal from '../UI/ConfirmationModal'
import { useTranslation } from 'react-i18next'
import Loader from "../UI/Loader"

import {
    useSiteSettings,
    useUpdateSiteSetting,
    SiteSettings as HookSiteSettings
} from "../../hooks/useAdminData"

import BroadcastManager from './Config/BroadcastManager'
import HeroBannerManager, { HeroSlide } from './Config/HeroBannerManager'
import RulesEditor from './Config/RulesEditor'
import DonorsManager from './DonorsManager'
import PoliciesManager from './Config/PoliciesManager'

// Define the settings interface to cover all known keys
interface Rule {
    id: number;
    title: string;
    description: string;
}

// NOTE: interface extension (not Omit) — Omit collapses the hook's index
// signature `[key: string]: unknown` and loses all named properties.
interface SiteSettings extends HookSiteSettings {
    server_rules?: string | Rule[];
    hero_slides: string | HeroSlide[];
}

interface User {
    id: string;
    email?: string;
    user_metadata?: {
        full_name?: string;
    };
}

export default function SiteConfig() {
    const { t } = useTranslation()
    const { user } = useAuth() as { user: User | null }

    // TanStack Query Hooks
    const { data: fetchedSettings, isLoading: loading } = useSiteSettings();
    const updateSettingMutation = useUpdateSiteSetting();

    const [showMaintenanceModal, setShowMaintenanceModal] = useState(false)
    const [maintenanceTarget, setMaintenanceTarget] = useState(false)
    const [localSettings, setLocalSettings] = useState<Partial<SiteSettings>>({})

    const settings: SiteSettings = {
        theme: 'default',
        maintenance_mode: 'false',
        broadcast_config: '',
        hero_slides: '',
        recruitment_status: 'false',
        recruitment_link: '',
        ...(fetchedSettings || {}) as Partial<SiteSettings>,
        ...localSettings
    };

    const handleUpdate = async (key: string, value: string | boolean) => {
        const username = user?.user_metadata?.full_name || user?.email || 'Admin';

        updateSettingMutation.mutate({ 
            key, 
            value, 
            username, 
            userId: user?.id 
        }, {
            onSuccess: () => {
                // Clear local override on success
                setLocalSettings(prev => {
                    const next = { ...prev };
                    delete next[key];
                    return next;
                });

                // Dispatch event for App.jsx to react immediately
                if(key === 'theme') {
                    window.dispatchEvent(new CustomEvent('themeChanged', { detail: String(value) }));
                }
                if(key === 'broadcast_config') {
                    window.dispatchEvent(new CustomEvent('broadcastChanged', { detail: String(value) }));
                }
                if(key === 'maintenance_mode') {
                    window.dispatchEvent(new CustomEvent('maintenanceChanged', { detail: String(value) }));
                }
            },
            onError: () => {
                alert(t('admin.settings.error_save'))
            }
        });
    }

    if (loading) return (
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: '5rem', background: 'rgba(0,0,0,0.1)', borderRadius: '12px' }}>
            <Loader text="" style={{ height: 'auto', minHeight: '120px' }} />
        </div>
    )

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem', paddingBottom: '3rem' }}>

            {/* 1. SECCIÓN GENERAL (Tema, Mantenimiento, Reclutamiento) */}
            <ConfigSection title={t('admin.settings.sections.general')} icon={<Settings />} defaultOpen={true}>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '2rem' }}>
                    {/* TEMA + MANTENIMIENTO */}
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                        <div className="admin-card" style={{ 
                            background: 'rgba(10, 10, 15, 0.4)', 
                            backdropFilter: 'blur(20px)', 
                            border: '1px solid rgba(255, 255, 255, 0.05)', 
                            borderRadius: '24px',
                            padding: '1.5rem',
                            margin: 0
                        }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem', flexWrap: 'wrap', gap: '1rem' }}>
                                <div style={{ flex: '1 1 200px' }}>
                                    <h3 style={{ marginBottom: '0.4rem', display:'flex', alignItems:'center', gap:'0.75rem', fontSize: '1.1rem', fontWeight: '800' }}>
                                        <div style={{ padding: '6px', background: 'rgba(0, 188, 212, 0.1)', borderRadius: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                            <Waves style={{ color: '#00bcd4' }} /> 
                                        </div>
                                        {t('admin.settings.theme.title')}
                                    </h3>
                                    <p style={{ color: 'rgba(255,255,255,0.5)', margin: 0, fontSize: '0.85rem' }}>
                                        {t('admin.settings.theme.desc')}
                                    </p>
                                </div>
                            </div>

                            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(130px, 1fr))', gap: '0.8rem' }}>
                                <ThemeCard 
                                    active={settings.theme === 'default'} 
                                    onClick={() => handleUpdate('theme', 'default')}
                                    icon={<Waves size={24} color="#00bcd4" />}
                                    title={t('admin.settings.theme.default')}
                                    color="#00bcd4"
                                    loading={updateSettingMutation.isPending && updateSettingMutation.variables?.key === 'theme'}
                                />
                                <ThemeCard 
                                    active={settings.theme === 'halloween'} 
                                    onClick={() => handleUpdate('theme', 'halloween')}
                                    icon={<Ghost size={24} color="#ff7518" />}
                                    title={t('admin.settings.theme.halloween')}
                                    color="#ff7518"
                                    loading={updateSettingMutation.isPending && updateSettingMutation.variables?.key === 'theme'}
                                />
                                <ThemeCard 
                                    active={settings.theme === 'christmas'} 
                                    onClick={() => handleUpdate('theme', 'christmas')}
                                    icon={<TreePine size={24} color="#ef4444" />}
                                    title={t('admin.settings.theme.christmas')}
                                    color="#ef4444"
                                    loading={updateSettingMutation.isPending && updateSettingMutation.variables?.key === 'theme'}
                                />
                            </div>
                        </div>

                        {/* MANTENIMIENTO CARD SEPARADA */}
                        <div className="admin-card" style={{ 
                            background: settings.maintenance_mode === 'true' ? 'rgba(239, 68, 68, 0.05)' : 'rgba(10, 10, 15, 0.4)', 
                            backdropFilter: 'blur(20px)', 
                            border: settings.maintenance_mode === 'true' ? '1px solid rgba(239, 68, 68, 0.3)' : '1px solid rgba(255, 255, 255, 0.05)', 
                            borderRadius: '24px',
                            padding: '1.5rem',
                            margin: 0,
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'space-between',
                            flexWrap: 'wrap',
                            gap: '1rem'
                        }}>
                             <div style={{ flex: '1' }}>
                                <h3 style={{ marginBottom: '0.4rem', display:'flex', alignItems:'center', gap:'0.75rem', fontSize: '1rem', fontWeight: '800' }}>
                                    <div style={{ padding: '6px', background: settings.maintenance_mode === 'true' ? 'rgba(239, 68, 68, 0.2)' : 'rgba(255,255,255,0.05)', borderRadius: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                        <Settings style={{ color: settings.maintenance_mode === 'true' ? '#ef4444' : '#fff' }} /> 
                                    </div>
                                    {t('admin.settings.maintenance_label')}
                                </h3>
                                <p style={{ color: settings.maintenance_mode === 'true' ? '#fca5a5' : 'rgba(255,255,255,0.5)', margin: 0, fontSize: '0.8rem' }}>
                                    {settings.maintenance_mode === 'true' ? 'El sitio está inaccesible para usuarios normales.' : 'El sitio está activo y visible.'}
                                </p>
                            </div>

                            <label className="switch" style={{ margin: 0 }}>
                                <input 
                                    aria-label={t('admin.settings.maintenance.toggle', 'Alternar modo mantenimiento')} 
                                    type="checkbox" 
                                    checked={settings.maintenance_mode === 'true'} 
                                    onChange={() => {}} 
                                    onClick={(e) => {
                                        e.preventDefault();
                                        const nextState = !(settings.maintenance_mode === 'true');
                                        setMaintenanceTarget(nextState);
                                        setShowMaintenanceModal(true);
                                    }}
                                />
                                <span className="slider round"></span>
                            </label>
                        </div>
                    </div>

                    {/* RECLUTAMIENTO */}
                    <div className="admin-card" style={{ 
                        background: 'rgba(10, 10, 15, 0.4)', 
                        backdropFilter: 'blur(20px)', 
                        border: '1px solid rgba(255, 255, 255, 0.05)', 
                        borderRadius: '24px',
                        padding: '1.5rem',
                        margin: 0,
                        display: 'flex',
                        flexDirection: 'column',
                        justifyContent: 'center'
                    }}>
                        <h3 style={{ marginBottom: '1.5rem', display:'flex', alignItems:'center', gap:'0.75rem', fontSize: '1.1rem', fontWeight: '800' }}>
                            <div style={{ padding: '6px', background: 'rgba(76, 175, 80, 0.1)', borderRadius: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                <Users style={{ color: '#4CAF50' }} /> 
                            </div>
                            {t('admin.settings.recruitment.title')}
                        </h3>

                        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: settings.recruitment_status === 'true' ? 'rgba(76, 175, 80, 0.1)' : 'rgba(239, 68, 68, 0.05)', padding: '1.25rem', borderRadius: '16px', border: settings.recruitment_status === 'true' ? '1px solid rgba(76, 175, 80, 0.2)' : '1px solid rgba(239, 68, 68, 0.1)' }}>
                                <div>
                                    <span style={{ display: 'block', fontWeight: '800', fontSize: '1.1rem', color: settings.recruitment_status === 'true' ? '#4CAF50' : '#ef4444', marginBottom: '4px' }}>
                                        {settings.recruitment_status === 'true' ? t('admin.settings.recruitment.status_open') : t('admin.settings.recruitment.status_closed')}
                                    </span>
                                    <span style={{ fontSize: '0.8rem', color: 'rgba(255,255,255,0.5)', fontWeight: '600' }}>{t('admin.settings.recruitment.status_label')}</span>
                                </div>
                                <label className="switch">
                                    <input 
                                        aria-label={t('admin.settings.recruitment.toggle', 'Alternar estado de reclutamiento')} 
