            <div className="suggestion-content" style={{ flex: 1, padding: '0 1rem', borderLeft: '1px solid rgba(255,255,255,0.05)', borderRight: '1px solid rgba(255,255,255,0.05)' }}>
                <div style={{ 
                    color: '#e2e8f0', fontSize: '0.9rem', lineHeight: '1.5',
                    fontFamily: '"Inter", sans-serif',
                    maxHeight: isExpanded ? 'none' : '42px', // Approx 2 lines
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    display: '-webkit-box',
                    WebkitLineClamp: isExpanded ? undefined : 2,
                    WebkitBoxOrient: 'vertical',
                }}>
                    {s.message}
                </div>
                {s.message.length > 100 && (
                    <button
                        type="button"
                        onClick={onToggleExpand}
                        style={{
                            background: 'none', border: 'none', padding: 0,
                            color: 'var(--accent)', fontSize: '0.75rem', cursor: 'pointer', marginTop: '4px', 
                            fontWeight: '600', display: 'inline-flex', alignItems: 'center', gap: '4px'
                        }}
                    >
                        {isExpanded ? t('admin.suggestions.show_less', 'Ver menos') : t('admin.suggestions.read_more', 'Leer más')}
                    </button>
                )}
            </div>

            {/* 4. Status Badge */}
             <div className="suggestion-status" style={{ width: '100px', display: 'flex', justifyContent: 'center' }}>
                <span style={{ 
                    fontSize: '0.7rem', padding: '4px 8px', borderRadius: '4px', 
                    background: statusStyle.bg, color: statusStyle.text, border: `1px solid ${statusStyle.border}`,
                    fontWeight: 'bold', textTransform: 'uppercase'
                }}>
                    {t(`admin.suggestions.status.${s.status || 'pending'}`)}
                </span>
            </div>

            {/* 5. Actions */}
            <div className="suggestion-actions" style={{ 
                display: 'flex', alignItems: 'center', gap: '6px', minWidth: '160px', justifyContent: 'flex-end'
            }}>
                {(s.status !== 'approved' && s.status !== 'implemented') && (
                    <button
                        aria-label={`${t('admin.actions.approve', 'Aprobar')} sugerencia de ${s.nickname || 'usuario'}`}
                        type="button" 
                        className="btn-action-icon btn-approve" 
                        title={t('admin.actions.approve', 'Aprobar')}
                        onClick={() => onUpdateStatus(s.id, 'approved')}
                        style={{ width: '32px', height: '32px', padding: 0, borderRadius: '8px' }}
                    >
                        <Check size={14} aria-hidden="true" />
                    </button>
                )}
                {(s.status !== 'rejected') && (
                    <button
                        aria-label={`${t('admin.actions.reject', 'Rechazar')} sugerencia de ${s.nickname || 'usuario'}`}
                        type="button" 
                        className="btn-action-icon btn-reject" 
                        title={t('admin.actions.reject', 'Rechazar')}
                        onClick={() => onUpdateStatus(s.id, 'rejected')}
                        style={{ width: '32px', height: '32px', padding: 0, borderRadius: '8px' }}
                    >
                        <X size={14} aria-hidden="true" />
                    </button>
                )}

                <button
                    type="button"
                    aria-label={`Eliminar sugerencia de ${s.nickname || 'usuario'}`}
                    onClick={() => onDelete(s.id)} 
                    className="btn-ghost-delete"
                    title="Eliminar"
                    style={{ width: '32px', height: '32px' }}
                >
                    <Trash2 size={14} aria-hidden="true" />
                </button>
            </div>
        </div>
    );
}

import { useState } from "react"
import { createPortal } from "react-dom"
import { Ticket as TicketIcon, X, Send } from "lucide-react"

import { useTranslation } from 'react-i18next'
import { supabase } from "../../../services/supabaseClient"
import { getAuthHeaders } from "../../../services/adminAuth"
import Loader from "../../UI/Loader"
import { AlertData } from "./types"
import { CustomAlert } from "./Shared"


interface CreateTicketModalProps {
    onClose: () => void;
    onSuccess: () => void;
    user: { id: string } | null;
}

export default function CreateTicketModal({ onClose, onSuccess, user }: CreateTicketModalProps) {
    const { t } = useTranslation()
    const [newTicket, setNewTicket] = useState<{
        subject: string;
        description: string;
        priority: 'low' | 'medium' | 'high' | 'urgent';
    }>({ subject: '', description: '', priority: 'medium' })
    const [alert, setAlert] = useState<AlertData | null>(null)
    const [isSubmitting, setIsSubmitting] = useState(false)

    const API_URL = import.meta.env.VITE_API_URL

    const handleCreateTicket = async (e: React.FormEvent) => {
        e.preventDefault()
        if (!newTicket.subject) {
            setAlert({ message: t('admin.tickets.create_modal.error_subject', 'Falta el asunto'), type: 'error' })
            return
        }

        if (!user) return;

        try {
            setIsSubmitting(true)
            const { data: { session } } = await supabase.auth.getSession();
            const headers = { 
                'Content-Type': 'application/json',
                ...getAuthHeaders(session?.access_token || null)
            };

            const res = await fetch(`${API_URL}/tickets`, {
                method: 'POST',
                headers,
                body: JSON.stringify({
                    user_id: user.id,
                    subject: newTicket.subject,
                    description: newTicket.description,
                    priority: newTicket.priority
                })
            })

            if (!res.ok) throw new Error("Error creating ticket")

            onSuccess()
            onClose()
        } catch (error) {
            setAlert({ message: t('admin.tickets.create_modal.error_create', 'Error al crear') + ": " + (error instanceof Error ? error.message : String(error)), type: 'error' })
        } finally {
            setIsSubmitting(false)
        }
    }

    return createPortal(
        <div className="modal-overlay" style={{ backdropFilter: 'blur(10px)', background: 'rgba(0,0,0,0.7)' }}>
             <div
                role="dialog"
                aria-modal="true"
                aria-labelledby="create-ticket-modal-title"
                className="admin-card modal-content"
                style={{ 
                    width: '500px', 
                    maxWidth: '90%', 
                    border: '1px solid rgba(255,255,255,0.1)', 
                    boxShadow: '0 20px 50px rgba(0,0,0,0.5)',
                    background: '#111',
                    borderRadius: '24px',
                    padding: '0'
                }}
             >
                <div style={{ 
                    display: 'flex', 
                    justifyContent: 'space-between', 
                    marginBottom: '0', 
                    borderBottom: '1px solid rgba(255,255,255,0.05)', 
                    padding: '1.5rem', 
                    alignItems: 'center',
                    background: 'rgba(255,255,255,0.02)'
                }}>
                    <h3 id="create-ticket-modal-title" style={{ margin: 0, display: 'flex', alignItems: 'center', gap: '0.8rem', fontSize: '1.2rem', color: '#fff' }}>
                        <TicketIcon style={{ color: 'var(--accent)' }} aria-hidden="true" /> {t('admin.tickets.create_modal.title', 'Nuevo Ticket')}
                    </h3>
                    <button
                        aria-label={t('common.close', 'Cerrar modal')}
                        type="button" 
                        onClick={onClose} 
                        className="hover-rotate"
                        style={{ background: 'none', border: 'none', color: 'rgba(255,255,255,0.5)', cursor: 'pointer', fontSize: '1.2rem' }}
                    >
                        <X aria-hidden="true" />
                    </button>
                </div>

                <form onSubmit={handleCreateTicket} style={{ padding: '2rem' }}>
                    <div style={{marginBottom: '1.5rem'}}>
                        <label htmlFor="ticket-subject" style={{ display: 'block', marginBottom: '0.8rem', color: 'rgba(255,255,255,0.7)', fontSize: '0.9rem', fontWeight: '700' }}>{t('admin.tickets.create_modal.subject', 'Asunto')}</label>
                        <input id="ticket-subject" 
                            className="admin-input-premium" 
                            value={newTicket.subject} 
                            onChange={e => setNewTicket({ ...newTicket, subject: e.target.value })} 

                            placeholder={t('admin.tickets.subject_ph', 'Ej: Problema con rango')} 
                            style={{ width: '100%', padding: '1rem', fontSize: '1rem', borderRadius: '12px' }}
                        />
                    </div>

                    <div style={{marginBottom: '1.5rem'}}>
                        <label htmlFor="ticket-description" style={{ display: 'block', marginBottom: '0.8rem', color: 'rgba(255,255,255,0.7)', fontSize: '0.9rem', fontWeight: '700' }}>{t('admin.tickets.create_modal.description', 'Descripción')}</label>
                        <textarea id="ticket-description" 
                            className="admin-input-premium" 
                            rows={5} 
                            value={newTicket.description}  
                            onChange={e => setNewTicket({ ...newTicket, description: e.target.value })} 
                            placeholder={t('admin.tickets.create_modal.desc_placeholder', 'Detalla el problema...')}
                            style={{ width: '100%', padding: '1rem', fontSize: '0.95rem', borderRadius: '12px', resize: 'vertical' }}
                        />
                    </div>

                    <div style={{marginBottom: '2rem'}}>
                        <label htmlFor="ticket-priority" style={{ display: 'block', marginBottom: '0.8rem', color: 'rgba(255,255,255,0.7)', fontSize: '0.9rem', fontWeight: '700' }}>{t('admin.tickets.table.priority', 'Prioridad')}</label>
                        <div style={{ position: 'relative' }}>
                            <select id="ticket-priority" 
                                    className="admin-input-premium" 
                                    style={{ width: '100%', padding: '1rem', fontSize: '1rem', borderRadius: '12px', cursor: 'pointer', appearance: 'none' }}
                                    value={newTicket.priority} 
                                    onChange={e => setNewTicket({ ...newTicket, priority: e.target.value as 'low' | 'medium' | 'high' | 'urgent' })}
                                >
                                    <option value="low">🟢 {t('admin.tickets.priority.low', 'Baja')}</option>
                                    <option value="medium">🟡 {t('admin.tickets.priority.medium', 'Media')}</option>
                                    <option value="high">🟠 {t('admin.tickets.priority.high', 'Alta')}</option>
                                    <option value="urgent">🔴 {t('admin.tickets.priority.urgent', 'Urgente')}</option>
                                </select>
                        </div>
                    </div>

                    <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '1rem', paddingTop: '1rem' }}>
                        <button 
                            type="button" 
                            onClick={onClose} 
                            className="hover-lift"
                            style={{ 
                                padding: '1rem 2rem', 
                                background: 'transparent', 
                                border: '1px solid rgba(255,255,255,0.1)', 
                                color: '#ccc', 
                                borderRadius: '12px', 
                                cursor: 'pointer',
                                fontWeight: '600'
                            }}
                        >
                            {t('admin.tickets.create_modal.cancel', 'Cancelar')}
                        </button>
                        <button 
                            type="submit" 
                            className="modal-btn-primary hover-lift" 
                            disabled={isSubmitting}
                            style={{ padding: '1rem 3rem', borderRadius: '12px' }}
                        >
                            {isSubmitting ? <Loader minimal size={20} /> : <><Send /> {t('admin.tickets.create_modal.submit', 'Crear Ticket')}</>}
                        </button>
                    </div>
                </form>
            </div>
            {alert && <CustomAlert message={alert.message} type={alert.type} onClose={() => setAlert(null)} />}
        </div>,
        document.body
    )
}

