    )
}

import { useState, useRef, useEffect, useCallback } from "react"
import { createPortal } from "react-dom"
import { X, Loader2, Send, Lock } from "lucide-react"

import { useTranslation } from 'react-i18next'
import { supabase } from "../../../services/supabaseClient"
import { getAuthHeaders } from "../../../services/adminAuth"
import { Ticket, Message, AlertData, ConfirmData } from "./types"
import { PriorityBadge, StatusBadge, CustomAlert, CustomConfirm } from "./Shared"
import BanUserModal from "./BanUserModal"

interface TicketDetailModalProps {
    ticket: Ticket;
    onClose: () => void;
    refreshTickets: () => void;
    mockMessages?: Message[];
    user: { id: string } | null;
}

export default function TicketDetailModal({ ticket, onClose, refreshTickets, mockMessages, user }: TicketDetailModalProps) {
    const { t } = useTranslation()
    const [messages, setMessages] = useState<Message[]>([])
    const [newMessage, setNewMessage] = useState('')
    const [sending, setSending] = useState(false)
    const [showBanModal, setShowBanModal] = useState(false)
    const [alert, setAlert] = useState<AlertData | null>(null)
    const [confirmAction, setConfirmAction] = useState<ConfirmData | null>(null)
    const scrollRef = useRef<HTMLDivElement>(null)
    const scrollTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

    const API_URL = import.meta.env.VITE_API_URL

    // Scroll timer tracked so it can be cleared on unmount
    const scheduleScroll = useCallback(() => {
        if (scrollTimerRef.current) clearTimeout(scrollTimerRef.current)
        scrollTimerRef.current = setTimeout(() => {
            if (scrollRef.current) scrollRef.current.scrollIntoView({ behavior: 'smooth' })
        }, 100)
    }, [])

    const fetchMessages = useCallback(async () => {
        if (mockMessages) {
            setMessages(mockMessages)
            scheduleScroll()
            return
        }
        try {
            const { data: { session } } = await supabase.auth.getSession();
            const headers: HeadersInit = getAuthHeaders(session?.access_token || null);

            const res = await fetch(`${API_URL}/tickets/${ticket.id}/messages`, { headers })
            if (res.ok) {
                const data = await res.json()
                if (data.success && Array.isArray(data.data)) {
                    setMessages(data.data)
                } else if (Array.isArray(data)) {
                    setMessages(data)
                } else {
                    setMessages([])
                }
                scheduleScroll()
            }
        } catch (error) {
            console.error("Error fetching messages:", error)
        }
    }, [ticket.id, mockMessages, API_URL, scheduleScroll])

    const handleNewMessagePayload = useCallback((payload: { new: Message }) => {
        setMessages(prev => (prev.some(m => m.id === payload.new.id) ? prev : [...prev, payload.new as Message]));
        scheduleScroll();
    }, [scheduleScroll]);

    useEffect(() => {
        if (ticket) {
            fetchMessages()

            // Real-time Subscription
            const channel = supabase
                .channel(`ticket_chat_admin_${ticket.id}`)
                .on('postgres_changes', { 
                    event: 'INSERT', 
                    schema: 'public', 
                    table: 'ticket_messages',
                    filter: `ticket_id=eq.${ticket.id}`
                }, handleNewMessagePayload)
                .subscribe()

            return () => {
                if (scrollTimerRef.current) clearTimeout(scrollTimerRef.current);
                channel.unsubscribe();
                supabase.removeChannel(channel);
            }
        }
    }, [ticket, fetchMessages, handleNewMessagePayload])

    const sendingRef = useRef(false);

    const handleSendMessage = async (e: React.SyntheticEvent<HTMLFormElement>) => {
        e.preventDefault()
        if (!newMessage.trim() || !user || sendingRef.current) return

        sendingRef.current = true;
        setSending(true)
        try {
            const { data: { session } } = await supabase.auth.getSession();
            const headers = { 
                'Content-Type': 'application/json',
                ...getAuthHeaders(session?.access_token || null)
            };

            const res = await fetch(`${API_URL}/tickets/${ticket.id}/messages`, {
                method: 'POST',
                headers,
                body: JSON.stringify({
                    user_id: user.id,
                    message: newMessage,
                    is_staff: true
                })
            })
            if (res.ok) {
                setNewMessage('')
                fetchMessages()
            }
        } catch (error) {
            console.error("Error sending message:", error)
        } finally {
            sendingRef.current = false;
            setSending(false)
        }
    }

    const handleAction = async (action: string) => {
        if (action === 'ban') {
            setShowBanModal(true)
            return
        }

        if (action === 'delete') {
            setConfirmAction({
                message: t('admin.tickets.detail.delete_confirm', '¿Estás seguro de eliminar este ticket?'),
                onConfirm: () => handleAction('force_delete')
            })
            return
        }

        let method = 'PATCH'
        let body: Record<string, string> | undefined = {}
        let url = `${API_URL}/tickets/${ticket.id}/status`

        if (action === 'resolve') body = { status: 'resolved' }
        if (action === 'close') body = { status: 'closed' }
        if (action === 'open') body = { status: 'open' }
        if (action === 'delete' || action === 'force_delete') {
            method = 'DELETE'
            url = `${API_URL}/tickets/${ticket.id}`
            body = undefined
        }

        try {
            const { data: { session } } = await supabase.auth.getSession();
            const headers = { 
                'Content-Type': 'application/json',
                ...getAuthHeaders(session?.access_token || null)
            };

            const res = await fetch(url, {
                method: method,
                headers,
                body: body ? JSON.stringify(body) : undefined
            })

            if (res.ok) {
                refreshTickets()
                onClose()
            } else {
                setAlert({ message: t('admin.alerts.error_title', 'Error'), type: 'error' })
            }
        } catch (error) {
            setAlert({ message: t('admin.alerts.error_title', 'Error') + ": " + (error instanceof Error ? error.message : String(error)), type: 'error' })
        }
    }

    return createPortal(
        <div className="modal-overlay">
            {showBanModal && (
                <BanUserModal 
                    ticket={ticket} 
                    onClose={() => setShowBanModal(false)}
                    onSuccess={() => { 
                        setShowBanModal(false)
                        refreshTickets()
                        setAlert({ message: t('admin.tickets.ban_modal.success', 'Usuario baneado correctamente'), type: 'success' }) 
                    }}
                />
            )}

            {!showBanModal && (
                <div role="dialog" aria-modal="true" aria-labelledby="ticket-modal-title" className="modal-content" style={{ maxHeight: '85vh', height: '85vh' }}>

                    {/* Header Modal */}
                    <div style={{ padding: '1.5rem', borderBottom: '1px solid #333', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', background: '#222', borderTopLeftRadius: 'var(--radius)', borderTopRightRadius: 'var(--radius)' }}>
                        <div>
                            <h2 id="ticket-modal-title" style={{ margin: 0, fontSize: '1.4rem', color: '#fff' }}>{ticket.subject}</h2>
                            <div style={{ display: 'flex', gap: '0.8rem', marginTop: '0.5rem', alignItems: 'center' }}>
                                <span style={{color: '#888', fontFamily:'monospace'}}>#{ticket.id}</span>
                                <PriorityBadge priority={ticket.priority} />
                                <StatusBadge status={ticket.status} />
                            </div>
                        </div>
                        <button
                            aria-label={t('common.close', 'Cerrar ticket')}
                            type="button"
                            onClick={onClose}
                            style={{ background: 'transparent', border: 'none', color: '#aaa', cursor: 'pointer', padding: '0.5rem' }}
                        >
                            <X size={22} aria-hidden="true" />
                        </button>
                    </div>

                    {/* Chat Body (Scrollable) */}
                    <div style={{ flex: 1, overflowY: 'auto', padding: '1.5rem', display: 'flex', flexDirection: 'column', gap: '1rem', background: '#181818' }}>

                        {/* Mensaje original del usuario (Descripción) */}
                        <div className="msg-bubble user">
                            <div className="msg-header">{t('admin.tickets.detail.original_desc', 'Descripción Original')}</div>
                            <div style={{whiteSpace: 'pre-wrap'}}>{ticket.description || t('admin.tickets.detail.no_desc', 'Sin descripción')}</div>
                        </div>

                        <div style={{height: '1px', background: '#333', margin: '1rem 0'}}></div>

                        {messages.length === 0 && (
                            <div style={{textAlign: 'center', color: '#555', padding: '2rem'}}>{t('admin.tickets.detail.no_history', 'No hay historial de chat')}</div>
                        )}

                        {messages.map((msg) => (
                            <div key={msg.id} className={`msg-bubble ${msg.is_staff ? 'staff' : 'user'}`}>
                                <div className="msg-header">{msg.is_staff ? t('admin.tickets.staff_label', 'STAFF') : t('admin.tickets.table.user', 'USUARIO').toUpperCase()} • {new Date(msg.created_at).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</div>
                                <div>{msg.message}</div>
                            </div>
                        ))}

                        {/* Referencia invisible para el scroll */}
                        <div ref={scrollRef}></div>
                    </div>

                    {/* Footer Actions & Reply */}
                    <div style={{ padding: '1.5rem', borderTop: '1px solid #333', background: '#222', borderBottomLeftRadius: 'var(--radius)', borderBottomRightRadius: 'var(--radius)' }}>

                        {ticket.status !== 'closed' ? (
                            <form onSubmit={handleSendMessage} style={{ display: 'flex', gap: '1rem', marginBottom: '1.5rem' }}>
                                <input
                                    aria-label={t('admin.tickets.detail.reply_placeholder', 'Escribe una respuesta...')}
                                    className="admin-input" 
                                    value={newMessage} 
                                    onChange={e => setNewMessage(e.target.value)} 
                                    placeholder={t('admin.tickets.detail.reply_placeholder', 'Escribe una respuesta...')}
                                    style={{flex: 1, marginBottom: 0}}
                                />
                                <button
                                    aria-label={t('admin.tickets.detail.send_reply', 'Enviar respuesta')}
                                    aria-busy={sending}
                                    type="submit"
                                    className="btn-primary"
                                    disabled={sending}
                                    style={{padding: '0 1.5rem'}}
                                >
                                    {sending ? <Loader2 className="animate-spin" aria-hidden="true" /> : <Send aria-hidden="true" />}
                                </button>
                            </form>
                        ) : (
                            <div style={{padding: '1rem', background: '#2a1a1a', color: '#888', textAlign: 'center', borderRadius: '8px', marginBottom: '1.5rem', border: '1px solid #442222'}}>
                                <Lock style={{marginRight: '0.5rem', width: '0.8rem'}}/> {t('admin.tickets.detail.closed_msg', 'Este ticket ha sido cerrado y no se pueden enviar más mensajes.')}
                            </div>
                        )}

                        <div style={{ display: 'flex', gap: '0.8rem', justifyContent: 'flex-end', flexWrap: 'wrap' }}>
                            <button type="button" onClick={() => handleAction('ban')} className="btn-action ban">{t('admin.tickets.actions.ban', 'Banear')}</button>
                            {ticket.status !== 'resolved' && ticket.status !== 'closed' && <button type="button" onClick={() => handleAction('resolve')} className="btn-action resolve">{t('admin.tickets.actions.resolve', 'Resolver')}</button>}
                            {ticket.status !== 'closed' ? 
                                <button type="button" onClick={() => handleAction('close')} className="btn-action close">{t('admin.tickets.actions.close', 'Cerrar')}</button> :
                                <button type="button" onClick={() => handleAction('open')} className="btn-action" style={{background:'#555'}}>{t('admin.tickets.actions.reopen', 'Reabrir')}</button>
                            }
                            <button type="button" onClick={() => handleAction('delete')} className="btn-action delete" style={{marginLeft: 'auto'}}>{t('admin.tickets.actions.delete', 'Eliminar')}</button>
                        </div>
                    </div>
                </div>
            )}
            {alert && <CustomAlert message={alert.message} type={alert.type} onClose={() => setAlert(null)} />}
            {confirmAction && (
                <CustomConfirm 
                    message={confirmAction.message} 
                    onConfirm={() => { setConfirmAction(null); confirmAction.onConfirm(); }} 
                    onCancel={() => setConfirmAction(null)} 
                />
            )}
        </div>,
        document.body
    )
}

import { useMemo } from "react"
import { Users, Eye, Ticket as TicketIcon } from "lucide-react"
import { useTranslation } from 'react-i18next'
import { Ticket } from "./types"
import { PriorityBadge, StatusBadge } from "./Shared"
import Loader from "../../UI/Loader"

interface TicketTableProps {
    tickets: Ticket[];
    loading: boolean;
    selectedTicketIds: number[];
    toggleSelectAll: () => void;
    toggleSelectTicket: (id: number) => void;
    onViewTicket: (ticket: Ticket) => void;
}

export default function TicketTable({ 
    tickets, 
    loading, 
    selectedTicketIds, 
    toggleSelectAll, 
    toggleSelectTicket, 
    onViewTicket 
}: Readonly<TicketTableProps>) {
    const { t } = useTranslation()
    const selectedSet = useMemo(() => new Set(selectedTicketIds), [selectedTicketIds]);

    if (loading) {
       return (
           <div style={{ padding: '4rem', display: 'flex', justifyContent: 'center' }}>
               <Loader text={t('admin.tickets.searching', 'Buscando tickets...')} minimal size={40} />
           </div>
       )
    }

    if (tickets.length === 0) {
        return (
            <div style={{ padding: '4rem', textAlign: 'center', color: 'rgba(255,255,255,0.3)' }}>
                <TicketIcon size={48} style={{ marginBottom: '1rem', opacity: 0.5 }} />
                <p style={{ fontSize: '1.1rem' }}>{t('admin.tickets.empty', 'No se encontraron tickets')}</p>
            </div>
        )
    }

    return (
        <div style={{ overflowX: 'auto' }}>
            <table className="admin-table" style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                    <tr style={{ borderBottom: '1px solid rgba(255,255,255,0.05)', background: 'rgba(255,255,255,0.02)' }}>
                        <th style={{width: '50px', padding: '1.5rem 1rem', textAlign: 'center'}}>
                            <input 
                                aria-label={t('admin.tickets.select_all', 'Seleccionar todos los tickets')} 
                                type="checkbox" 
                                checked={tickets.length > 0 && selectedTicketIds.length === tickets.length}
                                onChange={toggleSelectAll}
                                style={{cursor:'pointer', accentColor: 'var(--accent)'}}
                            />
                        </th>
                        <th style={{padding: '1.5rem 1rem', textAlign: 'left', color: 'rgba(255,255,255,0.5)', fontSize: '0.8rem', textTransform: 'uppercase', letterSpacing: '1px'}}>{t('admin.tickets.table.id', 'ID')}</th>
                        <th style={{padding: '1.5rem 1rem', textAlign: 'left', color: 'rgba(255,255,255,0.5)', fontSize: '0.8rem', textTransform: 'uppercase', letterSpacing: '1px'}}>{t('admin.tickets.table.user', 'Usuario')}</th>
                        <th style={{padding: '1.5rem 1rem', textAlign: 'left', color: 'rgba(255,255,255,0.5)', fontSize: '0.8rem', textTransform: 'uppercase', letterSpacing: '1px'}}>{t('admin.tickets.table.subject', 'Asunto')}</th>
                        <th style={{padding: '1.5rem 1rem', textAlign: 'left', color: 'rgba(255,255,255,0.5)', fontSize: '0.8rem', textTransform: 'uppercase', letterSpacing: '1px', width: '120px'}}>{t('admin.tickets.table.priority', 'Prioridad')}</th>
                        <th style={{padding: '1.5rem 1rem', textAlign: 'left', color: 'rgba(255,255,255,0.5)', fontSize: '0.8rem', textTransform: 'uppercase', letterSpacing: '1px', width: '120px'}}>{t('admin.tickets.table.status', 'Estado')}</th>
                        <th style={{padding: '1.5rem 1rem', textAlign: 'left', color: 'rgba(255,255,255,0.5)', fontSize: '0.8rem', textTransform: 'uppercase', letterSpacing: '1px', width: '150px'}}>{t('admin.tickets.table.date', 'Fecha')}</th>
                        <th style={{padding: '1.5rem 1rem', textAlign: 'right', color: 'rgba(255,255,255,0.5)', fontSize: '0.8rem', textTransform: 'uppercase', letterSpacing: '1px', width: '80px'}}>{t('admin.tickets.table.action', 'Acción')}</th>
                    </tr>
                </thead>
                <tbody>
                    {tickets.map(ticketItem => (
                        <tr 
                            key={ticketItem.id} 
                            onClick={() => onViewTicket(ticketItem)} 
                            className="hover-bg-glass"
                            style={{ 
                                cursor: 'pointer', 
                                borderBottom: '1px solid rgba(255,255,255,0.03)',
                                background: selectedSet.has(ticketItem.id) ? 'rgba(var(--accent-rgb), 0.05)' : 'transparent',
                                transition: 'background 0.2s'
                            }}
                        >
                            <td onClick={e => e.stopPropagation()} style={{textAlign: 'center', padding: '1rem'}}>
                                <input 
                                    aria-label={t('admin.tickets.select_ticket', `Seleccionar ticket #${ticketItem.id}`)} 
                                    type="checkbox" 
                                    checked={selectedSet.has(ticketItem.id)}
                                    onChange={() => toggleSelectTicket(ticketItem.id)}
                                    style={{cursor:'pointer', accentColor: 'var(--accent)'}}
                                />
                            </td>
                            <td style={{ fontFamily: 'monospace', color: 'var(--accent)', fontWeight: 'bold', padding: '1rem' }}>#{ticketItem.id}</td>
                            <td style={{ color: '#ccc', fontSize: '0.95rem', padding: '1rem' }}>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '0.8rem' }}>
                                    {ticketItem.profiles?.avatar_url ? (
                                        <img src={ticketItem.profiles.avatar_url} alt="" style={{ width: '32px', height: '32px', borderRadius: '50%', objectFit: 'cover', border: '1px solid rgba(255,255,255,0.1)' }} />
                                    ) : (
