import React, { useState, useEffect } from 'react';
import { Loader2, Film } from 'lucide-react';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { WikiArticle } from '../../../../services/wikiService';
import WikiBoss3DCard from '../../../Wiki/WikiBoss3DCard';

interface BossSkillsTabProps {
  formData: Partial<WikiArticle>;
  setFormData: React.Dispatch<React.SetStateAction<Partial<WikiArticle>>>;
}

export function BossSkillsTab({ formData, setFormData }: Readonly<BossSkillsTabProps>) {
  const phases =
    formData.boss_phases && formData.boss_phases.length > 0
      ? formData.boss_phases
      : [
          {
            phase_number: 1,
            phase_name: 'Fase I',
            model_3d_url: formData.model_3d_url || '/models/toro_wither.gltf',
            hp: formData.boss_hp || '600 HP',
            damage: formData.boss_damage || '35 Daño',
            attacks: formData.boss_phase_1_attacks || [],
          },
          {
            phase_number: 2,
            phase_name: 'Fase II',
            model_3d_url: formData.model_3d_url_phase_2 || '/models/toro_wither_terror.gltf',
            hp: formData.boss_hp_phase_2 || '800 HP',
            damage: formData.boss_damage_phase_2 || '50 Daño Crítico',
            attacks: formData.boss_phase_2_attacks || [],
          },
        ];

  const [selectedPhaseIdx, setSelectedPhaseIdx] = useState<number>(0);
  const [previewClip, setPreviewClip] = useState<string | null>(null);

  const activePhase = phases[selectedPhaseIdx] || phases[0];

  const [clipsMap, setClipsMap] = useState<Record<string, string[]>>({});
  const [loadingClips, setLoadingClips] = useState<boolean>(false);

  const activeModelUrl = activePhase?.model_3d_url || formData.model_3d_url || '';

  // Inspect GLTF model clips dynamically
  useEffect(() => {
    if (!activeModelUrl || clipsMap[activeModelUrl]) return;

    setLoadingClips(true);
    const loader = new GLTFLoader();
    loader.load(
      activeModelUrl,
      (gltf) => {
        const foundClips = (gltf.animations || []).map((c) => c.name);
        setClipsMap((prev) => ({ ...prev, [activeModelUrl]: foundClips }));
        setLoadingClips(false);
      },
      undefined,
      () => {
        setLoadingClips(false);
      },
    );
  }, [activeModelUrl, clipsMap]);

  const detectedClips = clipsMap[activeModelUrl] || [];

  const updatePhaseField = (phaseIdx: number, field: string, value: unknown) => {
    const updated = [...phases];
    updated[phaseIdx] = { ...updated[phaseIdx], [field]: value };
    setFormData({ ...formData, boss_phases: updated });
  };

  const addPhase = () => {
    const nextNum = phases.length + 1;
    const newPhase = {
      phase_number: nextNum,
      phase_name: `Fase ${nextNum}`,
      model_3d_url: '',
      hp: '500 HP',
      damage: '30 Daño',
      attacks: [
        {
          name: 'Ataque Primario',
          type: 'Melee',
          damage: '25 Daño',
          description: 'Descripción de la habilidad',
          animation_clip: 'attack',
        },
      ],
    };
    const updated = [...phases, newPhase];
    setFormData({ ...formData, boss_phases: updated });
    setSelectedPhaseIdx(updated.length - 1);
  };

  const removePhase = (phaseIdx: number) => {
    if (phases.length <= 1) return;
    const updated = phases
      .filter((_, i) => i !== phaseIdx)
      .map((p, i) => ({ ...p, phase_number: i + 1 }));
    setFormData({ ...formData, boss_phases: updated });
    setSelectedPhaseIdx(Math.max(0, phaseIdx - 1));
  };

  const addAttack = (phaseIdx: number, initialClip: string = '') => {
    const updated = [...phases];
    const currentAttacks = updated[phaseIdx].attacks || [];
    const newAttack = {
      name: 'Nueva Habilidad',
      type: 'Proyectil',
      damage: '25 Daño',
      description: 'Descripción de la habilidad.',
      animation_clip: initialClip || 'attack',
    };
    updated[phaseIdx] = {
      ...updated[phaseIdx],
      attacks: [...currentAttacks, newAttack],
    };
    setFormData({ ...formData, boss_phases: updated });
  };

  const updateAttack = (
    phaseIdx: number,
    attackIdx: number,
    field: string,
    value: string | string[],
  ) => {
    const updated = [...phases];
    const currentAttacks = [...(updated[phaseIdx].attacks || [])];
    currentAttacks[attackIdx] = {
      ...currentAttacks[attackIdx],
      [field]: value,
    };
    updated[phaseIdx] = { ...updated[phaseIdx], attacks: currentAttacks };
    setFormData({ ...formData, boss_phases: updated });

    if (field === 'animation_clip' && typeof value === 'string') {
      setPreviewClip(value);
    }
  };

  const removeAttack = (phaseIdx: number, attackIdx: number) => {
    const updated = [...phases];
    const currentAttacks = (updated[phaseIdx].attacks || []).filter((_, i) => i !== attackIdx);
    updated[phaseIdx] = { ...updated[phaseIdx], attacks: currentAttacks };
    setFormData({ ...formData, boss_phases: updated });
  };

  // Prepare preview 3D card phase & attacks
  const activeAttacks = activePhase?.attacks || [];
  const previewModelUrl =
    activePhase?.model_3d_url ||
    (selectedPhaseIdx === 1
      ? formData.model_3d_url_phase_2 || formData.model_3d_url
      : formData.model_3d_url);

  return (
    <div style={{ width: '100%', overflow: 'hidden' }}>
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'minmax(0, 1.4fr) minmax(0, 1fr)',
          gap: '1.2rem',
          alignItems: 'start',
        }}
      >
        <div style={{ width: '100%', minWidth: 0, overflow: 'hidden' }}>
          <div
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              marginBottom: '0.8rem',
              borderBottom: '1px solid rgba(255,255,255,0.1)',
              paddingBottom: '0.6rem',
            }}
          >
            <div style={{ display: 'flex', gap: '0.4rem', flexWrap: 'wrap' }}>
              {phases.map((phase, pIdx) => (
                <button
                  key={`phase-selector-${phase.phase_number}-${pIdx}`}
                  type="button"
                  onClick={() => {
                    setSelectedPhaseIdx(pIdx);
                    setPreviewClip(null);
                  }}
                  style={{
                    padding: '0.35rem 0.7rem',
                    borderRadius: '6px',
                    fontSize: '0.75rem',
                    fontWeight: 'bold',
                    border: '1px solid',
                    borderColor: selectedPhaseIdx === pIdx ? '#ef4444' : 'rgba(255,255,255,0.1)',
                    background:
                      selectedPhaseIdx === pIdx ? 'rgba(239, 68, 68, 0.25)' : 'rgba(0,0,0,0.3)',
                    color: selectedPhaseIdx === pIdx ? '#fca5a5' : '#888',
                    cursor: 'pointer',
                  }}
                >
                  🔥 {phase.phase_name || `Fase ${phase.phase_number}`} (
                  {(phase.attacks || []).length})
                </button>
              ))}
            </div>

            <button
              type="button"
              onClick={addPhase}
              style={{
                background: 'rgba(34, 197, 94, 0.2)',
                border: '1px solid rgba(34, 197, 94, 0.4)',
                color: '#86efac',
                padding: '0.35rem 0.7rem',
                borderRadius: '6px',
                fontSize: '0.75rem',
                fontWeight: 'bold',
                cursor: 'pointer',
              }}
            >
              + Añadir Fase
            </button>
          </div>

          {activePhase && (
            <div
              style={{
                background: 'rgba(0,0,0,0.3)',
                border: '1px solid rgba(255,255,255,0.08)',
                padding: '0.9rem',
                borderRadius: '8px',
                marginBottom: '1rem',
                width: '100%',
                boxSizing: 'border-box',
              }}
            >
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  marginBottom: '0.8rem',
                }}
              >
                <span
                  style={{
                    fontSize: '0.8rem',
                    fontWeight: 'bold',
                    color: '#fca5a5',
                    textTransform: 'uppercase',
                  }}
                >
                  Configuración de {activePhase.phase_name || `Fase ${activePhase.phase_number}`}
                </span>
                {phases.length > 1 && (
                  <button
                    type="button"
                    onClick={() => removePhase(selectedPhaseIdx)}
                    style={{
                      background: 'rgba(239, 68, 68, 0.2)',
                      border: '1px solid rgba(239, 68, 68, 0.4)',
                      color: '#fca5a5',
                      padding: '0.25rem 0.5rem',
                      borderRadius: '4px',
                      fontSize: '0.7rem',
                      cursor: 'pointer',
                    }}
                  >
                    🗑️ Eliminar Fase {activePhase.phase_number}
                  </button>
                )}
              </div>

              <div
                style={{
                  display: 'grid',
                  gridTemplateColumns: '1fr 1fr',
                  gap: '0.6rem',
                  marginBottom: '0.8rem',
                }}
              >
                <div>
                  <span
