// Internal component to handle form state and logic
function WikiArticleForm({
  initialData,
  onSave,
  onClose,
  isEditing,
  saving,
  t,
}: Readonly<{
  initialData: Partial<WikiArticle> | null;
  onSave: (article: Partial<WikiArticle>) => Promise<void>;
  onClose: () => void;
  isEditing: boolean;
  saving: boolean;
  t: TFunction;
}>) {
  const [viewMode, setViewMode] = useState<'editor' | 'preview'>('editor');
  const [formData, setFormData] = useState<Partial<WikiArticle>>(
    initialData || {
      title: '',
      slug: '',
      content: '',
      category: 'General',
    },
  );

  const handleSubmit = async (e: React.SyntheticEvent) => {
    e.preventDefault();
    await onSave(formData);
  };

  return (
    <form onSubmit={handleSubmit}>
      {/* Mode Switcher Tabs */}
      <div
        style={{
          display: 'flex',
          gap: '0.5rem',
          marginBottom: '1.5rem',
          borderBottom: '1px solid rgba(255, 255, 255, 0.1)',
          paddingBottom: '0.8rem',
        }}
      >
        <button
          type="button"
          onClick={() => setViewMode('editor')}
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: '0.4rem',
            padding: '0.5rem 1rem',
            borderRadius: '8px',
            background: viewMode === 'editor' ? 'rgba(255, 255, 255, 0.15)' : 'transparent',
            border:
              '1px solid ' + (viewMode === 'editor' ? 'rgba(255, 255, 255, 0.3)' : 'transparent'),
            color: viewMode === 'editor' ? '#fff' : '#888',
            cursor: 'pointer',
            fontSize: '0.85rem',
            fontWeight: 'bold',
          }}
        >
          <Edit3 size={15} /> Editor
        </button>
        <button
          type="button"
          onClick={() => setViewMode('preview')}
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: '0.4rem',
            padding: '0.5rem 1rem',
            borderRadius: '8px',
            background: viewMode === 'preview' ? 'rgba(239, 68, 68, 0.2)' : 'transparent',
            border:
              '1px solid ' + (viewMode === 'preview' ? 'rgba(239, 68, 68, 0.5)' : 'transparent'),
            color: viewMode === 'preview' ? '#fca5a5' : '#888',
            cursor: 'pointer',
            fontSize: '0.85rem',
            fontWeight: 'bold',
          }}
        >
          <Eye size={15} /> Vista Previa en Vivo
        </button>
      </div>

      {viewMode === 'preview' ? (
        <WikiArticlePreview formData={formData} />
      ) : (
        <WikiArticleEditorFields formData={formData} setFormData={setFormData} t={t} />
      )}

      <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '1rem', marginTop: '2rem' }}>
        <button
          type="button"
          onClick={onClose}
          style={{
            padding: '0.8rem 2rem',
            color: '#666',
            background: 'transparent',
            border: 'none',
            cursor: 'pointer',
          }}
        >
          {t('admin.wiki.cancel')}
        </button>
        <button
          type="submit"
          disabled={saving}
          className="btn-primary"
          style={{
            padding: '0.8rem 3rem',
            minWidth: '180px',
            display: 'flex',
            justifyContent: 'center',
          }}
        >
          {saving ? (
            <Loader2 className="animate-spin" size={20} />
          ) : (
            <>
              {isEditing ? (
                <>
                  <Save style={{ marginRight: '8px' }} /> {t('admin.wiki.update_btn')}
                </>
              ) : (
                <>
                  <Save style={{ marginRight: '8px' }} /> {t('admin.wiki.publish_btn')}
                </>
              )}
            </>
          )}
        </button>
      </div>
    </form>
  );
}

