        {pendingImageRepl && (
          <div style={{ padding: '0 1rem 1rem 1rem' }}>
            <div
              style={{
                background: 'rgba(255,255,255,0.05)',
                borderRadius: '4px',
                display: 'inline-flex',
                alignItems: 'center',
                gap: '1rem',
                border: '1px solid var(--accent)',
                padding: '0.5rem',
              }}
            >
              <img
                src={pendingImageRepl.preview}
                style={{
                  height: '50px',
                  borderRadius: '4px',
                  objectFit: 'cover',
                }}
                alt="preview"
              />
              <div style={{ fontSize: '0.8rem', color: '#ccc' }}>
                <div style={{ fontWeight: 'bold', color: '#fff' }}>Imagen lista</div>
              </div>
              <button
                aria-label={t('common.remove', 'Eliminar imagen')}
                type="button"
                onClick={clearReplImage}
                style={{
                  background: 'transparent',
                  border: 'none',
                  color: '#ef4444',
                  cursor: 'pointer',
                  padding: '0 0.5rem',
                  fontSize: '1.1rem',
                }}
              >
                <X />
              </button>
            </div>
          </div>
        )}

        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            padding: '0.5rem 1rem',
            background: 'rgba(255,255,255,0.02)',
            borderTop: '1px solid rgba(255,255,255,0.05)',
          }}
        >
          <label
            title="Adjuntar imagen"
            className="hover:bg-white/10 hover:text-white"
            style={{
              cursor: 'pointer',
              color: pendingImageRepl ? 'var(--accent)' : '#aaa',
              fontSize: '1.2rem',
              padding: '0.5rem',
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              transition: 'color 0.2s, background-color 0.2s, border-color 0.2s, opacity 0.2s',
            }}
          >
            <ImageIcon />
            <input
              aria-label={t('create_thread.form.attach_image', 'Adjuntar imagen')}
              type="file"
              accept="image/*"
              onChange={handleReplImageSelect}
              style={{ display: 'none' }}
            />
          </label>

          <button
            type="submit"
            disabled={isSubmitDisabled}
            style={{
              background: isSubmitDisabled ? '#444' : 'var(--accent)',
              color: isSubmitDisabled ? '#888' : '#000',
              border: 'none',
              padding: '0.4rem 1.2rem',
              borderRadius: '4px',
              fontWeight: 'bold',
              fontSize: '0.9rem',
              cursor: isSubmitDisabled ? 'not-allowed' : 'pointer',
              display: 'flex',
              alignItems: 'center',
              gap: '0.5rem',
              transition: 'transform 0.1s',
            }}
          >
            <Send size={12} /> {t('forum_thread.publish')}
          </button>
        </div>
      </div>
    </form>
  );
}

import { Pin, Lock, Unlock, Edit, Trash2, Check, X } from 'lucide-react';

interface ForumThreadActionButtonsProps {
  readonly isTopic: boolean;
  readonly isOwnerOrAdmin: boolean;
  readonly isEditingThread: boolean;
  readonly isAdmin: boolean;
  readonly pinned: boolean;
  readonly locked: boolean;
  readonly onTogglePin: () => void;
  readonly onToggleLock: () => void;
  readonly onStartEditThread: () => void;
  readonly onDeleteThread: () => void;
  readonly onUpdateThread: () => void;
  readonly onCancelEditThread: () => void;
}

export default function ForumThreadActionButtons({
  isTopic,
  isOwnerOrAdmin,
  isEditingThread,
  isAdmin,
  pinned,
  locked,
  onTogglePin,
  onToggleLock,
  onStartEditThread,
  onDeleteThread,
  onUpdateThread,
  onCancelEditThread,
}: Readonly<ForumThreadActionButtonsProps>) {
  if (isEditingThread) {
    return (
      <div className="flex items-center gap-3">
        <button
          type="button"
          onClick={onUpdateThread}
          className="btn-primary"
          style={{
            padding: '0.5rem 1rem',
            display: 'flex',
            gap: '0.5rem',
            fontSize: '0.8rem',
          }}
        >
          <Check size={16} /> Guardar
        </button>
        <button
          type="button"
          onClick={onCancelEditThread}
          className="btn-secondary"
          style={{
            padding: '0.5rem 1rem',
            display: 'flex',
            gap: '0.5rem',
            fontSize: '0.8rem',
          }}
        >
          <X size={16} /> Cancelar
        </button>
      </div>
    );
  }

  if (!isTopic || !isOwnerOrAdmin) return null;

  return (
    <div className="flex items-center gap-3">
      {/* Mod Tools - Only for Staff */}
      {isAdmin && (
        <div className="flex items-center gap-2 rounded-lg border border-white/5 bg-black/20 p-1.5">
          <button
            type="button"
            onClick={onTogglePin}
            className="rounded p-1 transition-colors hover:bg-white/5"
            title={pinned ? 'Desfijar' : 'Fijar'}
          >
            <Pin
              size={14}
              className={pinned ? 'text-(--accent)' : 'text-gray-500'}
              style={{
                transform: pinned ? 'rotate(0deg)' : 'rotate(45deg)',
                transition: 'color 0.3s, background-color 0.3s, border-color 0.3s, opacity 0.3s',
              }}
            />
          </button>
          <button
            type="button"
            onClick={onToggleLock}
            className="rounded p-1 transition-colors hover:bg-white/5"
            title={locked ? 'Desbloquear' : 'Bloquear'}
          >
            {locked ? (
              <Lock size={14} className="text-red-500" />
            ) : (
              <Unlock size={14} className="text-gray-500" />
