      <div className="flex items-center gap-2">
        <button
          type="button"
          onClick={onStartEditThread}
          className="bg-(--accent)/10 hover:bg-(--accent)/20 text-(--accent) rounded-xl p-2 transition-colors"
          title="Editar"
