        <button
          type="button"
          onClick={onDeleteThread}
          className="rounded-xl bg-red-500/10 p-2 text-red-500 transition-colors hover:bg-red-500/20"
          title="Eliminar"
        >
          <Trash2 size={16} />
        </button>
      </div>
    </div>
  );
}

import { useState } from "react";
import { BarChart3, CheckCircle2, ExternalLink } from "lucide-react";
import { sanitizeUrl } from "../../utils/urlUtils";

const API_URL = import.meta.env.VITE_API_URL;

interface PollOption {
  id: string;
  label: string;
  percent: number;
  votes: number;
}

interface Poll {
  id: string;
  discord_link?: string;
  question: string;
  options: PollOption[];
  totalVotes: number;
  closesIn: string;
}

interface PollDisplayProps {
  poll: Poll | null;
  refreshPoll?: () => void;
  onVote?: (optionId: string) => Promise<void>; // Optional override for testing
}

export default function PollDisplay({
  poll,
  refreshPoll,
  onVote,
}: PollDisplayProps) {
  const [voting, setVoting] = useState(false);
  const [voted, setVoted] = useState(false);

  if (!poll) return null;

  if (poll.discord_link) {
    return (
      <div
        style={{
          background: "#2f3136",
          padding: "1.5rem",
          borderRadius: "8px",
          border: "1px solid #202225",
          marginTop: "2rem",
          display: "flex",
          alignItems: "center",
          gap: "1.5rem",
        }}
      >
        <svg viewBox="0 0 24 24" fill="#5865F2" width="40" height="40">
          <path d="M20.317 4.37a19.791 19.791 0 0 0-4.885-1.515.074.074 0 0 0-.079.037c-.21.375-.444.864-.608 1.25a18.27 18.27 0 0 0-5.487 0 12.64 12.64 0 0 0-.617-1.25.077.077 0 0 0-.079-.037A19.736 19.736 0 0 0 3.677 4.37a.07.07 0 0 0-.032.027C.533 9.046-.32 13.58.099 18.057a.082.082 0 0 0 .031.057 19.9 19.9 0 0 0 5.993 3.03.078.078 0 0 0 .084-.028 14.09 14.09 0 0 0 1.226-1.994.076.076 0 0 0-.041-.106 13.107 13.107 0 0 1-1.872-.892.077.077 0 0 1-.008-.128c.125-.094.249-.192.37-.291a.074.074 0 0 1 .077-.01c3.928 1.793 8.18 1.793 12.062 0a.074.074 0 0 1 .078.01c.12.098.246.198.37.292a.077.077 0 0 1-.006.127 12.299 12.299 0 0 1-1.873.892.077.077 0 0 0-.041.107c.36.698.772 1.362 1.225 1.993a.076.076 0 0 0 .084.028 19.839 19.839 0 0 0 6.002-3.03.077.077 0 0 0 .032-.054c.5-5.177-.838-9.674-3.549-13.66a.061.061 0 0 0-.031-.03zM8.02 15.33c-1.183 0-2.157-1.085-2.157-2.419 0-1.333.955-2.419 2.157-2.419 1.21 0 2.176 1.096 2.157 2.42 0 1.333-.956 2.418-2.157 2.418zm7.975 0c-1.183 0-2.157-1.085-2.157-2.419 0-1.333.955-2.419 2.157-2.419 1.21 0 2.176 1.096 2.157 2.42 0 1.333-.946 2.418-2.157 2.418z" />
        </svg>
        <div>
          <h4 style={{ color: "#fff", marginBottom: "0.5rem" }}>
            Encuesta en Discord
          </h4>
          <p
            style={{ color: "#ccc", fontSize: "0.9rem", marginBottom: "1rem" }}
          >
            Esta encuesta se está llevando a cabo en nuestro servidor de
            Discord.
          </p>
          <a
            href={sanitizeUrl(poll.discord_link) || "#"}
            target="_blank"
            rel="noopener noreferrer"
            className="btn-primary"
            style={{
              background: "#5865F2",
              border: "none",
              display: "inline-flex",
              alignItems: "center",
              gap: "0.5rem",
            }}
          >
            Ir a Votar <ExternalLink size={12} />
          </a>
        </div>
      </div>
    );
  }

  const handleVote = async (optionId: string) => {
    if (voted) return;
    setVoting(true);
    try {
      if (onVote) {
        await onVote(optionId);
      } else {
        // Get the session token for the new secure voting backend
        const { supabase } = await import("../../services/supabaseClient");
        const {
          data: { session },
        } = await supabase.auth.getSession();

        if (!session) {
          throw new Error("Debes iniciar sesión para votar");
        }

        const response = await fetch(`${API_URL}/polls/vote`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.access_token}`,
          },
          body: JSON.stringify({ pollId: poll.id, optionId }),
        });

        if (!response.ok) {
          let errorMessage = "Error al votar";
          try {
            const contentType = response.headers.get("content-type");
            if (contentType && contentType.includes("application/json")) {
              const errorData = await response.json();
              errorMessage = errorData.message || errorMessage;
            } else {
              const textError = await response.text();
              errorMessage = textError || errorMessage;
            }
          } catch (e) {
            console.error("Error parsing response:", e);
          }
          throw new Error(errorMessage);
        }
      }
      setVoted(true);
      if (refreshPoll) refreshPoll();
    } catch (err) {
      console.error(err);
      const errorMessage =
        err instanceof Error ? err.message : "Error inesperado al votar";
      alert(errorMessage);
    } finally {
      setVoting(false);
    }
  };

  return (
    <div
      style={{
        background: "rgba(0,0,0,0.3)",
        padding: "1.5rem",
        borderRadius: "8px",
        border: "1px solid var(--accent)",
        marginTop: "2rem",
      }}
    >
      <h4
        style={{
          color: "var(--accent)",
          marginBottom: "1.5rem",
          display: "flex",
          alignItems: "center",
          gap: "0.5rem",
        }}
      >
        <BarChart3 size={18} aria-hidden="true" /> {poll.question}
      </h4>

      <div style={{ display: "flex", flexDirection: "column", gap: "0.8rem" }}>
        {poll.options.map((opt) => (
          <div
            key={opt.id}
            onClick={() => !voted && handleVote(opt.id)}
            role="button"
            aria-pressed={voted}
            aria-disabled={voted}
            aria-label={`${opt.label}, ${opt.percent}% de votos`}
            tabIndex={voted ? -1 : 0}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                if (!voted) handleVote(opt.id);
              }
            }}
            style={{
              position: "relative",
              height: "40px",
              background: "rgba(255,255,255,0.05)",
              borderRadius: "6px",
              overflow: "hidden",
              cursor: voted ? "default" : "pointer",
            }}
          >
            <div
              style={{
                width: `${opt.percent}%`,
                height: "100%",
                background: "var(--accent)",
                opacity: 0.2,
                position: "absolute",
                top: 0,
                left: 0,
                transition: "width 0.5s",
              }}
            ></div>

            <div
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                width: "100%",
                height: "100%",
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                padding: "0 1rem",
              }}
            >
              <span style={{ fontWeight: 500, color: "#fff", zIndex: 1 }}>
                {opt.label}
              </span>
              <span
                style={{
                  fontWeight: "bold",
                  color: "var(--accent)",
                  zIndex: 1,
                }}
              >
                {opt.percent}%{" "}
                {voted && (
                  <span style={{ fontSize: "0.8rem", color: "#888" }}>
                    ({opt.votes})
                  </span>
                )}
              </span>
            </div>
          </div>
        ))}
      </div>

      <div
        style={{
          marginTop: "1rem",
          textAlign: "right",
          fontSize: "0.85rem",
          color: "#888",
        }}
      >
        Total: {poll.totalVotes} votos •{" "}
        {poll.closesIn === "Finalizada"
          ? "Finalizada"
          : `Cierra en ${poll.closesIn}`}
        {voted && (
          <span style={{ marginLeft: "1rem", color: "#22c55e" }}>
            <CheckCircle2
              size={14}
              style={{ display: "inline", verticalAlign: "middle" }}
              aria-hidden="true"
            />{" "}
            Votado
          </span>
        )}
      </div>
      {voting && (
        <div
          role="status"
          aria-live="polite"
          style={{
            marginTop: "0.5rem",
            color: "var(--accent)",
            fontSize: "0.9rem",
          }}
        >
          Enviando voto...
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useRef } from "react";
import * as THREE from "three";
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
import { buildArcadeMachine, disposeArcadeMachine } from "./buildArcadeMachine";
import {
  bindScreenReels,
  createScreenReels,
  type ScreenReelsController,
} from "./screenReels";
import { reelsToImageStrips, type GachaSpinSync } from "./gachaSpinSync";
import type { GachaReward, MappedGachaResult } from "../../pages/Gacha/types";
import { resolveAssetUrl } from "../../utils/assetUtils";
import "../../styles/widgets/gacha_3d_showcase.css";

interface Gacha3DShowcaseProps {
  tierId: string;
  tierColor: string;
  isOpening?: boolean;
  isCelebrating?: boolean;
  spinSync?: GachaSpinSync | null;
  reelItemsSet?: (GachaReward | MappedGachaResult)[][];
}

type EmissiveMat = THREE.MeshStandardMaterial & {
  userData: { baseEmissive?: number };
};

const gltfBufferCache = new Map<string, Promise<ArrayBuffer>>();

function getGltfBuffer(tierId: string): Promise<ArrayBuffer> {
  if (!gltfBufferCache.has(tierId)) {
    const fileLoader = new THREE.FileLoader();
    fileLoader.setResponseType("arraybuffer");
    const promise = fileLoader.loadAsync(
      resolveAssetUrl(`/models/gacha/cabinet_${tierId}.glb`),
    ) as Promise<ArrayBuffer>;
    gltfBufferCache.set(tierId, promise);
  }
  return gltfBufferCache.get(tierId)!;
}

// Prefetch all cabinet GLB models in background so machine switches are instant
["bronze", "silver", "gold", "emerald", "diamond", "iridium", "ultra"].forEach(
  (tier) => {
    getGltfBuffer(tier).catch(() => {});
  },
);

const DEFAULT_REEL_ITEMS_SET: (GachaReward | MappedGachaResult)[][] = [
  [],
  [],
  [],
];

const Gacha3DShowcase: React.FC<Gacha3DShowcaseProps> = ({
  tierId,
  tierColor,
  isOpening = false,
  isCelebrating = false,
  spinSync = null,
  reelItemsSet = DEFAULT_REEL_ITEMS_SET,
}) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const modelRef = useRef<THREE.Group | null>(null);
  const accentLightRef = useRef<THREE.PointLight | null>(null);
  const mixerRef = useRef<THREE.AnimationMixer | null>(null);
  const winActionRef = useRef<THREE.AnimationAction | null>(null);
  const screenReelsRef = useRef<ScreenReelsController | null>(null);
  const winLightsRef = useRef<THREE.Object3D | null>(null);
  const coinBadgeRef = useRef<THREE.Object3D | null>(null);
  const coinMatsRef = useRef<EmissiveMat[]>([]);
  const coinLightRef = useRef<THREE.PointLight | null>(null);
  const emissiveMatsRef = useRef<EmissiveMat[]>([]);
  const isOpeningRef = useRef(isOpening);
  const isCelebratingRef = useRef(isCelebrating);
  const prevTierRef = useRef(tierId);
  const stripsInitializedRef = useRef(false);
  const clockRef = useRef<THREE.Clock | null>(null);
  const fromGltfRef = useRef(false);

  useEffect(() => {
    isOpeningRef.current = isOpening;
  }, [isOpening]);

  useEffect(() => {
    if (!spinSync?.id) return;
    screenReelsRef.current?.playSpin(spinSync);
  }, [spinSync]);

  useEffect(() => {
    if (!reelItemsSet.every((col) => col.length > 0)) return;

    const tierChanged = prevTierRef.current !== tierId;
    prevTierRef.current = tierId;

    if (!tierChanged && stripsInitializedRef.current) return;

    stripsInitializedRef.current = true;
    screenReelsRef.current?.setStrips(reelsToImageStrips(reelItemsSet), {
      resetPosition: true,
    });
  }, [tierId, reelItemsSet]);

  useEffect(() => {
    isCelebratingRef.current = isCelebrating;
    if (!isCelebrating) return;
    const action = winActionRef.current;
    if (!action) return;
    action.reset();
    action.setLoop(THREE.LoopOnce, 1);
    action.clampWhenFinished = true;
    action.play();
  }, [isCelebrating]);

  useEffect(() => {
    if (accentLightRef.current) {
      accentLightRef.current.color.set(tierColor);
    }
    if (coinLightRef.current) {
      coinLightRef.current.color.set(tierColor);
    }
    for (const mat of coinMatsRef.current) {
      mat.emissive.set(tierColor);
    }
  }, [tierColor]);

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;

    if (!clockRef.current) {
      clockRef.current = new THREE.Clock();
    }

    const width = mount.clientWidth || 280;
    const height = mount.clientHeight || 420;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(38, width / height, 0.1, 100);
    camera.position.set(2.4, 0.55, 5.6);
    camera.lookAt(0, 0.15, 0);

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
      powerPreference: "high-performance",
      preserveDrawingBuffer: true,
    });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setClearColor(0x000000, 0);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.28;
    mount.appendChild(renderer.domElement);

    scene.add(new THREE.AmbientLight(0xffffff, 0.88));
    scene.add(new THREE.HemisphereLight(0xd8e8ff, 0x2a2420, 0.52));

    const keyLight = new THREE.DirectionalLight(0xfff8f0, 1.55);
    keyLight.position.set(3, 5, 4);
    scene.add(keyLight);

    const fillLight = new THREE.DirectionalLight(0xb8c8e8, 0.62);
    fillLight.position.set(-3, 2, 2);
    scene.add(fillLight);

    const rimLight = new THREE.DirectionalLight(0xffd8b0, 0.38);
    rimLight.position.set(-1.5, 1.2, -3);
    scene.add(rimLight);

    const accentLight = new THREE.PointLight(tierColor, 1.25, 14);
    accentLight.position.set(1.5, 2.5, 3.5);
    accentLightRef.current = accentLight;
    scene.add(accentLight);

    const coinLight = new THREE.PointLight(tierColor, 0.32, 4.5);
    coinLight.position.set(0, 1.6, 1.4);
    coinLightRef.current = coinLight;
    scene.add(coinLight);

    const screenReels = createScreenReels(tierColor || "#5eead4");
    screenReelsRef.current = screenReels;

    let disposed = false;
    let frameId = 0;
    let idleAngle = 0;
    clockRef.current = new THREE.Clock();

    const prepareGltfMaterials = (root: THREE.Object3D) => {
      root.traverse((child) => {
        if (!(child instanceof THREE.Mesh)) return;
        child.castShadow = false;
        child.receiveShadow = false;
        child.frustumCulled = false;
        child.visible = true;
        const materials = Array.isArray(child.material)
          ? child.material
          : [child.material];
        for (const mat of materials) {
          if (!mat) continue;
          mat.side = THREE.DoubleSide;
          mat.visible = true;
          mat.transparent = false;
          mat.opacity = 1;
          mat.alphaTest = 0;
          mat.depthWrite = true;
          mat.depthTest = true;
          if ("alphaMap" in mat) mat.alphaMap = null;
          if (
            mat instanceof THREE.MeshStandardMaterial ||
            mat instanceof THREE.MeshPhysicalMaterial
          ) {
            mat.metalness = 0;
            mat.roughness = Math.min(
              Math.max(mat.roughness || 0.7, 0.42),
              0.88,
            );
            mat.color.set(0xffffff);
            if (mat.map) {
              mat.map.colorSpace = THREE.SRGBColorSpace;
              mat.map.premultiplyAlpha = false;
              mat.map.flipY = false;
              mat.map.needsUpdate = true;
            }
            if (mat.emissiveMap)
              mat.emissiveMap.colorSpace = THREE.SRGBColorSpace;
            if (!mat.map && mat.color.getHex() === 0) {
              mat.color.set(tierColor || "#cd7f32");
            }

            const isVividPart =
              /marquee|mface|title|screen|led|btn|neon|fascia|accent|coin|rim|joy_t|waves/i.test(
                child.name,
              );
            if (mat.map && isVividPart) {
              mat.emissiveMap = mat.map;
              mat.emissive.set(0xffffff);
              mat.emissiveIntensity = 0.24;
            } else if (mat.map) {
              mat.emissive.setHex(0x101820);
              mat.emissiveIntensity = 0.11;
            } else {
              mat.emissive.setHex(0x000000);
              mat.emissiveIntensity = 0;
            }
            mat.envMapIntensity = 0;
            mat.needsUpdate = true;
          } else if (mat instanceof THREE.MeshBasicMaterial) {
            if (mat.map) mat.map.colorSpace = THREE.SRGBColorSpace;
            mat.needsUpdate = true;
          }
        }
      });
    };

    const fitAndFrame = (model: THREE.Object3D, targetSize = 3.35) => {
      model.scale.setScalar(1);
      model.position.set(0, 0, 0);
      model.rotation.set(0, 0, 0);
      model.updateMatrixWorld(true);

      const box = new THREE.Box3().setFromObject(model);
      const size = box.getSize(new THREE.Vector3());
      const center = box.getCenter(new THREE.Vector3());
      const dim = Math.max(size.x, size.y, size.z, 0.001);
      model.position.x -= center.x;
      model.position.y -= center.y;
      model.position.z -= center.z;
      model.scale.setScalar(targetSize / dim);
      model.updateMatrixWorld(true);

      const box2 = new THREE.Box3().setFromObject(model);
      const size2 = box2.getSize(new THREE.Vector3());
      const center2 = box2.getCenter(new THREE.Vector3());
      model.position.x -= center2.x;
      model.position.y -= center2.y;
      model.position.z -= center2.z;
      model.userData.baseY = model.position.y;

      const fitH = Math.max(size2.y, 0.001);
      const fitW = Math.max(size2.x, 0.001);
      const fov = camera.fov * (Math.PI / 180);
      const distForH = fitH / (2 * Math.tan(fov / 2));
      const distForW = fitW / (2 * Math.tan(fov / 2) * camera.aspect);
      const dist = Math.max(distForH, distForW) * 1.22;

      camera.near = 0.05;
      camera.far = Math.max(100, dist * 4);
      camera.position.set(dist * 0.28, fitH * 0.06, dist);
      camera.lookAt(0, fitH * 0.02, 0);
      camera.updateProjectionMatrix();
    };

    const releaseModel = (model: THREE.Group | null) => {
      if (!model) return;
      scene.remove(model);
      // GLTF resources may be loader-cached — disposing them blanks remounts (React Strict Mode).
      if (!model.userData.fromGltf) {
        disposeArcadeMachine(model);
      }
    };

    const cacheEmissive = (root: THREE.Object3D) => {
      const mats: EmissiveMat[] = [];
      root.traverse((child) => {
        if (!(child instanceof THREE.Mesh)) return;
        const materials = Array.isArray(child.material)
          ? child.material
          : [child.material];
        for (const m of materials) {
          if (!(m instanceof THREE.MeshStandardMaterial)) continue;
          if (m.emissiveIntensity <= 0.05 && m.emissive.getHex() === 0)
            continue;
          m.userData.baseEmissive = m.emissiveIntensity;
          mats.push(m as EmissiveMat);
        }
      });
      emissiveMatsRef.current = mats;
    };

    const bindWinLights = (
      root: THREE.Object3D,
      animations: THREE.AnimationClip[],
    ) => {
      const winLights =
        root.getObjectByName("marquee_leds") ||
        root.getObjectByName("win_lights") ||
        null;
      winLightsRef.current = winLights;

      const coinBadge =
        root.getObjectByName("coin_badge") ||
        root.getObjectByName("badge") ||
        null;
      coinBadgeRef.current = coinBadge;

      const coinMats: EmissiveMat[] = [];
      const markCoinMat = (child: THREE.Object3D) => {
        if (!(child instanceof THREE.Mesh)) return;
        const materials = Array.isArray(child.material)
          ? child.material
          : [child.material];
        for (const m of materials) {
          if (!(m instanceof THREE.MeshStandardMaterial)) continue;
          if (m.map) m.emissiveMap = m.map;
          m.emissive = new THREE.Color(tierColor);
          m.userData.baseEmissive = 0.4;
          m.emissiveIntensity = 0.4;
          coinMats.push(m as EmissiveMat);
        }
      };
      if (coinBadge) {
        coinBadge.traverse(markCoinMat);
      } else {
        root.traverse((child) => {
          if (/badge|coin/i.test(child.name)) markCoinMat(child);
        });
      }
      coinMatsRef.current = coinMats;

      if (coinBadge && coinLightRef.current) {
        const world = new THREE.Vector3();
        coinBadge.getWorldPosition(world);
        coinLightRef.current.position.copy(world);
        coinLightRef.current.position.z += 0.6;
      }

      void screenReels.ready.then(() => {
        if (disposed) return;
        bindScreenReels(root, screenReels, tierColor || "#5eead4");
      });

      const clip = animations.find((c) => /win_flash/i.test(c.name)) || null;
      if (!clip) {
        mixerRef.current = null;
        winActionRef.current = null;
        return;
      }
      const mixer = new THREE.AnimationMixer(root);
      mixerRef.current = mixer;
      const action = mixer.clipAction(clip);
      action.setLoop(THREE.LoopOnce, 1);
      action.clampWhenFinished = true;
      winActionRef.current = action;
    };

    const mountModel = (
      model: THREE.Group,
      animations: THREE.AnimationClip[] = [],
      fromGltf = false,
    ) => {
      if (disposed) {
        if (!fromGltf) disposeArcadeMachine(model);
        return;
      }
      releaseModel(modelRef.current);
      model.userData.fromGltf = fromGltf;
      if (fromGltf) prepareGltfMaterials(model);
      fitAndFrame(model);
      cacheEmissive(model);
      bindWinLights(model, animations);
      modelRef.current = model;
      fromGltfRef.current = fromGltf;
      scene.add(model);
    };

    const loader = new GLTFLoader();

    // Fetch and parse GLTF directly from module cache.
    getGltfBuffer(tierId)
      .then(
        (buffer) =>
          new Promise<void>((resolve, reject) => {
            loader.parse(
              buffer,
              "/models/gacha/",
              (gltf) => {
                if (disposed) {
                  resolve();
                  return;
                }
                const root = gltf.scene;
                root.name = `arcade-gltf-${tierId}`;
                let meshCount = 0;
                root.traverse((c) => {
                  if (c instanceof THREE.Mesh) meshCount += 1;
                });
                if (meshCount === 0) {
                  reject(new Error("GLTF scene has no meshes"));
                  return;
                }
                mountModel(root, gltf.animations || [], true);
                resolve();
              },
              reject,
            );
          }),
      )
      .catch(() => {
        if (!disposed) {
          const procedural = buildArcadeMachine(tierId);
          mountModel(procedural, [], false);
        }
      });

    (window as unknown as { __gacha3d?: unknown }).__gacha3d = {
      scene,
      camera,
      renderer,
      getInfo: () => {
        const current = modelRef.current;
        if (!current) return { mounted: false };
        const box = new THREE.Box3().setFromObject(current);
        const size = box.getSize(new THREE.Vector3());
        let meshes = 0;
        let withMap = 0;
        let black = 0;
        current.traverse((c) => {
          if (!(c instanceof THREE.Mesh)) return;
          meshes += 1;
          const materials = Array.isArray(c.material)
            ? c.material
            : [c.material];
          for (const m of materials) {
            if (!m) continue;
            if ("map" in m && m.map) withMap += 1;
            if (
              "color" in m &&
              m.color &&
              (m.color as THREE.Color).getHex?.() === 0
            )
              black += 1;
          }
        });

        const corners = [
          new THREE.Vector3(box.min.x, box.min.y, box.min.z),
          new THREE.Vector3(box.min.x, box.min.y, box.max.z),
          new THREE.Vector3(box.min.x, box.max.y, box.min.z),
          new THREE.Vector3(box.min.x, box.max.y, box.max.z),
          new THREE.Vector3(box.max.x, box.min.y, box.min.z),
          new THREE.Vector3(box.max.x, box.min.y, box.max.z),
          new THREE.Vector3(box.max.x, box.max.y, box.min.z),
          new THREE.Vector3(box.max.x, box.max.y, box.max.z),
        ].map((v) => {
          const n = v.clone().project(camera);
          return {
            x: +((n.x * 0.5 + 0.5) * mount.clientWidth).toFixed(1),
            y: +((-n.y * 0.5 + 0.5) * mount.clientHeight).toFixed(1),
            z: +n.z.toFixed(3),
            clip: Math.abs(n.x) > 1 || Math.abs(n.y) > 1 || n.z > 1 || n.z < -1,
          };
        });
        const xs = corners.map((c) => c.x);
        const ys = corners.map((c) => c.y);
        return {
          mounted: true,
          fromGltf: !!current.userData.fromGltf,
          name: current.name,
          meshes,
          withMap,
          black,
          mats: (() => {
            const sample: Array<Record<string, unknown>> = [];
            current.traverse((c) => {
              if (!(c instanceof THREE.Mesh) || sample.length >= 6) return;
              const m = Array.isArray(c.material) ? c.material[0] : c.material;
              if (!(m instanceof THREE.MeshStandardMaterial)) return;
              sample.push({
                mesh: c.name,
                metalness: m.metalness,
                roughness: m.roughness,
                map: !!m.map,
                mapW: m.map?.image?.width ?? null,
                mapH: m.map?.image?.height ?? null,
                color: `#${m.color.getHexString()}`,
              });
            });
            return sample;
          })(),
          size: {
            x: +size.x.toFixed(3),
            y: +size.y.toFixed(3),
            z: +size.z.toFixed(3),
          },
          pos: {
            x: +current.position.x.toFixed(3),
            y: +current.position.y.toFixed(3),
            z: +current.position.z.toFixed(3),
          },
          scale: +current.scale.x.toFixed(3),
          mount: {
            w: mount.clientWidth,
            h: mount.clientHeight,
          },
          cam: {
            x: +camera.position.x.toFixed(3),
            y: +camera.position.y.toFixed(3),
            z: +camera.position.z.toFixed(3),
            fov: camera.fov,
            aspect: +camera.aspect.toFixed(3),
          },
          projected: {
            minX: +Math.min(...xs).toFixed(1),
            maxX: +Math.max(...xs).toFixed(1),
            minY: +Math.min(...ys).toFixed(1),
            maxY: +Math.max(...ys).toFixed(1),
            fillW: +(
              ((Math.max(...xs) - Math.min(...xs)) / mount.clientWidth) *
              100
            ).toFixed(1),
            fillH: +(
              ((Math.max(...ys) - Math.min(...ys)) / mount.clientHeight) *
              100
            ).toFixed(1),
            corners,
          },
        };
      },
    };

    const animate = () => {
      frameId = requestAnimationFrame(animate);
      if (!clockRef.current) clockRef.current = new THREE.Clock();
      const dt = clockRef.current.getDelta();
      if (mixerRef.current) mixerRef.current.update(dt);
      screenReelsRef.current?.update(dt);

      const current = modelRef.current;
      const celebrating = isCelebratingRef.current;
      const opening = isOpeningRef.current;

      if (current) {
        const baseY =
          typeof current.userData.baseY === "number"
            ? current.userData.baseY
            : 0;
        idleAngle += celebrating ? 0.05 : opening ? 0.035 : 0.008;
        current.rotation.y =
          Math.sin(idleAngle) * (celebrating || opening ? 0.08 : 0.14);

        if (celebrating) {
          current.position.y = baseY + Math.sin(idleAngle * 3.2) * 0.05;
          accentLight.intensity = 1.35 + Math.sin(idleAngle * 10) * 0.55;
        } else if (opening) {
          current.position.y = baseY + Math.sin(idleAngle * 2.4) * 0.04;
          accentLight.intensity = 0.85 + Math.sin(idleAngle * 4) * 0.3;
        } else {
          current.position.y = baseY;
          accentLight.intensity = 1.05;
        }

        for (const mat of emissiveMatsRef.current) {
          const base = mat.userData.baseEmissive ?? 0.3;
          if (celebrating) {
            mat.emissiveIntensity =
              base * (2.2 + Math.sin(idleAngle * 12) * 1.4);
          } else if (opening) {
            mat.emissiveIntensity =
              base * (1.2 + Math.sin(idleAngle * 5) * 0.45);
          } else {
            mat.emissiveIntensity = base;
          }
        }

        for (const mat of coinMatsRef.current) {
          const base = mat.userData.baseEmissive ?? 0.35;
          if (celebrating) {
            mat.emissiveIntensity =
              base * (3.2 + Math.sin(idleAngle * 14) * 2.2);
          } else if (opening) {
            mat.emissiveIntensity =
              base * (1.8 + Math.sin(idleAngle * 7) * 0.9);
          } else {
            mat.emissiveIntensity =
              base * (1.15 + Math.sin(idleAngle * 2.2) * 0.45);
          }
        }

        if (coinLightRef.current) {
          if (celebrating) {
            coinLightRef.current.intensity =
              0.75 + Math.sin(idleAngle * 14) * 0.45;
          } else if (opening) {
            coinLightRef.current.intensity =
              0.45 + Math.sin(idleAngle * 6) * 0.2;
          } else {
            coinLightRef.current.intensity =
              0.28 + Math.sin(idleAngle * 2.2) * 0.1;
          }
        }

        if (!winActionRef.current && winLightsRef.current && celebrating) {
          winLightsRef.current.children.forEach((child, i) => {
            const pulse =
              0.85 + Math.abs(Math.sin(idleAngle * 8 - i * 0.45)) * 0.7;
            child.scale.setScalar(pulse);
          });
        } else if (
          !winActionRef.current &&
          winLightsRef.current &&
          !celebrating
        ) {
          winLightsRef.current.children.forEach((child) => {
            child.scale.setScalar(0.85);
          });
        }

        if (!winActionRef.current && coinBadgeRef.current) {
          const pulse = celebrating
            ? 1 + Math.abs(Math.sin(idleAngle * 10)) * 0.22
            : 1 + Math.sin(idleAngle * 2.4) * 0.04;
          coinBadgeRef.current.scale.setScalar(pulse);
        }

        const stick = current.getObjectByName("joystick-stick");
        if (stick) {
          stick.rotation.z = Math.sin(idleAngle * 1.6) * 0.18;
        }
      }
      renderer.render(scene, camera);
    };
    animate();

    const onResize = () => {
      if (!mount) return;
      const w = mount.clientWidth || 280;
      const h = mount.clientHeight || 420;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };
    window.addEventListener("resize", onResize);
    const ro = new ResizeObserver(onResize);
    ro.observe(mount);

    return () => {
      disposed = true;
      cancelAnimationFrame(frameId);
      window.removeEventListener("resize", onResize);
      ro.disconnect();
      const dbg = window as unknown as { __gacha3d?: unknown };
      if (dbg.__gacha3d) delete dbg.__gacha3d;
      mixerRef.current?.stopAllAction();
      mixerRef.current = null;
      winActionRef.current = null;
      screenReelsRef.current?.dispose();
      screenReelsRef.current = null;
      winLightsRef.current = null;
      coinBadgeRef.current = null;
      coinMatsRef.current = [];
      emissiveMatsRef.current = [];
      if (coinLightRef.current) {
        scene.remove(coinLightRef.current);
        coinLightRef.current = null;
      }
      releaseModel(modelRef.current);
      modelRef.current = null;
      accentLightRef.current = null;
      renderer.dispose();
      if (mount.contains(renderer.domElement)) {
        mount.removeChild(renderer.domElement);
      }
    };
  }, [tierId, tierColor]);

  return (
    <div
      className={`gacha-3d-showcase ${isOpening ? "is-spinning" : ""} ${isCelebrating ? "is-celebrating" : ""}`}
      style={{ "--tier-color": tierColor } as React.CSSProperties}
      aria-hidden="true"
    >
      <div className="showcase-pedestal">
        <div className="pedestal-top" />
        <div className="pedestal-glow" />
      </div>
      <div ref={mountRef} className="three-container" />
      <span className="showcase-caption">{tierId} cabinet</span>
    </div>
  );
};

