/** Event mega-cab with stepped silhouette (ultra). */
function buildUltra(p: CabinetPalette): THREE.Group {
  const root = new THREE.Group();
  const body = mat(p.body);
  const dark = mat(p.bodyDark);
  const trim = metalBand(p);
  const panel = mat(p.panel);
  const screen = mat(p.screen, { emissive: p.accent, emissiveIntensity: 0.35 });
  const frame = mat(p.trim, { emissive: p.accentGlow, emissiveIntensity: 0.55 });

  // Stepped base
  root.add(box(2.6, 0.2, 1.7, dark, 0, 0.1, 0));
  root.add(box(2.3, 0.7, 1.5, body, 0, 0.55, 0));
  root.add(box(2.0, 0.9, 1.35, body, 0, 1.35, 0));
  root.add(box(2.35, 0.14, 1.55, trim, 0, 0.95, 0, 'rainbow-belt'));

  const deck = box(2.2, 0.16, 1.1, panel, 0, 2.0, 0.55);
  deck.rotation.x = -0.32;
  root.add(deck);
  addControls(root, p, 2.2, 0.9, { joyX: -0.75, wide: true });
  root.add(box(0.18, 0.1, 0.18, mat(p.button, { emissive: p.accent, emissiveIntensity: 0.4 }), 0.75, 2.2, 0.9));

  // Twin screen look
  root.add(box(2.1, 1.75, 1.1, body, 0, 3.15, -0.05));
  root.add(box(0.85, 1.15, 0.1, frame, -0.5, 3.2, 0.52));
  root.add(box(0.85, 1.15, 0.1, frame, 0.5, 3.2, 0.52));
  root.add(box(0.72, 1.0, 0.06, screen, -0.5, 3.2, 0.58, 'screen'));
  root.add(box(0.72, 1.0, 0.06, screen, 0.5, 3.2, 0.58));

  root.add(box(2.4, 0.7, 0.75, dark, 0, 4.25, 0.05));
  root.add(box(2.1, 0.4, 0.12, panel, 0, 4.3, 0.42, 'marquee'));
  root.add(box(1.9, 0.1, 0.1, trim, 0, 4.0, 0.45, 'marquee-underline'));
  addCoinBadge(root, p, 0, 4.3, 0.52, 0.58);
  addShadow(root, 1.55);
  root.position.set(0, -2.25, 0);
  return root;
}

const BUILDERS: Record<GachaCabinetTier, (p: CabinetPalette) => THREE.Group> = {
  bronze: buildBronze,
  silver: buildSilver,
  gold: buildGold,
  emerald: buildEmerald,
  diamond: buildDiamond,
  iridium: buildIridium,
  ultra: buildUltra,
};

export function buildArcadeMachine(tierId: string = 'bronze'): THREE.Group {
  const key = (tierId in PALETTES ? tierId : 'bronze') as GachaCabinetTier;
  const palette = PALETTES[key];
  const root = BUILDERS[key](palette);
  root.name = `arcade-${key}`;
  root.userData.tierId = key;
  root.userData.palette = palette;
  return root;
}

export function disposeArcadeMachine(root: THREE.Group) {
  const disposedMats = new Set<THREE.Material>();
  const disposedTex = new Set<THREE.Texture>();
  root.traverse((child) => {
    if (!(child instanceof THREE.Mesh)) return;
    child.geometry.dispose();
    const materials = Array.isArray(child.material) ? child.material : [child.material];
    for (const m of materials) {
      if (disposedMats.has(m)) continue;
      disposedMats.add(m);
      if (m instanceof THREE.MeshStandardMaterial) {
        if (m.map && !disposedTex.has(m.map)) {
          disposedTex.add(m.map);
          m.map.dispose();
        }
        if (m.emissiveMap && !disposedTex.has(m.emissiveMap)) {
          disposedTex.add(m.emissiveMap);
          m.emissiveMap.dispose();
        }
      }
      m.dispose();
    }
  });
}

import { useState, useEffect, useMemo } from 'react'
import useEmblaCarousel from 'embla-carousel-react'
import createAutoplay from 'embla-carousel-autoplay' // Embla: alias de función de fábrica en minúscula para evitar confusión con componentes React (react/capitalized-calls)
import createFade from 'embla-carousel-fade' // Embla: alias de función de fábrica en minúscula para evitar confusión con componentes React (react/capitalized-calls)

const IMAGES = [
    '/images/backgrounds/hero-bg-1.webp',
    '/images/backgrounds/hero-bg-2.webp',
    '/images/backgrounds/hero-bg-3.webp',
    '/images/backgrounds/hero-bg-4.webp',
    '/images/backgrounds/hero-bg-5.webp'
]

const DEFAULT_SLIDES: Slide[] = []; // React: array estático fuera del render para preservar igualdad referencial (react/no-object-type-as-default-prop)

interface Slide {
    image: string;
    title?: string;
    text?: string;
    buttonText?: string;
    link?: string;
}

interface HeroBackgroundCarouselProps {
    slides?: Slide[];
}

const HeroBackgroundCarousel = ({ slides = DEFAULT_SLIDES }: HeroBackgroundCarouselProps) => { // React: uso de referencia estable por defecto
    const [loadSecondary, setLoadSecondary] = useState(false)
    const prefersReducedMotion = typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    const plugins = useMemo(() => {
        const list = [createFade()]; // Embla: invocación de fábrica segura
        if (!prefersReducedMotion) {
            list.unshift(createAutoplay({ delay: 6000, stopOnInteraction: false })); // Embla: invocación de fábrica segura
        }
        return list;
    }, [prefersReducedMotion]);

    const [emblaRef] = useEmblaCarousel(
        { loop: !prefersReducedMotion, watchDrag: false, duration: 40 },
        plugins
    )

    useEffect(() => {
        const timer = setTimeout(() => setLoadSecondary(true), 2500)
        return () => clearTimeout(timer)
    }, [])

    const hasDynamicSlides = slides && slides.length > 0;
    const items: Slide[] = hasDynamicSlides ? slides : IMAGES.map(src => ({ image: src }));

    return (
        <div className="absolute inset-0 z-0 overflow-hidden" ref={emblaRef} aria-hidden={!hasDynamicSlides}>
            <div className="flex touch-pan-y h-full">
                {items.map((slide, index) => (
                    <div className="relative flex-[0_0_100%] min-w-0 h-full overflow-hidden" key={slide.image}>
                        {(index === 0 || loadSecondary) && (
                            <img
                                src={slide.image}
                                alt=""
                                aria-hidden="true"
                                className="absolute inset-0 w-full h-full object-cover animate-slow-zoom motion-reduce:animate-none"
                                fetchPriority={index === 0 ? "high" : "low"}
                                loading={index === 0 ? "eager" : "lazy"}
                                decoding="async"
                            />
                        )}
                        {/* Gradient Overlays */}
                        <div className="absolute inset-0 bg-black/50"></div>
                        <div className="absolute inset-0 bg-linear-to-t from-black via-transparent to-black/60"></div>
                        <div className="absolute inset-0 bg-linear-to-r from-black/20 via-transparent to-black/20"></div>

                        {/* Dynamic Content Overlay */}
                        {hasDynamicSlides && (slide.title || slide.text) && (
                            <div className="absolute inset-0 flex flex-col items-center justify-center p-6 text-center z-10">
                                <div className="max-w-4xl animate-fade-in-up">
                                    {slide.title && (
                                        <h2 className="text-4xl md:text-7xl font-black uppercase tracking-tighter text-white mb-4 drop-shadow-2xl">
                                            {slide.title}
                                        </h2>
                                    )}
                                    {slide.text && (
                                        <p className="text-lg md:text-2xl text-gray-200 font-medium mb-8 drop-shadow-lg">
                                            {slide.text}
                                        </p>
                                    )}
                                    {slide.buttonText && (
                                        <a 
                                            href={slide.link || '#'} 
                                            className="px-8 py-4 bg-(--accent) text-black font-black uppercase tracking-widest rounded-2xl shadow-2xl hover:scale-110 active:scale-95 transition-colors inline-block"
                                        >
                                            {slide.buttonText}
                                        </a>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>
                ))}
            </div>
        </div>
    )
}

