interface AccountSwitcherModalProps {
  onClose: () => void;
  onNavigateSettings: () => void;
}

export const AccountSwitcherModal: React.FC<AccountSwitcherModalProps> = ({
  onClose,
  onNavigateSettings,
}) => {
  const {
    currentSession,
    crystalSession,
    savedAccounts,
    selectAccount,
    removeAccount,
    logout,
  } = useAuth();

  const [avatarPref, setAvatarPref] = useState<"web" | "minecraft">(
    () => getSettings().avatarPreference || "web"
  );

  const handleToggleAvatarPref = (pref: "web" | "minecraft") => {
    setAvatarPref(pref);
    saveSettings({ avatarPreference: pref });
    window.dispatchEvent(new Event("crystaltides_settings_updated"));
  };

  return (
    <>
      {/* Backdrop */}
      <div
        onClick={onClose}
        role="presentation"
        style={{
          position: "fixed",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          zIndex: 999,
          backgroundColor: "transparent",
        }}
      />

