        role="dialog"
        aria-modal="true"
        aria-labelledby="account-switcher-title"
        className="reveal-up"
        style={{
          position: "fixed",
          left: 92,
          bottom: 24,
          width: 330,
          backgroundColor: "rgba(13, 17, 23, 0.95)",
          backdropFilter: "blur(16px)",
          border: "1px solid rgba(45, 212, 191, 0.25)",
          borderRadius: 16,
          boxShadow: "0 16px 36px rgba(0, 0, 0, 0.6), 0 0 20px rgba(45, 212, 191, 0.15)",
          zIndex: 1000,
          padding: 16,
          display: "flex",
          flexDirection: "column",
          gap: 12,
        }}
      >
        {/* Title */}
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <span id="account-switcher-title" style={{ fontSize: 13, fontWeight: 800, color: "#FFF", letterSpacing: "0.05em", textTransform: "uppercase" }}>
            👤 Selector de Sesiones
          </span>
          <button aria-label="Cerrar selector de sesiones" type="button"
            onClick={onClose}
            style={{
              background: "none",
              border: "none",
              color: "rgba(255, 255, 255, 0.5)",
              cursor: "pointer",
              fontSize: 16,
              padding: "2px 6px",
            }}
          >
            ✕
          </button>
        </div>

        {/* Avatar Source Preference Toggle */}
        <div style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          backgroundColor: "rgba(255, 255, 255, 0.03)",
          border: "1px solid rgba(255, 255, 255, 0.08)",
          borderRadius: 10,
          padding: "6px 10px",
        }}>
          <span style={{ fontSize: 11, fontWeight: 600, color: "rgba(255, 255, 255, 0.7)" }}>
            🖼️ Icono del Avatar:
          </span>
          <div style={{ display: "flex", gap: 4 }}>
            <button type="button"
              onClick={() => handleToggleAvatarPref("web")}
              title="Usar Foto de Perfil de la Web"
              style={{
                backgroundColor: avatarPref === "web" ? "rgba(45, 212, 191, 0.25)" : "transparent",
                border: `1px solid ${avatarPref === "web" ? "var(--accent)" : "rgba(255,255,255,0.15)"}`,
                color: avatarPref === "web" ? "#2DD4BF" : "rgba(255,255,255,0.5)",
                fontSize: 10,
                fontWeight: 700,
                borderRadius: 6,
                padding: "3px 8px",
                cursor: "pointer",
                transition: "color 0.15s ease, background-color 0.15s ease, border-color 0.15s ease, opacity 0.15s ease",
              }}
            >
              🌊 Web
            </button>
            <button type="button"
              onClick={() => handleToggleAvatarPref("minecraft")}
              title="Usar Cabeza de Minecraft"
              style={{
                backgroundColor: avatarPref === "minecraft" ? "rgba(45, 212, 191, 0.25)" : "transparent",
                border: `1px solid ${avatarPref === "minecraft" ? "var(--accent)" : "rgba(255,255,255,0.15)"}`,
                color: avatarPref === "minecraft" ? "#2DD4BF" : "rgba(255,255,255,0.5)",
                fontSize: 10,
                fontWeight: 700,
                borderRadius: 6,
                padding: "3px 8px",
                cursor: "pointer",
                transition: "color 0.15s ease, background-color 0.15s ease, border-color 0.15s ease, opacity 0.15s ease",
              }}
            >
              ⛏️ Minecraft
            </button>
          </div>
        </div>

        {/* Section 1: CrystalTides Web Account */}
        <div style={{
          backgroundColor: "rgba(45, 212, 191, 0.04)",
          border: "1px solid rgba(45, 212, 191, 0.15)",
          borderRadius: 12,
