              {SAMPLE_FRIENDS_OFFLINE.map((friend) => (
                <div
                  key={friend.name}
                  className="group flex cursor-pointer items-center justify-between rounded-lg p-1.5 opacity-50 transition-colors hover:bg-white/5 hover:opacity-100"
