                      ? "Quitar Capa"
                      : userCapes[selectedCapeIndex]?.state === "ACTIVE"
                        ? "Equipada"
                        : "Equipar Capa"}
                </button>
              </div>
            )}
          </CrystalCard>
        </div>
      </section>

      {/* ── Error de lanzamiento ── */}
      {launchError && (
