        { name: "Hábil", req: "10k", item: getMcItemUrl("Diamond_Pickaxe.png"), minVal: 10000 },
        { name: "Arquitecto", req: "50k", item: getMcItemUrl("Netherite_Pickaxe.png"), minVal: 50000 },
