export function RewardsPage() {
  const { currentSession } = useAuth();
  const [config, setConfig] = useState<RoadmapDay[]>([]);
  const [activeTab, setActiveTab] = useState<number>(0);
  const [streak, setStreak] = useState<{
    currentStreak: number;
    canClaim: boolean;
    hasLegendaryAchievement: boolean;
    prestigeLevel: number;
    streakShields: number;
    lastClaimAt?: string | null;
  }>({ currentStreak: 1, canClaim: true, hasLegendaryAchievement: false, prestigeLevel: 0, streakShields: 3 });

  const [claiming, setClaiming] = useState(false);
  const [claimMsg, setClaimMsg] = useState<string | null>(null);

  useEffect(() => {
    let ignore = false;
    const fetchRoadmapData = async () => {
      try {
        const [resConfig, resStreak] = await Promise.all([
          fetch("https://api.crystaltidessmp.net/api/roadmap/config").then((r) => {
            if (!r.ok) throw new Error("Failed to fetch roadmap config");
            return r.json();
          }),
          fetch(
            `https://api.crystaltidessmp.net/api/roadmap/streak?userId=${currentSession?.id || ""}`
          ).then((r) => {
            if (!r.ok) throw new Error("Failed to fetch roadmap streak");
            return r.json();
          }),
        ]);

        if (!ignore) {
          if (resConfig.success && Array.isArray(resConfig.data)) {
            setConfig(resConfig.data);
          }
          if (resStreak.success && resStreak.data) {
            setStreak(resStreak.data);
          }
        }
      } catch {
        // Fallback offline preview config (30 días)
        if (!ignore) {
          setConfig(
            Array.from({ length: 30 }, (_, i) => ({
              day: i + 1,
              title:
                i === 29
                  ? "Día 30: 👑 JACKPOT IRIDIUM X50"
                  : i === 6
                  ? "Día 7: Cofre de Cobre"
                  : i === 13
                  ? "Día 14: Cofre de Plata"
                  : i === 20
                  ? "Día 21: Cofre de Oro"
                  : i === 27
                  ? "Día 28: Cofre Esmeralda"
                  : `Día ${i + 1}`,
              reward_type: i === 29 ? "achievement" : i % 3 === 2 ? "gacha_spin" : "killucoins",
              reward_value: (i + 1) * 25,
              multiplier: i < 7 ? 1 : i < 14 ? 2 : i < 21 ? 5 : i < 29 ? 10 : 50,
              is_jackpot: i === 29,
            }))
          );
        }
      }
    };
    fetchRoadmapData();
    return () => { ignore = true; };
  }, [currentSession]);

  const claimingRef = useRef(false);

  const handleClaim = async () => {
    if (claiming || claimingRef.current) return;
    claimingRef.current = true;
    setClaiming(true);
    setClaimMsg(null);
    try {
      const res = await fetch("https://api.crystaltidessmp.net/api/roadmap/claim", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId: currentSession?.id || "guest" }),
      });
      if (!res.ok) {
        setClaimMsg("⚠️ Error al reclamar recompensa");
        return;
      }
      const data = await res.json();
      if (data.success) {
        setClaimMsg(`🎉 ¡${data.data.message}! Nuevo Saldo: ${data.data.newBalance} KC`);
        setStreak((prev) => ({ ...prev, canClaim: false }));
      } else {
        setClaimMsg(`⚠️ ${data.message || "Error al reclamar recompensa"}`);
      }
    } catch {
      setClaimMsg("⚠️ Error de conexión al reclamar");
    } finally {
      claimingRef.current = false;
      setClaiming(false);
    }
  };

  const filterDaysByTab = (tabId: number) => {
    if (tabId === 1) return config.filter((d) => d.day >= 1 && d.day <= 7);
    if (tabId === 2) return config.filter((d) => d.day >= 8 && d.day <= 14);
    if (tabId === 3) return config.filter((d) => d.day >= 15 && d.day <= 21);
    if (tabId === 4) return config.filter((d) => d.day >= 22 && d.day <= 30);
    return config;
  };

  return (
    <div
      style={{
        padding: "24px 32px 48px",
        color: "#F8FAFC",
        height: "100%",
        maxHeight: "100%",
        overflowY: "auto",
        boxSizing: "border-box",
      }}
    >
      {/* Header Banner */}
      <div
        style={{
          padding: "24px 28px",
          borderRadius: 20,
          background: "linear-gradient(135deg, rgba(13, 148, 136, 0.35) 0%, rgba(15, 23, 42, 0.85) 100%)",
          border: "1.5px solid rgba(45, 212, 191, 0.35)",
          boxShadow: "0 12px 36px rgba(0, 0, 0, 0.4)",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          marginBottom: 20,
        }}
      >
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <Gift size={28} color="#2DD4BF" />
            <h1 style={{ margin: 0, fontSize: 24, fontWeight: 900, color: "#FFF" }}>
              Recompensas Diarias & Roadmap Mensual
            </h1>
          </div>
          <p style={{ margin: "6px 0 0", fontSize: 13, color: "rgba(255,255,255,0.75)", maxWidth: 580 }}>
            Inicia sesión cada día en el Launcher para desbloquear KilluCoins, Tiradas de Gacha y el Botín Mítico del Día 30.
          </p>
        </div>

        {/* Claim Action Box */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 8 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", justifyContent: "flex-end" }}>
            {/* Prestige Badge */}
            {streak.prestigeLevel > 0 && (() => {
              const p = getPrestigeInfo(streak.prestigeLevel);
              return (
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 6,
                    background: `${p.color}20`,
                    padding: "5px 12px",
                    borderRadius: 20,
                    border: `1px solid ${p.color}60`,
                    boxShadow: `0 0 12px ${p.color}30`,
                  }}
                >
                  <Trophy size={15} color={p.color} />
                  <span style={{ fontSize: 12, fontWeight: 800, color: p.color }}>
                    {p.name} (+{p.bonus}% KC)
                  </span>
                </div>
              );
            })()}

            {/* Streak Shield Badge */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 6,
                background: streak.streakShields > 0 ? "rgba(56, 189, 248, 0.15)" : "rgba(0,0,0,0.3)",
                padding: "5px 12px",
                borderRadius: 20,
                border: streak.streakShields > 0 ? "1px solid rgba(56, 189, 248, 0.4)" : "1px solid rgba(255,255,255,0.1)",
              }}
            >
              <Shield size={15} color={streak.streakShields > 0 ? "#38BDF8" : "rgba(255,255,255,0.4)"} />
              <span style={{ fontSize: 12, fontWeight: 800, color: streak.streakShields > 0 ? "#38BDF8" : "rgba(255,255,255,0.5)" }}>
                Escudos: {streak.streakShields}
              </span>
            </div>

            {/* Flame Racha Badge */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 6,
                background: "rgba(0,0,0,0.45)",
                padding: "5px 12px",
                borderRadius: 20,
                border: "1px solid rgba(245, 158, 11, 0.35)",
              }}
            >
              <Flame size={16} color="#F59E0B" />
              <span style={{ fontSize: 12, fontWeight: 800, color: "#F59E0B" }}>
                Racha: Día {streak.currentStreak} / 30
              </span>
            </div>
          </div>

          <button
            aria-label={streak.canClaim ? `Reclamar recompensa del día ${streak.currentStreak}` : "Recompensa de hoy ya reclamada"}
            aria-busy={claiming}
            type="button"
            onClick={handleClaim}
            disabled={!streak.canClaim || claiming}
            style={{
              padding: "12px 28px",
              borderRadius: 14,
              background: streak.canClaim
                ? "linear-gradient(135deg, #2DD4BF 0%, #0D9488 100%)"
                : "rgba(255,255,255,0.1)",
              color: streak.canClaim ? "#030712" : "rgba(255,255,255,0.4)",
              fontWeight: 900,
              fontSize: 14,
              border: "none",
              cursor: streak.canClaim ? "pointer" : "not-allowed",
              boxShadow: streak.canClaim ? "0 6px 20px rgba(45, 212, 191, 0.4)" : "none",
              display: "flex",
              alignItems: "center",
              gap: 10,
              transition: "color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease, opacity 0.2s ease",
            }}
          >
            <Sparkles size={18} aria-hidden="true" />
            {claiming
              ? "Reclamando..."
              : streak.canClaim
              ? `RECLAMAR DÍA ${streak.currentStreak}`
              : "¡RECOMPENSA DE HOY LISTA!"}
          </button>
        </div>
      </div>

      {claimMsg && (
        <div
          role="status"
          aria-live="polite"
          style={{
            padding: "12px 18px",
            borderRadius: 12,
            background: "rgba(45,212,191,0.15)",
            border: "1px solid #2DD4BF",
            color: "#2DD4BF",
            marginBottom: 20,
            fontSize: 13,
            fontWeight: 700,
          }}
        >
          {claimMsg}
        </div>
      )}

      {/* Logro Único Banner */}
      {streak.hasLegendaryAchievement && (
        <div
          style={{
            padding: 16,
            borderRadius: 16,
            background: "linear-gradient(135deg, rgba(177, 80, 179, 0.25) 0%, rgba(15, 23, 42, 0.8) 100%)",
            border: "1.5px solid #E879F9",
            display: "flex",
            alignItems: "center",
            gap: 14,
            marginBottom: 20,
          }}
        >
          <Trophy size={32} color="#E879F9" aria-hidden="true" />
          <div>
            <div style={{ fontSize: 15, fontWeight: 900, color: "#E879F9" }}>
              🏆 ¡LOGRO MÁXIMO DESBLOQUEADO: Leyenda de CrystalTides!
            </div>
            <div style={{ fontSize: 12, color: "rgba(255,255,255,0.7)", marginTop: 2 }}>
              Completaste la racha mensual perfecta. Tienes el badge dorado en tu perfil y el título exclusivo en el servidor.
            </div>
          </div>
        </div>
      )}

      {/* Selector de Semanas / Tabs */}
      <div role="tablist" aria-label="Filtrar recompensas por semana" style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 20, flexWrap: "wrap" }}>
        {WEEKS.map((w) => {
          const isActive = activeTab === w.id;
          return (
            <button
              role="tab"
              aria-selected={isActive}
              aria-label={w.label}
              type="button"
              key={w.id}
              onClick={() => setActiveTab(w.id)}
              style={{
                padding: "8px 16px",
                borderRadius: 12,
                background: isActive
                  ? "linear-gradient(135deg, rgba(45, 212, 191, 0.25) 0%, rgba(13, 148, 136, 0.4) 100%)"
                  : "rgba(15, 23, 42, 0.6)",
                border: isActive ? "1.5px solid #2DD4BF" : "1px solid rgba(255, 255, 255, 0.1)",
                color: isActive ? "#FFF" : "rgba(255, 255, 255, 0.6)",
                fontWeight: isActive ? 800 : 600,
                fontSize: 13,
                cursor: "pointer",
                display: "flex",
                alignItems: "center",
                gap: 8,
                transition: "color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease, opacity 0.2s ease",
              }}
            >
              <span aria-hidden="true">{w.icon}</span>
              <span>{w.label}</span>
            </button>
          );
        })}
      </div>

      {/* Título y Subtítulo de la vista actual */}
      <div style={{ marginBottom: 16 }}>
        <h3
          style={{
            margin: 0,
            fontSize: 16,
            fontWeight: 800,
            color: "#38BDF8",
            display: "flex",
            alignItems: "center",
            gap: 8,
          }}
        >
          <Layers size={18} /> {getWeekHeaderInfo(activeTab).title}
        </h3>
        <p style={{ margin: "4px 0 0", fontSize: 12, color: "rgba(255,255,255,0.5)" }}>
          {getWeekHeaderInfo(activeTab).desc}
        </p>
      </div>

      {/* Grid de Días Filtrados */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))", gap: 14 }}>
        {filterDaysByTab(activeTab).map((day) => {
          const isCompleted = day.day < streak.currentStreak;
          const isCurrent = day.day === streak.currentStreak;
          const isLocked = day.day > streak.currentStreak;

          const reward = getRewardInfo(day);

          return (
            <div
              key={day.day}
              style={{
                borderRadius: 16,
                padding: 14,
                background: reward.boxGradient,
                border: isCurrent
                  ? "2px solid #2DD4BF"
                  : reward.borderColor
                  ? `1.5px solid ${reward.borderColor}`
                  : "1px solid rgba(255,255,255,0.08)",
                boxShadow: isCurrent
                  ? "0 0 20px rgba(45, 212, 191, 0.35)"
                  : day.is_jackpot
                  ? "0 0 24px rgba(232, 121, 249, 0.35)"
                  : "none",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                textAlign: "center",
                position: "relative",
                opacity: isLocked ? 0.65 : 1,
                transition: "transform 0.2s ease, boxShadow 0.2s ease",
              }}
            >
              {/* Badge superior de tipo de ítem */}
              <div
                style={{
                  fontSize: 9,
                  fontWeight: 900,
                  color: reward.color,
                  letterSpacing: "0.04em",
                  marginBottom: 6,
                  background: "rgba(0,0,0,0.45)",
                  padding: "2px 8px",
                  borderRadius: 10,
                  border: `1px solid ${reward.color}40`,
                }}
              >
                {reward.badge}
              </div>

              <div style={{ fontSize: 11, fontWeight: 900, color: "rgba(255,255,255,0.6)" }}>
                DÍA {day.day}
              </div>

              {/* Imagen real del ítem / KilluCoin / Ficha de Gacha */}
              <div
                style={{
                  margin: "8px 0",
                  padding: 6,
                  borderRadius: 14,
                  background: "rgba(0,0,0,0.35)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  width: 48,
                  height: 48,
                  border: "1px solid rgba(255,255,255,0.05)",
                }}
              >
                {reward.imageSrc ? (
                  <img
                    src={reward.imageSrc}
                    alt={reward.itemTitle}
                    style={{
                      width: 38,
                      height: 38,
                      objectFit: "contain",
                      filter: "drop-shadow(0 4px 6px rgba(0,0,0,0.6))",
                    }}
                    onError={(e) => {
                      e.currentTarget.style.display = "none";
                    }}
                  />
                ) : (
                  reward.fallbackIcon
                )}
              </div>

              {/* Título de objeto */}
              <div style={{ fontSize: 12, fontWeight: 800, color: "#FFF", lineHeight: 1.2 }}>
                {reward.itemTitle}
              </div>

              {/* Subtexto / Cantidad */}
              <div style={{ fontSize: 11, fontWeight: 700, color: reward.color, marginTop: 4 }}>
                {reward.subtext}
              </div>

              {/* Multiplicador Badge */}
              {day.multiplier > 1 && !day.is_jackpot && (
                <span
                  style={{
                    marginTop: 6,
                    fontSize: 9.5,
                    fontWeight: 900,
                    background: reward.color,
                    color: "#030712",
                    padding: "1px 7px",
                    borderRadius: 8,
                  }}
                >
                  x{day.multiplier} MULTIPLICADOR
                </span>
              )}

              {/* Estado Badge (Check, ¡HOY! o Candado) */}
              <div style={{ marginTop: 10 }}>
                {isCompleted ? (
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 4,
                      color: "#10B981",
                      fontSize: 10,
                      fontWeight: 800,
                    }}
                  >
                    <CheckCircle2 size={14} /> RECLAMADO
                  </div>
                ) : isCurrent ? (
                  <div
                    style={{
                      fontSize: 10,
                      fontWeight: 900,
                      color: "#030712",
                      background: "#2DD4BF",
                      padding: "2px 10px",
                      borderRadius: 10,
                      boxShadow: "0 2px 8px rgba(45, 212, 191, 0.4)",
                    }}
                  >
                    ¡RECLAMAR HOY!
                  </div>
                ) : (
                  <div style={{ display: "flex", alignItems: "center", gap: 4, color: "rgba(255,255,255,0.35)", fontSize: 10 }}>
                    <Lock size={12} /> BLOQUEADO
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import React, { useState } from "react";
import { CrystalCard } from "./CrystalCard";
import { CrystalButton } from "./CrystalButton";
import { CrystalPageHeader } from "./CrystalPageHeader";
import { getSettings, saveSettings, type LauncherSettings } from "./mockLauncherState";
import { useAuth } from "./mockLauncherState";
import { RoleBadge } from "./RoleBadge";

const sectionStyle: React.CSSProperties = {
  display: "flex",
  flexDirection: "column",
  gap: 12,
  textAlign: "left",
};

const labelStyle: React.CSSProperties = {
  fontSize: 12,
  color: "rgba(255, 255, 255, 0.6)",
  fontWeight: 600,
  textTransform: "uppercase" as const,
  letterSpacing: 1,
};

export const SettingsPage: React.FC = () => {
  const [settings, setSettings] = useState<LauncherSettings>(() => getSettings());
  const [formConfig, setFormConfig] = useState({
    tempMaxRam: settings.maxRam / 1024,
    javaPath: settings.javaPath || "",
    width: settings.width || 1280,
    height: settings.height || 720,
    fullscreen: settings.fullscreen || false,
    autoConnect: settings.autoConnect ?? true,
    serverHost: settings.serverHost || "mc.crystaltidesSMP.net",
    serverPort: settings.serverPort || 25565,
  });

  const { tempMaxRam, javaPath, width, height, fullscreen, autoConnect, serverHost, serverPort } = formConfig;

  const setTempMaxRam = (val: number) => setFormConfig(prev => ({ ...prev, tempMaxRam: val }));
  const setJavaPath = (val: string) => setFormConfig(prev => ({ ...prev, javaPath: val }));
  const setWidth = (val: number) => setFormConfig(prev => ({ ...prev, width: val }));
  const setHeight = (val: number) => setFormConfig(prev => ({ ...prev, height: val }));
  const setFullscreen = (val: boolean) => setFormConfig(prev => ({ ...prev, fullscreen: val }));
  const setAutoConnect = (val: boolean) => setFormConfig(prev => ({ ...prev, autoConnect: val }));
  const setServerHost = (val: string) => setFormConfig(prev => ({ ...prev, serverHost: val }));
  const setServerPort = (val: number) => setFormConfig(prev => ({ ...prev, serverPort: val }));

  const [saved, setSaved] = useState(false);

  // CrystalTides Web Account state & actions
  const { crystalSession, loginCrystal, logoutCrystal } = useAuth();
  const [crystalEmail, setCrystalEmail] = useState("");
  const [crystalPassword, setCrystalPassword] = useState("");
  const [isLinking, setIsLinking] = useState(false);
  const [linkError, setLinkError] = useState<string | null>(null);

  const handleLinkCrystal = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    const cleanEmail = crystalEmail.trim();
    const cleanPassword = crystalPassword.trim();
    if (!cleanEmail || !cleanPassword) {
      setLinkError("Por favor ingresa tu correo electrónico y tu contraseña de la web.");
      return;
    }
    setIsLinking(true);
    setLinkError(null);
    try {
      await loginCrystal(cleanEmail, cleanPassword);
      setCrystalEmail("");
      setCrystalPassword("");
    } catch (err: unknown) {
      console.error("Crystal login error:", err);
      const msg = err instanceof Error ? err.message : String(err);
      setLinkError(msg || "Credenciales incorrectas o error al conectar.");
    } finally {
      setIsLinking(false);
    }
  };

  const handleSave = () => {
    const updated = saveSettings({
      ...settings,
      maxRam: tempMaxRam * 1024,
      minRam: Math.min(2048, (tempMaxRam * 1024) / 2),
      javaPath: javaPath || undefined,
      width,
      height,
      fullscreen,
      autoConnect,
      serverHost,
      serverPort,
    });
    setSettings(updated);
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  };

  const handleReset = () => {
    localStorage.removeItem("crystaltides_settings");
    const defaults = getSettings();
    setSettings(defaults);
    setFormConfig({
      tempMaxRam: defaults.maxRam / 1024,
      javaPath: "",
      width: 1280,
      height: 720,
      fullscreen: false,
      autoConnect: true,
      serverHost: "mc.crystaltidesSMP.net",
      serverPort: 25565,
    });
  };

  return (
    <div style={{ padding: 32, display: "flex", flexDirection: "column", height: "100%", boxSizing: "border-box" }}>
      <CrystalPageHeader eyebrow="Configuración" title="Ajustes del Launcher" />

      <div style={{ flex: 1, overflowY: "auto", marginTop: 24, display: "flex", flexDirection: "column", gap: 20 }}>
        {/* 🌊 Cuenta de CrystalTides Web */}
        <CrystalCard style={{ padding: 20 }} enableHoverEffect={false}>
          <div style={sectionStyle}>
            <h4 style={{ margin: 0, fontSize: 15, fontWeight: "bold", color: "#FFFFFF", display: "flex", alignItems: "center", gap: 8 }}>
              <img src="/logo.png" style={{ width: 18, height: 18, objectFit: "contain", imageRendering: "pixelated" }} alt="Logo" />
              <span>Cuenta de CrystalTides</span>
            </h4>

            {crystalSession ? (
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", backgroundColor: "rgba(45, 212, 191, 0.03)", border: "1px solid rgba(45, 212, 191, 0.15)", borderRadius: 12, padding: "14px 16px" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
                  <div style={{
                    width: 48,
                    height: 48,
                    borderRadius: 12,
                    backgroundColor: "rgba(45, 212, 191, 0.08)",
                    border: "1px solid rgba(45, 212, 191, 0.2)",
                    overflow: "hidden",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}>
                    {crystalSession.avatarUrl ? (
                      <img src={crystalSession.avatarUrl} style={{ width: "100%", height: "100%", objectFit: "cover" }} alt="Avatar" />
                    ) : (
                      <img src="/logo.png" style={{ width: 24, height: 24, objectFit: "contain" }} alt="Logo" />
                    )}
                  </div>
                  <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 2 }}>
                    <span style={{ fontWeight: 700, color: "#FFFFFF", fontSize: 14.5 }}>{crystalSession.username}</span>
                    <span style={{ fontSize: 11, color: "var(--text-muted)" }}>{crystalSession.email}</span>
                    <RoleBadge role={crystalSession.role} size="md" style={{ marginTop: 4 }} />
                  </div>
                </div>
                <button aria-label="Desvincular cuenta web de CrystalTides" type="button"
                  onClick={logoutCrystal}
                  style={{
                    background: "rgba(239, 68, 68, 0.1)",
                    border: "1px solid rgba(239, 68, 68, 0.25)",
                    color: "var(--danger)",
                    fontSize: 12,
                    fontWeight: 700,
                    cursor: "pointer",
                    padding: "8px 16px",
                    borderRadius: 8,
                    transition: "color 0.2s, background-color 0.2s, border-color 0.2s, opacity 0.2s",
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.backgroundColor = "rgba(239, 68, 68, 0.18)";
                    e.currentTarget.style.borderColor = "var(--danger)";
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.backgroundColor = "rgba(239, 68, 68, 0.1)";
                    e.currentTarget.style.borderColor = "rgba(239, 68, 68, 0.25)";
                  }}
                >
                  Desvincular Cuenta
                </button>
              </div>
            ) : (
              <div>
                <p style={{ margin: "0 0 14px 0", fontSize: 13, color: "rgba(255,255,255,0.5)", lineHeight: 1.45 }}>
                  Vincula tu cuenta de nuestra web oficial para sincronizar tu rango del servidor, participar en eventos del launcher y desbloquear características premium.
                </p>
                <div style={{ display: "flex", flexDirection: "column", gap: 12, maxWidth: 450 }}>
                  {linkError && (
                    <div style={{
                      backgroundColor: "rgba(239, 68, 68, 0.15)",
                      border: "1px solid rgba(239, 68, 68, 0.4)",
                      borderRadius: 8,
                      padding: "10px 14px",
                      color: "#FF9999",
                      fontSize: 12.5,
                      fontWeight: 600,
                      textAlign: "left",
                      lineHeight: 1.4,
                    }}>
                      ⚠️ {linkError}
                    </div>
                  )}
                  <div style={{ display: "flex", gap: 12 }}>
                    <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 4 }}>
                      <label htmlFor="settings-crystal-email" style={labelStyle}>Correo de la Web</label>
                      <input id="settings-crystal-email"
                        type="text"
                        placeholder="tu_correo@ejemplo.com"
                        value={crystalEmail}
                        onChange={(e) => setCrystalEmail(e.target.value)}
                        onKeyDown={(e) => { if (e.key === "Enter") handleLinkCrystal(); }}
                        disabled={isLinking}
                        style={{ padding: "8px 12px", fontSize: 13 }}
                      />
                    </div>
                    <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 4 }}>
                      <label htmlFor="settings-crystal-password" style={labelStyle}>Contraseña</label>
                      <input id="settings-crystal-password"
                        type="password"
                        placeholder="••••••••"
                        value={crystalPassword}
                        onChange={(e) => setCrystalPassword(e.target.value)}
                        onKeyDown={(e) => { if (e.key === "Enter") handleLinkCrystal(); }}
                        disabled={isLinking}
                        style={{ padding: "8px 12px", fontSize: 13 }}
                      />
                    </div>
                  </div>
                  <button aria-label="Conectar cuenta web"
                    type="button"
                    disabled={isLinking}
                    onClick={handleLinkCrystal}
                    style={{
                      marginTop: 4,
                      alignSelf: "flex-start",
                      fontSize: 11,
                      fontWeight: 700,
                      color: "#FFF",
                      background: "linear-gradient(135deg, #2DD4BF 0%, #0D9488 100%)",
                      border: "none",
                      borderRadius: 8,
                      padding: "8px 20px",
                      cursor: isLinking ? "not-allowed" : "pointer",
                      transition: "color 0.2s, background-color 0.2s, border-color 0.2s, opacity 0.2s",
                      boxShadow: "0 4px 12px rgba(45, 212, 191, 0.2)",
                    }}
                    onMouseEnter={(e) => {
                      if (isLinking) return;
                      e.currentTarget.style.transform = "translateY(-1px)";
                      e.currentTarget.style.boxShadow = "0 6px 16px rgba(45, 212, 191, 0.3)";
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.transform = "none";
                      e.currentTarget.style.boxShadow = "0 4px 12px rgba(45, 212, 191, 0.2)";
                    }}
                  >
                    {isLinking ? "Conectando..." : "🌊 Conectar Cuenta Web"}
                  </button>
                </div>
              </div>
            )}

            {/* Avatar Preference toggle */}
            <div style={{
              marginTop: 14,
              paddingTop: 12,
              borderTop: "1px solid rgba(255, 255, 255, 0.08)",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}>
              <div style={{ display: "flex", flexDirection: "column" }}>
                <span style={{ fontSize: 12.5, fontWeight: 700, color: "#FFF" }}>🖼️ Preferencia de Icono de Perfil</span>
                <span style={{ fontSize: 11, color: "rgba(255,255,255,0.45)" }}>Elige si prefieres mostrar tu foto de la web o la cabeza de Minecraft en el launcher</span>
              </div>
              <div style={{ display: "flex", gap: 6 }}>
                <button aria-label="Usar foto de perfil web"
                  aria-pressed={(settings.avatarPreference || "web") === "web"}
                  type="button"
                  onClick={() => {
                    const updated = saveSettings({ avatarPreference: "web" });
                    setSettings(updated);
                    window.dispatchEvent(new Event("crystaltides_settings_updated"));
                  }}
                  style={{
                    backgroundColor: (settings.avatarPreference || "web") === "web" ? "rgba(45, 212, 191, 0.2)" : "rgba(255, 255, 255, 0.04)",
                    border: `1px solid ${(settings.avatarPreference || "web") === "web" ? "#2DD4BF" : "rgba(255, 255, 255, 0.12)"}`,
                    color: (settings.avatarPreference || "web") === "web" ? "#2DD4BF" : "rgba(255, 255, 255, 0.6)",
                    fontSize: 11,
                    fontWeight: 700,
                    borderRadius: 8,
                    padding: "6px 12px",
                    cursor: "pointer",
                    transition: "color 0.15s ease, background-color 0.15s ease, border-color 0.15s ease, opacity 0.15s ease",
                  }}
                >
                  🌊 Foto Web
                </button>
                <button aria-label="Usar cabeza de Minecraft"
                  aria-pressed={settings.avatarPreference === "minecraft"}
                  type="button"
                  onClick={() => {
