  removeAccount: (accountId: string) => Promise<void>;
  logout: () => Promise<void>;
}

const DEFAULT_SAVED_ACCOUNTS: SavedAccount[] = [
  {
    id: "account_invitado",
    username: "Invitado",
    type: "microsoft",
    uuid: "069a79f4-44e9-4726-a5be-fef90e38aaf5",
