import { useEffect, Suspense, lazy } from "react"
import { Outlet, useLocation, useNavigate } from "react-router-dom"
import { useAuth } from "../../context/AuthContext"

import Navbar from "../Layout/Navbar"
import SocialSidebar from "../Layout/SocialSidebar"
import ScrollToHash from "../Utils/ScrollToHash"
import TypingBubbles from "../Effects/TypingBubbles"
import AmbientBubbles from "../Effects/AmbientBubbles"
import BroadcastAlert from "../UI/BroadcastAlert"
import Footer from "../Layout/Footer"
import CommandPalette from "../UI/CommandPalette"
import Tutorial from "../UI/Tutorial"
import { useSiteSettings } from "../../hooks/useAdminData"
import Snowfall from "../Effects/Snowfall"
import HalloweenPop from "../Effects/HalloweenPop"

const MobileBottomNav = lazy(() => import("../Layout/MobileBottomNav"))

function StatusHandler({ maintenanceActive }: { maintenanceActive: boolean }) {
    const { user, loading } = useAuth()
    const location = useLocation()
    const navigate = useNavigate()

    const isAuthorized = !!user; 

    useEffect(() => {
        if (loading) return;

        if (maintenanceActive) {
             const path = location.pathname;
             const isExempt = path === '/login' || path === '/maintenance' || path.startsWith('/admin');

             if (!isAuthorized && !isExempt) {
                 navigate('/maintenance');
             }
        } else {
            if (location.pathname === '/maintenance') {
                navigate('/');
            }
        }
    }, [maintenanceActive, isAuthorized, location, navigate, loading]);

    return null;
}

export default function RootLayout() {
    const location = useLocation()
    const { data: settings } = useSiteSettings();
    const maintenanceMode = settings?.maintenance_mode === 'true';

    useEffect(() => {
        if (!settings) return;

        // Apply Theme
        document.body.className = document.body.className.replace(/theme-\w+/g, '').trim();
        if (settings.theme && settings.theme !== 'default') {
            document.body.classList.add(`theme-${settings.theme}`);
        }
    }, [settings]);

    const isGachaPage = location.pathname === '/gacha'
    const isMaintenancePage = location.pathname === '/maintenance'
    const isAdminPage = location.pathname.startsWith('/admin')
    const isAccountPage = location.pathname.startsWith('/account')
    const isStatusPage = location.pathname === '/status'

    const showHeader = !isMaintenancePage && !isAdminPage
    const showFooter = !isAdminPage && !isMaintenancePage && !isAccountPage
    const holidayTheme = settings?.theme === 'christmas' || settings?.theme === 'halloween'
    const showBubbles = !isAccountPage && !isAdminPage && !holidayTheme
    // Sidebar overlaps the machine column on gacha — keep it off there
    const showSocialSidebar = !isAdminPage && !isAccountPage && !isStatusPage && !isGachaPage

    return (
        <>
            <StatusHandler maintenanceActive={maintenanceMode} />
            <ScrollToHash />

            {/* Accessible skip link for keyboard navigation */}
            <a
                href="#main-content"
                className="sr-only focus:not-sr-only focus:fixed focus:top-4 focus:left-4 focus:z-250 focus:px-4 focus:py-2 focus:bg-white focus:text-black focus:font-black focus:text-xs focus:uppercase focus:tracking-widest focus:rounded-xl focus:shadow-2xl focus:ring-2 focus:ring-(--accent)"
            >
                Saltar al contenido principal
            </a>

            {showHeader && (
                <>
                    <BroadcastAlert />
                    <Navbar />
                    <Suspense fallback={null}><MobileBottomNav /></Suspense>
                    {showSocialSidebar && <SocialSidebar />}
                </>
            )}

            <main id="main-content" tabIndex={-1} className="flex-1 flex flex-col w-full outline-none">
                <Outlet />
            </main>

            {showFooter && <Footer />}

            {settings?.theme === 'christmas' && !isAdminPage && <Snowfall />}
            {settings?.theme === 'halloween' && !isAdminPage && <HalloweenPop />}

            {showBubbles && (
                <>
                    <TypingBubbles />
                    <AmbientBubbles />
                </>
            )}

            <Suspense fallback={null}>
                <CommandPalette />
                <Tutorial />
            </Suspense>
        </>
    )
}

import React, { useRef, useEffect } from 'react';
import { gsap } from 'gsap';
import { useIntersectionObserver } from '../../hooks/useIntersectionObserver';

interface SectionProps {
    title?: React.ReactNode;
    headingLevel?: 'h1' | 'h2';
    children: React.ReactNode;
    delay?: number;
    direction?: 'up' | 'down' | 'left' | 'right';
    className?: string;
    id?: string;
    style?: React.CSSProperties;
    separator?: boolean;
}

const Separator = () => (
    <div className="w-full flex items-center justify-center gap-8 py-16 opacity-50 select-none pointer-events-none">
        <div className="h-px w-32 sm:w-64 bg-linear-to-r from-transparent to-(--accent)"></div>
        <div className="w-3 h-3 rotate-45 bg-(--accent) shadow-[0_0_15px_var(--accent)] animate-pulse"></div>
        <div className="h-px w-32 sm:w-64 bg-linear-to-l from-transparent to-(--accent)"></div>
    </div>
);

const OBSERVER_OPTIONS = { triggerOnce: true, threshold: 0.1 };
const DEFAULT_STYLE: React.CSSProperties = {};

export default function Section({
    title,
    headingLevel = 'h2',
    children,
    delay = 0,
    direction = 'up',
    className = '',
    id,
    style = DEFAULT_STYLE,
    separator = false
}: SectionProps) {
    const [ref, isVisible] = useIntersectionObserver<HTMLElement>(OBSERVER_OPTIONS);
    const hasAnimated = useRef(false);

    useEffect(() => {
        if (ref.current && !hasAnimated.current) {
            if (isVisible) {
                hasAnimated.current = true;
                const startY = direction === 'up' ? 30 : (direction === 'down' ? -30 : 0);
                const startX = direction === 'left' ? -30 : (direction === 'right' ? 30 : 0);

                gsap.fromTo(ref.current,
                    { opacity: 0, y: startY, x: startX },
                    {
                        opacity: 1,
                        y: 0,
                        x: 0,
                        duration: 0.8,
                        ease: 'power3.out',
                        delay: delay / 1000
                    }
                );
            } else {
                // Ensure default visibility if observer hasn't triggered yet
                gsap.set(ref.current, { opacity: 1 });
            }
        }
    }, [isVisible, delay, direction, ref]);

    if (title) {
        const HeadingTag = headingLevel;
        return (
            <section
                ref={ref}
                id={id}
                className={`w-full max-w-360 mx-auto px-4 py-16 text-center ${className}`.trim()}
                style={style}
            >
                <HeadingTag className="text-3xl md:text-4xl font-black mb-8 text-(--accent) uppercase tracking-widest drop-shadow-lg">
                    {title}
                </HeadingTag>
                <div className="relative mb-8">{children}</div>
                {separator && <Separator />}
            </section>
        )
    }

    return (
        <div
            ref={ref as React.RefObject<HTMLDivElement>}
            id={id}
            className={`w-full max-w-360 mx-auto ${className}`.trim()}
            style={style}
        >
            {children}
            {separator && <Separator />}
        </div>
    )
}

export default function SectionDivider() {
    return (
        <div className="w-full flex items-center justify-center gap-8 py-16 opacity-50 select-none pointer-events-none">
            <div className="h-px w-32 sm:w-64 bg-linear-to-r from-transparent to-(--accent)"></div>
            <div className="w-3 h-3 rotate-45 bg-(--accent) shadow-[0_0_15px_var(--accent)] animate-pulse"></div>
            <div className="h-px w-32 sm:w-64 bg-linear-to-l from-transparent to-(--accent)"></div>
        </div>
    );
}

import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Shield, Trash2, Copy, Key } from 'lucide-react';
import { use2FAStatus, useSetup2FA, useEnable2FA, useDisable2FA } from '../../../hooks/useAccountData';
import Loader from '../../UI/Loader';

interface TwoFactorSetupProps {
    mockEnabled?: boolean;
    mockLoading?: boolean;
    mockSetupData?: { secret: string; qrCode: string } | null;
    onSetup?: () => Promise<{ success: boolean; data?: { secret: string; qrCode: string }; error?: string }>;
    onEnable?: (token: string, secret: string) => Promise<{ success: boolean; error?: string }>;
    onDisable?: () => Promise<{ success: boolean; error?: string }>;
}

export default function TwoFactorSetup({ 
    mockEnabled, 
    mockLoading, 
    mockSetupData,
    onSetup,
    onEnable,
    onDisable 
}: TwoFactorSetupProps = {}) {
    const { t } = useTranslation();

    // TanStack Query
    const { data: statusData, isLoading: loadingStatus } = use2FAStatus();
    const { mutate: setup2FAMutation, isPending: isSettingUp } = useSetup2FA();
    const { mutate: enable2FAMutation, isPending: isVerifying } = useEnable2FA();
    const { mutate: disable2FAMutation, isPending: isDisabling } = useDisable2FA();

    // Local state for transitions and UI feedback
    const [setupData, setSetupData] = useState<{ secret: string; qrCode: string } | null>(mockSetupData ?? null);
    const [token, setToken] = useState('');
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');

    // Derived values
    const isActuallyEnabled = statusData?.enabled ?? false;
    const enabled = mockEnabled !== undefined ? mockEnabled : isActuallyEnabled;
    const loading = mockLoading !== undefined ? mockLoading : (loadingStatus || isSettingUp || isDisabling);
    const confirming = isVerifying;

    const handleSetup = async () => {
        setError('');

        if (onSetup) {
            try {
                const res = await onSetup();
                if (res.success && res.data) setSetupData(res.data);
                else setError(res.error || 'Failed');
            } catch { setError('Error'); }
            return;
        }

        setup2FAMutation(undefined, {
            onSuccess: (data) => setSetupData(data),
            onError: (err: Error) => setError(err.message)
        });
    };

    const handleEnable = async () => {
        if(!setupData) return;
        setError('');

        if (onEnable) {
            try {
                const res = await onEnable(token, setupData.secret);
                if (res.success) {
                    setSetupData(null);
                    setSuccess(t('account.security.2fa_enabled', '2FA Enabled Successfully!'));
                } else setError(res.error || 'Invalid code');
            } catch { setError('Error'); }
            return;
        }

        enable2FAMutation({ token, secret: setupData.secret }, {
            onSuccess: () => {
                setSetupData(null);
                setToken('');
                setSuccess(t('account.security.2fa_enabled', '2FA Enabled Successfully!'));
            },
            onError: (err: Error) => setError(err.message)
        });
    };

    const handleDisable = async () => {
        if(!confirm(t('account.security.2fa_disable_confirm', 'Are you sure you want to disable 2FA?'))) return;
        setError('');

        if (onDisable) {
            try {
                const res = await onDisable();
                if (res.success) {
                    setSuccess(t('account.security.2fa_disabled', '2FA Disabled'));
                } else setError(res.error || 'Failed');
            } catch { setError('Error'); }
            return;
        }

        disable2FAMutation(undefined, {
            onSuccess: () => {
                setSuccess(t('account.security.2fa_disabled', '2FA Disabled'));
            },
            onError: (err: Error) => setError(err.message)
        });
    };

    if (loading) return <Loader />;

    return (
        <div className="security-card" style={{ background: 'rgba(255,255,255,0.03)', padding: '1.5rem', borderRadius: '12px', border: '1px solid rgba(255,255,255,0.05)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1rem' }}>
                <div style={{ background: 'rgba(59, 130, 246, 0.2)', color: '#3b82f6', padding: '10px', borderRadius: '50%' }}>
                    <Shield size={20} />
                </div>
                <div>
                    <h3 style={{ margin: 0, color: '#fff' }}>{t('account.security.2fa_title', 'Two-Factor Authentication')}</h3>
                    <p style={{ margin: '4px 0 0', color: '#888', fontSize: '0.9rem' }}>
                        {enabled 
                            ? t('account.security.2fa_active', 'Your account is secured with 2FA.') 
                            : t('account.security.2fa_inactive', 'Add an extra layer of security to your account.')}
                    </p>
                </div>
            </div>

            {error && <div style={{ color: '#ef4444', background: 'rgba(239, 68, 68, 0.1)', padding: '0.8rem', borderRadius: '8px', marginBottom: '1rem', fontSize: '0.9rem' }}>{error}</div>}
            {success && <div style={{ color: '#10b981', background: 'rgba(16, 185, 129, 0.1)', padding: '0.8rem', borderRadius: '8px', marginBottom: '1rem', fontSize: '0.9rem' }}>{success}</div>}

            {!enabled && !setupData && (
                <button type="button" 
                    onClick={handleSetup}
                    disabled={loading}
                    className="btn-primary"
                    style={{ 
                        background: 'var(--accent)', 
                        color: '#000', 
                        fontWeight: 'bold', 
                        display: 'flex', 
                        justifyContent: 'center', 
                        alignItems: 'center',
                        padding: '0.8rem 1.5rem',
                        borderRadius: '8px',
                        border: 'none',
                        cursor: loading ? 'not-allowed' : 'pointer',
                        width: '100%',
                        transition: "color 0.2s, background-color 0.2s, border-color 0.2s, opacity 0.2s",
                        opacity: loading ? 0.7 : 1
                    }}
                >
                    {loading ? <Loader minimal /> : t('account.security.setup_2fa', 'Setup 2FA')}
                </button>
            )}

            {!enabled && setupData && (
                <div className="setup-box animate-fade-in" style={{ marginTop: '1rem', background: 'rgba(0,0,0,0.2)', padding: '1.5rem', borderRadius: '8px' }}>
                    <h4 style={{ color: '#fff', marginBottom: '1rem' }}>1. {t('account.security.scan_qr', 'Scan QR Code')}</h4>
                    <div style={{ 
                        position: 'relative', 
                        background: '#fff', 
                        padding: '10px', 
                        borderRadius: '12px', 
                        width: 'fit-content', 
                        marginBottom: '1.5rem',
                        boxShadow: '0 10px 30px rgba(0,0,0,0.5)',
                        margin: '0 auto'
                    }}>
                        <img src={setupData.qrCode} alt="2FA QR" style={{ width: '180px', height: '180px', display: 'block' }} />
                        {/* Centered Logo Overlay */}
                        <div style={{
                            position: 'absolute',
                            top: '50%',
                            left: '50%',
                            transform: 'translate(-50%, -50%)',
                            width: '44px',
                            height: '44px',
                            background: '#fff',
                            borderRadius: '50%',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            boxShadow: '0 0 10px rgba(0,0,0,0.1)',
                            border: '2px solid #fff'
                        }}>
                            <img 
                                src="/images/ui/logo.webp" 
                                alt="LT" 
                                style={{ width: '32px', height: '32px', objectFit: 'contain' }} 
                            />
                        </div>
                    </div>

                    <div style={{ marginTop: '1.5rem', borderTop: '1px solid rgba(255,255,255,0.1)', paddingTop: '1rem' }}>
                        <p style={{ color: '#aaa', fontSize: '0.85rem', marginBottom: '0.5rem', display: 'flex', alignItems: 'center', gap: '6px' }}>
                            <Key size={12} /> {t('account.security.cant_scan', "Can't scan the QR code?")}
                        </p>

                        <button
                            type="button"
                            onClick={() => {
                                navigator.clipboard.writeText(setupData.secret);
