import React, { useState, useRef } from 'react';
import { Upload, Loader2 } from 'lucide-react';
import { uploadImage, ImageBucket } from '../../services/uploadService';

interface ImageUploaderProps {
    onImageUploaded: (url: string) => void;
    currentImage?: string;
    bucketName?: ImageBucket;
    folderPath?: string;
    className?: string;
}

const processImage = async (file: File): Promise<Blob> => {
    const objectUrl = URL.createObjectURL(file);
    return await new Promise<Blob>((resolve, reject) => {
        const img = new Image();
        img.onerror = () => {
            URL.revokeObjectURL(objectUrl);
            reject(new Error('Image load failed'));
        };
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const MAX_WIDTH = 512;
            const MAX_HEIGHT = 512;
            let width = img.width;
            let height = img.height;

            if (width > height) {
                if (width > MAX_WIDTH) {
                    height *= MAX_WIDTH / width;
                    width = MAX_WIDTH;
                }
            } else {
                if (height > MAX_HEIGHT) {
                    width *= MAX_HEIGHT / height;
                    height = MAX_HEIGHT;
                }
            }

            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            if (!ctx) {
                URL.revokeObjectURL(objectUrl);
                reject(new Error('Canvas context failed'));
                return;
            }
            ctx.drawImage(img, 0, 0, width, height);
            canvas.toBlob((blob) => {
                URL.revokeObjectURL(objectUrl);
                if (blob) resolve(blob);
                else reject(new Error('Conversion failed'));
            }, 'image/webp', 0.85);
        };
        img.src = objectUrl;
    });
};

export default function ImageUploader({
    onImageUploaded,
    currentImage,
    bucketName = 'content',
    folderPath = 'uploads',
    className = ''
}: ImageUploaderProps) {
    // const { t } = useTranslation();
    const [uploading, setUploading] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setUploading(true);
        try {
            const webpBlob = await processImage(file);
            // Server-validated upload (magic bytes checked in backend)
            const publicUrl = await uploadImage(webpBlob, bucketName, folderPath);
            onImageUploaded(publicUrl);
        } catch (error) {
            console.error('Upload failed:', error);
            alert('Error al subir imagen. Verifica permisos o consola.');
        } finally {
            setUploading(false);
            if (fileInputRef.current) fileInputRef.current.value = '';
        }
    };

    return (
        <div className={`image-uploader ${className}`} style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
            <button
                type="button"
                className="uploader-preview"
                style={{
                    width: '64px',
                    height: '64px',
                    borderRadius: '12px',
                    background: 'rgba(0,0,0,0.3)',
                    border: '1px dashed rgba(255,255,255,0.2)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    cursor: 'pointer',
                    overflow: 'hidden',
                    position: 'relative',
                    padding: 0
                }}
                onClick={() => fileInputRef.current?.click()}
            >
                {uploading ? (
                    <Loader2 className="animate-spin text-white/50" size={20} />
                ) : currentImage ? (
                    <img src={currentImage} alt="Uploaded" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                ) : (
                    <Upload size={20} className="text-white/30" />
                )}
            </button>
            <input aria-label="Input field" 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                accept="image/*" 
                style={{ display: 'none' }} 
            />
            <button aria-label="Action" 
                type="button" 
                onClick={() => fileInputRef.current?.click()}
                className="text-xs text-white/50 hover:text-white underline text-left"
            >
                {currentImage ? 'Cambiar Imagen' : 'Subir Imagen (WebP)'}
            </button>
        </div>
    );
}

import React from 'react';

interface MarkdownRendererProps {
    content: string;
}

/**
 * A basic markdown-like renderer that handles:
 * - Images: ![alt](url)
 * - Links: [text](url)
 * - Bold: **text**
 * - Italic: *text* (added)
 * - Line breaks
 *
 * Security: URLs go through a PROTOCOL WHITELIST (never a blacklist).
 * Control chars and whitespace are stripped before validation, which kills
 * obfuscation bypasses like "java\tscript:" or "java\nscript:".
 */
const sanitizeUrl = (rawUrl: string): string | null => {
    // Strip control chars and ALL whitespace (tabs/newlines defeat prefix checks)
    // eslint-disable-next-line no-control-regex -- intentionally stripping control chars
    const cleaned = rawUrl.replace(/[\u0000-\u0020\u007F]+/g, '');
    // Allow relative paths and anchors
    if (cleaned.startsWith('/') || cleaned.startsWith('#')) return cleaned;
    // Allow only http/https absolute URLs
    if (/^https?:\/\//i.test(cleaned)) return cleaned;
    // Everything else (javascript:, data:, vbscript:, protocol-relative, ...) is rejected
    return null;
};

const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({ content }) => {
    if (!content) return null;

    // Regular expression to find Markdown-like patterns
    // 1. Images: !\[(.*?)\]\((.*?)\)
    // 2. Links: \[(.*?)\]\((.*?)\)
    // 3. Bold: \*\*(.*?)\*\*
    // 4. Italic: \*(.*?)\*

    const parts = content.split(/(!\[.*?\]\(.*?\)|\[.*?\]\(.*?\)|(?:\*\*[^*]+\*\*)|(?:\*[^*]+\*))/g);
    const seenCounts = new Map<string, number>();

    return (
        <>
            {parts.map((part) => {
                const count = (seenCounts.get(part) || 0) + 1;
                seenCounts.set(part, count);
                const partId = `md_${part.length}_${count}_${part.slice(0, 12)}`;

                // Images
                if (part.startsWith('![')) {
                    const match = part.match(/!\[(.*?)\]\((.*?)\)/);
                    if (match) {
                        const safeUrl = sanitizeUrl(match[2]);
                        // Rejected protocol -> render nothing (don't emit the URL at all)
                        if (!safeUrl) return null;
                        return (
                            <img
                                key={partId}
                                src={safeUrl}
                                alt={match[1]}
                                style={{ maxWidth: '100%', borderRadius: '8px', margin: '0.5rem 0', display: 'block' }}
                            />
                        );
                    }
                }

                // Links
                if (part.startsWith('[')) {
                    const match = part.match(/\[(.*?)\]\((.*?)\)/);
                    if (match) {
                        const safeUrl = sanitizeUrl(match[2]);
                        // Rejected protocol -> render the text without the link
                        if (!safeUrl) {
                            console.warn('Blocked potentially malicious URL:', match[2]);
                            return <span key={partId}>{match[1]}</span>;
                        }

                        return (
                            <a
                                key={partId}
                                href={safeUrl}
                                target="_blank"
                                rel="noopener noreferrer"
                                style={{ color: 'var(--accent)', textDecoration: 'underline' }}
                            >
                                {match[1]}
                            </a>
                        );
                    }
                }

                // Bold
                if (part.startsWith('**') && part.endsWith('**')) {
                    return <strong key={partId}>{part.slice(2, -2)}</strong>;
                }

                // Italic
                if (part.startsWith('*') && part.endsWith('*')) {
                    return <em key={partId}>{part.slice(1, -1)}</em>;
                }

                // Normal Text with preserved line breaks
                return (
                    <span key={partId} style={{ whiteSpace: 'pre-wrap' }}>
                        {part}
                    </span>
                );
            })}
        </>
    );
};

export default MarkdownRenderer;

