                                key={step}
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: -20 }}
                                transition={{ duration: 0.2 }}
                            >
                                <div style={{ marginBottom: '1.5rem', height: '80px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                    {STEPS[step].icon}
                                </div>
                                <h2 style={{ marginBottom: '1rem', color: '#fff', fontSize: '1.8rem' }}>
                                    {STEPS[step].title}
                                </h2>
                                <p style={{ color: '#aaa', lineHeight: '1.6', marginBottom: '2.5rem', minHeight: '60px' }}>
                                    {STEPS[step].content}
                                </p>
                            </Motion.div>
                        </AnimatePresence>

                        {/* Action Buttons */}
                        <div style={{ display: 'flex', gap: '1rem', flexDirection: 'column' }}>
                            <div style={{ display: 'flex', gap: '1rem', width: '100%' }}>
                                {step > 0 && (
                                    <button type="button" 
                                        className="btn-secondary"
                                        onClick={prevStep}
                                        style={{
                                            padding: '0.8rem',
                                            fontSize: '0.95rem',
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            gap: '0.5rem',
                                            background: 'rgba(255,255,255,0.08)',
                                            border: '1px solid rgba(255,255,255,0.15)',
                                            color: '#fff',
                                            borderRadius: '8px',
                                            cursor: 'pointer',
                                            flex: 1,
                                            fontWeight: '600',
                                            transition: "color 0.2s, background-color 0.2s, border-color 0.2s, opacity 0.2s",
                                            textTransform: 'uppercase',
                                            letterSpacing: '0.5px'
                                        }}
                                    >
                                        <ArrowLeft size={10} /> {t('tutorial.back')}
                                    </button>
                                )}

                                <button aria-label="Action" type="button" 
                                    className="btn-primary"
                                    onClick={() => {
                                        if (step < STEPS.length - 1) {
                                            nextStep();
                                        } else {
                                            handleClose();
                                        }
                                    }}
                                    style={{
                                        padding: '0.8rem',
                                        fontSize: '0.95rem',
                                        display: 'flex',
                                        alignItems: 'center',
                                        justifyContent: 'center',
                                        gap: '0.8rem',
                                        flex: 2,
                                        borderRadius: '8px',
                                        fontWeight: '800',
                                        textTransform: 'uppercase',
                                        letterSpacing: '0.5px',
                                        boxShadow: '0 4px 15px rgba(0,0,0,0.2)'
                                    }}
                                >
                                    {STEPS[step].action} <ArrowRight size={12} />
                                </button>
                            </div>

                             {/* Register Link Button (Always visible or just on last step? "botón que lleve a register" implying an alternative or final call to action) */}
                             {/* Only showing prominently on the last step or as a secondary option always? Let's put it on the last step as a strong CTA */}

                             {step === STEPS.length - 1 && (
                                <button type="button"
                                    onClick={handleRegister}
                                    style={{
                                        background: 'transparent',
                                        border: '1px solid var(--accent)',
                                        color: 'var(--accent)',
                                        padding: '0.8rem',
                                        borderRadius: 'var(--radius)',
                                        cursor: 'pointer',
                                        fontWeight: 'bold',
                                        display: 'flex',
                                        alignItems: 'center',
                                        justifyContent: 'center',
                                        gap: '0.5rem',
                                        marginTop: '0.5rem'
                                    }}
                                >
                                    <UserPlus /> {t('navbar.register') || "Registrarse"}
                                </button>
                             )}
                        </div>

                    </Motion.div>
                </div>
            )}
        </AnimatePresence>
    );
}

import { Suspense, lazy } from 'react';
import { Trophy } from 'lucide-react';
import Loader from '../UI/Loader';
import { useTranslation } from 'react-i18next';

const PlaystyleRadar = lazy(() => import('../Account/PlaystyleRadarFinal'));

interface PlayerStats {
  playtime: string;
  kills: number;
  mob_kills: number;
  deaths: number;
  money: string;
  blocks_mined: string;
  blocks_placed: string;
  rank?: string;
}

interface PlayerStatsGridProps {
  stats: PlayerStats | null;
  loading: boolean;
  isPublic: boolean;
  isAdmin: boolean;
}

// Helper to parse playtime "12h 30m"
const parsePlaytime = (ptStr: string): number => {
  if (!ptStr) return 0;
  let hours = 0;
  for (const part of ptStr.trim().split(/\s+/)) {
    if (part.endsWith('h')) {
      hours += Number.parseFloat(part.slice(0, -1)) || 0;
    } else if (part.endsWith('m')) {
      hours += (Number.parseFloat(part.slice(0, -1)) || 0) / 60;
    }
  }
  return hours;
};

const parseMoney = (moneyStr: string): number => {
  if (!moneyStr) return 0;
  return Number.parseFloat(moneyStr.replace(/[^0-9.-]+/g, '')) || 0;
};

export default function PlayerStatsGrid({
  stats,
  loading,
  isPublic,
  isAdmin,
}: PlayerStatsGridProps) {
  const { t } = useTranslation();

  return (
    <div className="rounded-3xl border border-white/10 bg-white/5 p-8 shadow-xl backdrop-blur-md transition-colors hover:border-white/20 hover:shadow-2xl">
      <h3 className="mb-6 flex items-center gap-3 text-sm font-black uppercase tracking-widest text-white/40">
        <Trophy size={16} /> {t('profile.playstyle_title', 'Gráfico de Estilo')}
      </h3>

      {isPublic || isAdmin ? (
        <div className="flex flex-col items-center">
          {loading ? (
            <div className="py-12">
              <Loader text={t('profile.loading_stats')} />
            </div>
          ) : stats ? (
            <>
              <div className="h-[220px] w-full">
                <Suspense
                  fallback={
                    <div className="flex h-full items-center justify-center">
                      <Loader />
                    </div>
                  }
                >
                  <PlaystyleRadar
                    stats={{
                      blocksPlaced: Number(stats.blocks_placed || 0),
                      blocksMined: Number(stats.blocks_mined || 0),
                      kills: Number(stats.kills || 0),
                      mobKills: Number(stats.mob_kills || 0),
                      playtimeHours: parsePlaytime(stats.playtime),
                      money: parseMoney(stats.money),
                      rank: stats.rank || 'default',
                    }}
                  />
                </Suspense>
              </div>
            </>
          ) : (
            <div className="py-8 text-center text-xs font-bold italic text-gray-500">
              {t('profile.error_stats', 'No se pudieron cargar los datos de estilo.')}
            </div>
          )}
        </div>
      ) : (
        <div className="rounded-2xl border border-dashed border-white/5 bg-black/20 px-6 py-12 text-center">
          <div className="mb-2 text-2xl opacity-30">🔒</div>
          <p className="text-xs font-bold text-gray-500">
            {t('profile.private_stats', 'Este usuario mantiene su estilo de juego en privado.')}
          </p>
        </div>
      )}
    </div>
  );
}

import { m as motion } from "framer-motion"
