    reputation?: number;
    avatar_preference?: 'minecraft' | 'social';
    status_message?: string;
    full_name?: string;
    social_avatar_url?: string;
    minecraft_nick?: string;
}

interface User {
    id: string;
    user_metadata?: {
        full_name?: string;
        username?: string;
        status_message?: string;
    };
}

interface ProfileHeaderProps {
    profile: Profile;
    currentUser: User | null;
    onGiveKarma: () => void;
    givingKarma: boolean;
