                    {(searchTerm || selectedMod !== 'all' || selectedTab !== 'all') && (
                        <button
                            type="button"
                            onClick={() => {
                                setSelectedTab('all')
                                setSelectedMod('all')
                                setSearchTerm('')
                            }}
                            className="text-teal-400 hover:text-teal-300 font-bold hover:underline cursor-pointer"
                        >
