}

// Like Button Component with Magic Particles
const LikeButton = ({ articleId }: { articleId: string | number }) => {
  const [likes, setLikes] = useState(() => {
    const saved = localStorage.getItem(`like_v1_${articleId}`);
    return saved ? Number.parseInt(saved, 10) : Math.floor(Math.random() * 40) + 15;
  });
  const [isLiked, setIsLiked] = useState(() => {
    return localStorage.getItem(`is_liked_v1_${articleId}`) === 'true';
  });
  const [particles, setParticles] = useState<Particle[]>([]);

  const handleLike = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    const newLiked = !isLiked;
    setIsLiked(newLiked);
    const newLikesCount = newLiked ? likes + 1 : likes - 1;
    setLikes(newLikesCount);
    localStorage.setItem(`is_liked_v1_${articleId}`, String(newLiked));
    localStorage.setItem(`like_v1_${articleId}`, String(newLikesCount));

    if (newLiked) {
      const newParticles: Particle[] = [];
      const emojis = ['💎', '✨', '💙', '👑'];
      for (let i = 0; i < 6; i++) {
        newParticles.push({
          id: Date.now() + i,
          x: (Math.random() - 0.5) * 80,
          y: -(Math.random() * 60 + 30),
          emoji: emojis[Math.floor(Math.random() * emojis.length)],
          rotate: (Math.random() - 0.5) * 90,
        });
      }
      setParticles(newParticles);
      setTimeout(() => setParticles([]), 800);
    }
  };

  return (
    <div className="relative inline-block">
      <button
        aria-label="Action"
        type="button"
        onClick={handleLike}
        className={`flex items-center gap-2 rounded-full border px-4 py-2 text-xs font-black transition-colors ${isLiked ? 'bg-(--accent)/25 text-(--accent) border-(--accent)/40 shadow-(--accent)/10 scale-105 shadow-lg' : 'border-white/10 bg-white/5 text-gray-400 hover:bg-white/10 hover:text-white'}`}
      >
        <span className="text-sm leading-none">{isLiked ? '💙' : '🤍'}</span>
        <span>{likes}</span>
      </button>

      {/* Particles */}
      <AnimatePresence>
        {particles.map((p) => (
          <motion.span
            key={p.id}
            initial={{ opacity: 1, scale: 0.6, x: 0, y: 0 }}
            animate={{
              opacity: 0,
              scale: [1, 1.3, 0.7],
              x: p.x,
              y: p.y,
              rotate: p.rotate,
            }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.8, ease: 'easeOut' }}
            className="pointer-events-none absolute left-1/2 top-0 z-50 -ml-2 text-sm"
          >
            {p.emoji}
          </motion.span>
        ))}
      </AnimatePresence>
    </div>
  );
};

