// Countdown Timer Component
const CountdownTimer = ({ targetDate }: { targetDate: Date }) => {
  const [timeLeft, setTimeLeft] = useState({
    days: 0,
    hours: 0,
    minutes: 0,
    seconds: 0,
  });

  useEffect(() => {
    const updateTimer = () => {
      const difference = targetDate.getTime() - Date.now();
      if (difference <= 0) {
        setTimeLeft({ days: 0, hours: 0, minutes: 0, seconds: 0 });
        return;
      }
      const days = Math.floor(difference / (1000 * 60 * 60 * 24));
      const hours = Math.floor((difference / (1000 * 60 * 60)) % 24);
      const minutes = Math.floor((difference / 1000 / 60) % 60);
      const seconds = Math.floor((difference / 1000) % 60);
      setTimeLeft({ days, hours, minutes, seconds });
    };

    updateTimer();
    const interval = setInterval(updateTimer, 1000);
    return () => clearInterval(interval);
  }, [targetDate]);

  return (
    <div className="flex w-full items-center justify-center gap-2 rounded-2xl border border-white/10 bg-white/5 px-4 py-2.5 font-mono text-sm text-white">
      <div className="flex flex-col items-center">
        <span className="text-sm font-black leading-none">
          {String(timeLeft.days).padStart(2, "0")}
        </span>
        <span className="mt-0.5 text-[8px] font-black uppercase text-gray-500">
          d
        </span>
      </div>
      <span className="animate-pulse font-black text-gray-600">:</span>
      <div className="flex flex-col items-center">
        <span className="text-sm font-black leading-none">
          {String(timeLeft.hours).padStart(2, "0")}
        </span>
        <span className="mt-0.5 text-[8px] font-black uppercase text-gray-500">
          h
        </span>
      </div>
      <span className="animate-pulse font-black text-gray-600">:</span>
      <div className="flex flex-col items-center">
        <span className="text-sm font-black leading-none">
          {String(timeLeft.minutes).padStart(2, "0")}
        </span>
        <span className="mt-0.5 text-[8px] font-black uppercase text-gray-500">
          m
        </span>
      </div>
      <span className="animate-pulse font-black text-gray-600">:</span>
      <div className="text-(--accent) flex flex-col items-center">
        <span className="text-sm font-black leading-none">
          {String(timeLeft.seconds).padStart(2, "0")}
        </span>
        <span className="text-(--accent)/50 mt-0.5 text-[8px] font-black uppercase">
          s
        </span>
      </div>
    </div>
  );
};

const getEventDates = (event: ContestEvent) => {
  const now = new Date();
  if (event.status === "active") {
    const endDate = event.end_date
      ? new Date(event.end_date)
      : new Date(now.getTime() + 2 * 24 * 60 * 60 * 1000 + 4 * 60 * 60 * 1000);
    return { label: "Finaliza en:", date: endDate };
  } else if (event.status === "soon") {
    const startDate = event.start_date
      ? new Date(event.start_date)
      : new Date(now.getTime() + 5 * 24 * 60 * 60 * 1000 + 12 * 60 * 60 * 1000);
    return { label: "Comienza en:", date: startDate };
  }
  return null;
};

const getEventWinners = (event: ContestEvent) => {
  if (event.winners && event.winners.length > 0) return event.winners;
  if (event.type === "hammer") return ["pixiesixer", "Zeta", "Churly"];
  if (event.type === "dice") return ["SendPles", "Lawchihuahua", "ZenXeone"];
  if (event.type === "map") return ["Neroferno", "Killu", "Nana_Fubuki"];
  return ["Churly", "Zeta", "SendPles"];
};

