                                        <span className="text-lg font-black text-white">{cat.posts}</span>
                                        <span className="text-[10px] text-gray-500 uppercase tracking-widest">{t('forum_page.stats.posts')}</span>
                                    </div>
                                </div>
                            </div>

                             {/* Last Post (Desktop styles can be enhanced, simplified here for mobile compat) */}
                             <div className="hidden xl:flex flex-col justify-center items-end text-right min-w-30 text-xs text-gray-500 border-l border-white/5 pl-6 ml-2">
                                <div className="flex items-center gap-2 mb-1 text-gray-300">
                                    <User className="text-(--accent)/50 text-[10px]" /> {cat.lastPost.user}
                                </div>
                                <div className="flex items-center gap-2">
                                    <Clock className="text-(--accent)/50 text-[10px]" /> {cat.lastPost.date}
                                </div>
                             </div>
                        </Link>
                    ))}
                </div>
            </Section>
        </div>
    )
}

import { useParams, Link } from "react-router-dom"
import { User, MessageSquare, Clock, Pen, Pin, ArrowLeft } from "lucide-react"
import Loader from "../components/UI/Loader"
import { useTranslation } from 'react-i18next'
import Section from "../components/Layout/Section"
import { useQuery } from "@tanstack/react-query"

interface ThreadSummary {
    id: string | number;
    title: string;
    author: string;
    replies: number;
    views: number;
    lastActivity: string;
    pinned: boolean;
    tag: string | null;
    slug?: string;
}

interface NewsResponse {
    id: string | number;
    title: string;
    replies?: number;
    views?: number;
    created_at: string;
    category: string | null;
    status: string;
    slug?: string;
}

interface ThreadResponse {
    id: string | number;
    title: string;
    author_name?: string;
    reply_count?: number;
    views?: number;
    created_at: string;
    pinned?: boolean;
    slug?: string;
}

const categorySlugs = {
    "announcements": 1,
    "general": 2,
    "support": 3,
    "off-topic": 4
}

const categoryTranslationKeys: Record<string, string> = {
    "announcements": "announcements",
    "1": "announcements",
    "news": "announcements",
    "general": "general",
    "2": "general",
    "support": "support",
    "3": "support",
    "off-topic": "offtopic",
    "4": "offtopic"
}

export default function ForumCategory() {
    const { id: slug } = useParams<{ id: string }>()
    const { t } = useTranslation()
    const API_URL = import.meta.env.VITE_API_URL
    const categoryId = slug ? (categorySlugs[slug as keyof typeof categorySlugs] || slug) : null;
    const translationKey = slug ? categoryTranslationKeys[slug] : null;
    const categoryTitle = translationKey ? t(`forum_page.categories.${translationKey}.title`) : t('forum_page.categories.general.title')

    const isNewsCategory = String(categoryId) === "1"

    const { data: threads = [], isLoading: loading } = useQuery<ThreadSummary[]>({
        queryKey: ['forumCategoryThreads', categoryId, isNewsCategory, API_URL],
        queryFn: async () => {
            if (!categoryId) return [];
            if (isNewsCategory) {
                const res = await fetch(`${API_URL}/news`);
                if (!res.ok) throw new Error('Failed to fetch news');
                const data = await res.json();
                return Array.isArray(data)
                    ? (data as NewsResponse[]).reduce<ThreadSummary[]>((acc, n) => {
                        if (n.status === 'Published') {
                            acc.push({
                                id: n.id,
                                title: n.title,
                                author: "Staff",
                                replies: n.replies || 0,
                                views: n.views || 0,
                                lastActivity: new Date(n.created_at).toLocaleDateString(),
                                pinned: true,
                                tag: "NEWS",
                                slug: n.slug || `news-${n.id}`
                            });
                        }
                        return acc;
                    }, []) : [];
            } else {
                const res = await fetch(`${API_URL}/forum/category/${categoryId}`);
                if (!res.ok) throw new Error('Failed to fetch threads');
                const data = await res.json();
                return Array.isArray(data) ? (data as ThreadResponse[]).map((t) => ({
                    id: t.id,
                    title: t.title,
                    author: t.author_name || "Aventurero",
                    replies: t.reply_count || 0,
                    views: t.views || 0,
                    lastActivity: new Date(t.created_at).toLocaleDateString(),
                    pinned: t.pinned || false,
                    tag: null,
                    slug: t.slug
                })) : [];
            }
        },
        enabled: Boolean(categoryId),
        staleTime: 30_000,
    });

    return (
        <div className="pt-24 min-h-screen">
            <Section title={categoryTitle}>
                <div className="max-w-4xl mx-auto">
                    {/* Header Controls */}
                    <div className="flex justify-between items-center mb-8 bg-black/40 backdrop-blur-md p-4 rounded-2xl border border-white/5">
                        <Link 
                            to="/forum" 
                            className="flex items-center gap-2 text-gray-400 hover:text-(--accent) transition-colors text-sm font-bold uppercase tracking-widest"
                        >
                            <ArrowLeft /> {t('forum_category.back_link')}
                        </Link>

                        {String(categoryId) !== "1" && (
                            <Link 
                                to="/forum/create" 
                                className="flex items-center gap-2 px-6 py-3 bg-(--accent) text-black rounded-xl text-xs font-black uppercase tracking-widest hover:scale-105 transition-transform shadow-lg shadow-(--accent)/20"
                            >
                                <Pen /> {t('forum_category.new_thread')}
                            </Link>
                        )}
                    </div>

                    {/* Content */}
                    {loading ? (
                        <div className="py-20 flex flex-col items-center justify-center gap-4">
                            <div className="w-12 h-12 border-4 border-white/10 border-t-(--accent) rounded-full animate-spin"></div>
                            <Loader text={t('forum_category.loading')} />
                        </div>
                    ) : threads.length === 0 ? (
                        <div className="py-20 flex flex-col items-center justify-center gap-6 bg-white/2 border border-dashed border-white/10 rounded-3xl">
                            <MessageSquare className="text-6xl text-white/10" />
                            <div className="text-center">
                                <p className="text-gray-400 font-medium mb-4">{t('forum_category.no_threads')}</p>
                                {String(categoryId) !== '1' && (
                                    <Link 
                                        to="/forum/create" 
                                        className="text-(--accent) font-bold hover:underline"
                                    >
                                        {t('forum_category.be_first')}
                                    </Link>
                                )}
                            </div>
                        </div>
                    ) : (
                        <div className="flex flex-col gap-4">
                            {threads.map(thread => (
                                <Link 
                                    to={String(categoryId) === "1" ? `/forum/thread/news/${thread.slug || thread.id}` : `/forum/thread/topic/${thread.slug || thread.id}`} 
                                    key={thread.id} 
                                    className="group block"
                                >
                                    <div className="bg-black/40 backdrop-blur-xl border border-white/5 rounded-2xl p-6 flex items-center gap-6 transition-colors duration-300 hover:bg-white/5 hover:border-(--accent)/30 hover:-translate-y-1 hover:shadow-xl hover:shadow-(--accent)/5">

                                        {/* Icon */}
                                        <div className={`w-12 h-12 rounded-full flex items-center justify-center text-xl shrink-0 ${thread.pinned ? 'bg-(--accent)/10 text-(--accent)' : 'bg-white/5 text-gray-500 group-hover:bg-white/10 group-hover:text-gray-300'}`}>
                                            {thread.pinned ? <Pin className="rotate-45" /> : <MessageSquare />}
                                        </div>

                                        {/* Info */}
                                        <div className="grow min-w-0">
                                            <div className="flex items-center gap-3 mb-2">
                                                {thread.tag && (
