                    ) : tier.id === 'ultra' ? (
                      <span className="event-only-badge">{t('gacha.event_only')}</span>
                    ) : (
                      <>{formatCost(tier.cost)}</>
                    )}
                  </div>
                </div>
                {isLocked && <Lock className="lock-icon" size={14} />}
