            />
          </div>

          <div id="gacha_machine_area" className="gacha-game-layout">
            <GachaMachine
              reelItemsSet={reelItemsSet}
              reelRefs={reelRefs as unknown as React.RefObject<HTMLDivElement>[]}
              isOpening={isOpening}
              RARITY_ICONS={RARITY_ICONS}
