            type="button"
            onClick={() => onLike(hero.id)}
            className="flex items-center gap-2 px-5 py-3.5 rounded-2xl bg-white/10 text-xs font-bold text-gray-300 hover:bg-white/20 transition-colors cursor-pointer"
